    if (car >= 1 && tl < 120) goHome = true;
  }

  // ===== DELIVERY (highest priority, cannot be overridden by site detection) =====
  if (goHome || mem.mode === 'deliver') {
    mem.mode = 'deliver';

    if (car === 0 && (obs.docked || bDist < 5)) {
      mem.cl = 0; mem.cr = 0;
      if (tl > 200 && bat < 0.55) return { left: 0, right: 0, drill: false };
      if (tl > 100 && bat > 0.3) { mem.mode = 'plan'; mem.tI = -1; }
      else return { left: 0, right: 0, drill: false };
    }

    if (mem.mode === 'deliver') {
      if (obs.beacon && obs.beacon.distance != null && isFinite(obs.beacon.distance)) {
        if (bDist < 3 && mem.spd < 0.12) {
          mem.cl = 0; mem.cr = 0;
          return { left: 0, right: 0, drill: false };
        }
        var fwd = 0, turn = 0;
        if (Math.abs(bBearing) > 15) {
          var dir = bBearing > 0 ? 1 : -1;
          turn = dir * Math.min(0.2, Math.abs(bBearing) * 0.005);
          fwd = bDist > 8 ? 0.12 : 0;
        } else {
          fwd = bDist > 10 ? 0.32 : bDist > 5 ? 0.18 : bDist > 3 ? 0.1 : 0.04;
          turn = clamp(bBearing * 0.005, -0.12, 0.12);
        }
        if (fwR < 2 && bDist > 5) { fwd = Math.min(fwd, 0.08); turn = clamp(turn + eD * 0.12, -0.25, 0.25); }
        if (mnR < 1 && bDist > 5) { fwd = -0.12; turn = eD * 0.22; }
        var cl = clamp(fwd - turn, -0.45, 0.45);
        var cr = clamp(fwd + turn, -0.45, 0.45);
        mem.cl = mem.cl + (cl - mem.cl) * 0.55;
        mem.cr = mem.cr + (cr - mem.cr) * 0.55;
        return { left: clamp(mem.cl, -1, 1), right: clamp(mem.cr, -1, 1), drill: false };
      }
      if (dBase < 2.5 && mem.spd < 0.12) {
        mem.cl = 0; mem.cr = 0;
        return { left: 0, right: 0, drill: false };
      }
      navTo(mem.bx, mem.by);
      return { left: clamp(mem.cl, -1, 1), right: clamp(mem.cr, -1, 1), drill: false };
    }
  }

  // ===== DRILL =====
  if (mem.mode === 'drill') {
    var sOK = obs.site && obs.site.distance != null && isFinite(obs.site.distance) && obs.site.distance <= 1.5;
    if (dProg >= 6) {
      mem.mode = 'plan'; mem.tI = -1; mem.dT = 0;
      for (i = 0; i < mem.hints.length; i++) {
        if (mem.hints[i].st < 2 && dist(mem.x, mem.y, mem.hints[i].x, mem.hints[i].y) < 25) mem.hints[i].st = 2;
      }
      return { left: 0, right: 0, drill: false };
    }
    if (mem.dT > 10 && dProg < 0.3) {
      mem.mode = 'plan'; mem.tI = -1; mem.dT = 0;
      return { left: 0, right: 0, drill: false };
    }
    if (!sOK || obs.bumped) {
      mem.mode = 'approach'; mem.dT = 0;
      return { left: 0, right: 0, drill: false };
    }
    mem.dT += dt;
    holdPos();
    return { left: clamp(mem.cl, -1, 1), right: clamp(mem.cr, -1, 1), drill: true };
  }

  // ===== SITE DETECTION (only when not delivering) =====
  if (obs.site && obs.site.distance != null && isFinite(obs.site.distance) && car < mem.cap && mem.mode !== 'deliver') {
    if (mem.mode !== 'approach') mem.mode = 'approach';
  }

  // ===== APPROACH =====
  if (mem.mode === 'approach') {
    if (obs.site && obs.site.distance != null && isFinite(obs.site.distance)) {
      var sd = obs.site.distance, sb = obs.site.bearing || 0;
      if (sd < 1.2 && mem.spd < 0.1) {
        mem.mode = 'drill'; mem.dT = 0;
        mem.hx = mem.x; mem.hy = mem.y;
      } else {
        approachSite(sd, sb);
        return { left: clamp(mem.cl, -1, 1), right: clamp(mem.cr, -1, 1), drill: false };
      }
    } else {
      mem.mode = 'search'; mem.sT = 0; mem.sciSeen = false;
      if (mem.sP) { mem.scX = mem.sP.x; mem.scY = mem.sP.y; }
      else { mem.scX = mem.x; mem.scY = mem.y; }
    }
  }

  // ===== SEARCH =====
  if (mem.mode === 'search') {
    if (obs.site && obs.site.distance != null && isFinite(obs.site.distance)) {
      mem.mode = 'approach';
    } else {
      mem.sT += dt;
      var sci = obs.science || 0;
      if (sci > 0.01) mem.sciSeen = true;
      if (mem.sT > 20 && !mem.sciSeen) {
        if (mem.tI >= 0 && mem.tI < mem.hints.length) mem.hints[mem.tI].st = 3;
        mem.mode = 'plan'; mem.tI = -1;
      } else {
        var mxT = sci > 0.5 ? 75 : 60;
        if (mem.sT > mxT) {
          if (mem.tI >= 0 && mem.tI < mem.hints.length) mem.hints[mem.tI].st = 3;
          mem.mode = 'plan'; mem.tI = -1;
        } else {
          var sA = mem.sT * 0.12, sR = 3 + mem.sT * 0.22;
          if (sci > 0.5) { sA = mem.sT * 0.18; sR = 3 + mem.sT * 0.15; }
          navTo(mem.scX + sR * Math.cos(sA), mem.scY + sR * Math.sin(sA));
          return { left: clamp(mem.cl, -1, 1), right: clamp(mem.cr, -1, 1), drill: false };
        }
      }
    }
  }

  // ===== GOTO =====
  if (mem.mode === 'goto') {
    if (mem.tI >= 0 && mem.tI < mem.hints.length && mem.hints[mem.tI].st < 2) {
      var tg = mem.hints[mem.tI];
      var dT = dist(mem.x, mem.y, tg.x, tg.y);
      if (dT < 20) {
        mem.mode = 'search'; mem.sT = 0; mem.sciSeen = false;
        mem.scX = tg.x; mem.scY = tg.y;
        tg.st = 1;
      } else {
        navTo(tg.x, tg.y);
        return { left: clamp(mem.cl, -1, 1), right: clamp(mem.cr, -1, 1), drill: false };
      }
    } else {
      mem.mode = 'plan'; mem.tI = -1;
    }
  }

  // ===== PLAN =====
  if (mem.mode === 'plan') {
    var bSc = -1, bIdx = -1;
    for (i = 0; i < mem.hints.length; i++) {
      if (mem.hints[i].st >= 2) continue;
      var dTo = dist(mem.x, mem.y, mem.hints[i].x, mem.hints[i].y);
      var tripT = (dTo + mem.hints[i].dB) / 1.2 + 40;
      if (tripT > tl * 0.85) continue;
      var sc = mem.hints[i].est / (tripT + 10);
      if (sc > bSc) { bSc = sc; bIdx = i; }
    }
    if (bIdx >= 0) {
      mem.tI = bIdx;
      mem.mode = 'goto';
    } else if (car > 0) {
      mem.mode = 'deliver';
    } else if (tl > 150) {
      if (!mem.eg) {
        mem.eg = [];
        for (var gx = 35; gx < mem.sz - 35; gx += 65)
          for (var gy = 35; gy < mem.sz - 35; gy += 65)
            mem.eg.push({ x: gx, y: gy, d: false });
        mem.eg.sort(function(a, b) { return dist(a.x, a.y, mem.bx, mem.by) - dist(b.x, b.y, mem.bx, mem.by); });
      }
      var bD2 = 1e9, bI2 = -1;
      for (i = 0; i < mem.eg.length; i++) {
        if (mem.eg[i].d) continue;
        var dd2 = dist(mem.x, mem.y, mem.eg[i].x, mem.eg[i].y);
        if (dd2 < bD2) { bD2 = dd2; bI2 = i; }
      }
      if (bI2 >= 0 && tl > 80) {
        if (bD2 < 15) mem.eg[bI2].d = true;
        navTo(mem.eg[bI2].x, mem.eg[bI2].y);
        return { left: clamp(mem.cl, -1, 1), right: clamp(mem.cr, -1, 1), drill: false };
      }
      mem.mode = 'deliver';
    } else {
      mem.mode = 'deliver';
    }
  }

  mem.cl *= 0.85;
  mem.cr *= 0.85;
  return { left: clamp(mem.cl, -1, 1), right: clamp(mem.cr, -1, 1), drill: false };

  function navTo(tx, ty) {
    var dx = tx - mem.x, dy = ty - mem.y;
    var dd = Math.sqrt(dx * dx + dy * dy);
    if (dd < 1.5) { mem.cl = 0; mem.cr = 0; return; }
    var tH = Math.atan2(dy, dx) * 180 / Math.PI;
    var hE = wrap(tH - mem.h);
    var aE = Math.abs(hE);
    var fwd = 0, turn = 0;
    if (aE > 80) {
      fwd = 0;
      turn = (hE > 0 ? 1 : -1) * Math.min(0.2, aE * 0.0025);
    } else if (aE > 35) {
      fwd = 0.12;
      turn = clamp(hE * 0.0035, -0.15, 0.15);
    } else {
      fwd = 0.35;
      if (dd < 15) fwd = Math.min(fwd, 0.06 + dd * 0.02);
      if (dd < 5) fwd = Math.min(fwd, 0.04 + dd * 0.03);
      turn = clamp(hE * 0.003, -0.08, 0.08);
    }
    if (fwR < 5) {
      fwd = Math.min(fwd, fwR * 0.1);
      turn = clamp(turn + eD * (5 - fwR) * 0.025, -0.22, 0.22);
    }
    if (mnR < 1.5) {
      fwd = Math.min(fwd, 0.08);
      turn = clamp(eD * 0.18, -0.28, 0.28);
    }
    if (mnR < 0.5) { fwd = -0.12; turn = eD * 0.2; }
    var mg = 15;
    if (mem.x < mg || mem.x > mem.sz - mg || mem.y < mg || mem.y > mem.sz - mg) {
      var cH = Math.atan2(mem.sz / 2 - mem.y, mem.sz / 2 - mem.x) * 180 / Math.PI;
      turn = clamp(turn + wrap(cH - mem.h) * 0.002, -0.18, 0.18);
    }
    fwd = Math.max(fwd, -0.18);
    var cl = clamp(fwd - turn, -0.45, 0.45);
    var cr = clamp(fwd + turn, -0.45, 0.45);
    mem.cl = mem.cl + (cl - mem.cl) * 0.5;
    mem.cr = mem.cr + (cr - mem.cr) * 0.5;
  }

  function approachSite(sd, sb) {
    var fwd = 0, turn = 0;
    if (Math.abs(sb) > 15) {
      var dir = sb > 0 ? 1 : -1;
      turn = dir * Math.min(0.2, Math.abs(sb) * 0.005);
    } else {
      fwd = sd > 5 ? 0.25 : sd > 3 ? 0.15 : sd > 2 ? 0.08 : sd > 1.5 ? 0.04 : 0.02;
      fwd *= (1 - Math.abs(sb) / 15 * 0.3);
      turn = clamp(sb * 0.004, -0.08, 0.08);
    }
    if (mnR < 1.5) {
      fwd = Math.min(fwd, 0.04);
      turn = clamp(turn + eD * 0.08, -0.2, 0.2);
    }
    var cl = clamp(fwd - turn, -0.22, 0.22);
    var cr = clamp(fwd + turn, -0.22, 0.22);
    mem.cl = mem.cl + (cl - mem.cl) * 0.5;
    mem.cr = mem.cr + (cr - mem.cr) * 0.5;
  }

  function holdPos() {
    var dx = mem.hx - mem.x, dy = mem.hy - mem.y;
    var dd = Math.sqrt(dx * dx + dy * dy);
    if (dd > 2.5) { navTo(mem.hx, mem.hy); return; }
    var fwd = 0, turn = 0;
    if (dd > 0.12) {
      var tH = Math.atan2(dy, dx) * 180 / Math.PI;
      turn = clamp(wrap(tH - mem.h) * 0.003, -0.06, 0.06);
      fwd = clamp(dd * 0.03, -0.06, 0.06);
    }
    fwd -= clamp((obs.pitch || 0) * 0.01, -0.1, 0.1);
    fwd -= mem.spd * 0.35;
    fwd = clamp(fwd, -0.1, 0.1);
    var cl = clamp(fwd - turn, -0.15, 0.15);
    var cr = clamp(fwd + turn, -0.15, 0.15);
    mem.cl = mem.cl + (cl - mem.cl) * 0.6;
    mem.cr = mem.cr + (cr - mem.cr) * 0.6;
  }
}

function act(obs, mem) {
  var out = {left: 0, right: 0, drill: false};
  var i;

  function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
  function wrap(a) { while (a > 180) a -= 360; while (a < -180) a += 360; return a; }
  function dist(ax, ay, bx, by) { var dx = bx - ax, dy = by - ay; return Math.sqrt(dx * dx + dy * dy); }

  var dt = 0.1;
  if (mem.tp !== undefined) dt = clamp(obs.t - mem.tp, 0.03, 0.5);
  mem.tp = obs.t;

  if (!mem.init) {
    mem.init = 1;
    var M = obs.mission || {};
    mem.sz = M.size || 400;
    mem.bx = (M.base && M.base.x) || 200;
    mem.by = (M.base && M.base.y) || 200;
    mem.cap = M.capacity || 5;
    mem.hints = [];
    var H = M.hints || [];
    for (i = 0; i < H.length; i++) {
      mem.hints.push({x: H[i].x, y: H[i].y, est: H[i].estimate || 1, dB: dist(H[i].x, H[i].y, mem.bx, mem.by), st: 0, fl: 0});
    }
    mem.hints.sort(function(a, b) { return (b.est / (b.dB + 25)) - (a.est / (a.dB + 25)); });
    mem.x = obs.x;
    mem.y = obs.y;
    mem.h = obs.heading;
    mem.gx = obs.x;
    mem.gy = obs.y;
    mem.cl = 0;
    mem.cr = 0;
    mem.mode = 'nav';
    mem.tI = -1;
    mem.dT = 0;
    mem.sT = 0;
    mem.apT = 0;
    mem.hx = 0;
    mem.hy = 0;
    mem.spd = 0;
    mem.lb = (obs.battery != null && isFinite(obs.battery)) ? obs.battery : 1;
    mem.epm = 0.0004;
    mem.mg = 3.0;
    mem.stkX = obs.x;
    mem.stkY = obs.y;
    mem.stkT = 0;
    mem.esc = 0;
    mem.escDir = 1;
    mem.lastEscDir = 0;
    mem.sP = null;
    mem.scX = mem.x;
    mem.scY = mem.y;
    mem.maxSci = 0;
    return out;
  }

  var wL = obs.wheelLeft || 0;
  var wR = obs.wheelRight || 0;
  var iS = Math.abs((wL + wR) / 2);
  if (iS > 15) iS = mem.spd;
  mem.spd = mem.spd * 0.8 + iS * 0.2;

  var cmdAvg = Math.abs((mem.cl + mem.cr) / 2);
  if (cmdAvg > 0.12 && iS > 0.15) {
    var mgEst = iS / cmdAvg;
    if (mgEst > 0.5 && mgEst < 10) {
      mem.mg = mem.mg * 0.97 + mgEst * 0.03;
    }
  }

  var vA = (wL + wR) / 2;
  var hR = mem.h * Math.PI / 180;
  mem.x += vA * Math.cos(hR) * dt;
  mem.y += vA * Math.sin(hR) * dt;

  if (obs.x !== mem.gx || obs.y !== mem.gy) {
    var jp = dist(obs.x, obs.y, mem.x, mem.y);
    if (jp < 30) {
      mem.x = obs.x;
      mem.y = obs.y;
    } else {
      mem.x = mem.x * 0.5 + obs.x * 0.5;
      mem.y = mem.y * 0.5 + obs.y * 0.5;
    }
    var gd = dist(obs.x, obs.y, mem.gx, mem.gy);
    if (gd > 1 && iS > 0.3) {
      var gH = Math.atan2(obs.y - mem.gy, obs.x - mem.gx) * 180 / Math.PI;
      var gHE = wrap(gH - mem.h);
      if (Math.abs(gHE) < 40) mem.h = wrap(mem.h + gHE * 0.08);
    }
    mem.gx = obs.x;
    mem.gy = obs.y;
  }

  mem.h = wrap(mem.h + (wR - wL) / 0.6 * dt * 180 / Math.PI);
  var cE = wrap(obs.heading - mem.h);
  if (Math.abs(cE) < 45) mem.h = wrap(mem.h + cE * 0.03);
  if (!isFinite(mem.x)) mem.x = obs.x;
  if (!isFinite(mem.y)) mem.y = obs.y;
  if (!isFinite(mem.h)) mem.h = obs.heading;

  var R = obs.rays || [];
  var mnR = 15;
  var fwR = 15;
  var lS = 0;
  var rS = 0;
  for (i = 0; i < 9; i++) {
    var r = (R[i] == null || isNaN(R[i]) || R[i] > 15) ? 15 : R[i];
    if (r < mnR) mnR = r;
    if (i === 4) fwR = r;
    if (i >= 5) lS += r;
    if (i <= 3) rS += r;
  }
  var eD = (lS > rS) ? 1 : -1;

  var bat = (obs.battery != null && isFinite(obs.battery)) ? obs.battery : mem.lb;
  var dBat = bat - mem.lb;
  mem.lb = bat;
  var uE = -dBat + (obs.solar || 0) * dt;
  if (uE > 0 && iS > 0.1) {
    var eM = uE / (iS * dt * (1 + 0.15 * (obs.carried || 0)));
    if (eM > 1e-6 && eM < 0.05) mem.epm = mem.epm * 0.95 + eM * 0.05;
  }

  if (obs.site && obs.site.distance != null && isFinite(obs.site.distance)) {
    var sa = (mem.h + (obs.site.bearing || 0)) * Math.PI / 180;
    mem.sP = {x: mem.x + obs.site.distance * Math.cos(sa), y: mem.y + obs.site.distance * Math.sin(sa)};
  }

  if (mem.mode === 'nav' || mem.mode === 'deliver' || mem.mode === 'search') {
    mem.stkT += dt;
    if (mem.stkT > 25) {
      if (dist(mem.x, mem.y, mem.stkX, mem.stkY) < 10) {
        mem.mode = 'escape';
        mem.esc = 0;
        var maxR2 = 0;
        var maxAng = 0;
        for (i = 0; i < 9; i++) {
          var rv = (R[i] != null && isFinite(R[i]) && R[i] > 0) ? R[i] : 15;
          if (rv > maxR2) {
            maxR2 = rv;
            maxAng = (i - 4) * 20;
          }
        }
        mem.escDir = (maxAng >= 0) ? 1 : -1;
        if (mem.escDir === mem.lastEscDir) mem.escDir = -mem.escDir;
        mem.lastEscDir = mem.escDir;
        if (mem.tI >= 0 && mem.tI < mem.hints.length && mem.hints[mem.tI].st < 2) {
          mem.hints[mem.tI].fl = (mem.hints[mem.tI].fl || 0) + 1;
          if (mem.hints[mem.tI].fl >= 2) mem.hints[mem.tI].st = 3;
        }
      }
      mem.stkX = mem.x;
      mem.stkY = mem.y;
      mem.stkT = 0;
    }
  }

  if (mem.mode === 'escape') {
    mem.esc += dt;
    var el = 0;
    var er = 0;
    var escSafe = 0.75 / Math.max(mem.mg || 3.0, 1.5);
    if (mem.esc < 3) {
      var rv1 = Math.min(0.3, escSafe);
      el = -rv1;
      er = -rv1;
    } else if (mem.esc < 5.5) {
      el = -mem.escDir * 0.2;
      er = mem.escDir * 0.2;
    } else if (mem.esc < 10) {
      var fe1 = Math.min(0.35, escSafe);
      if (fwR < 3) fe1 = Math.min(fe1, fwR * 0.1);
      if (fwR < 1.5) fe1 = 0;
      el = fe1;
      er = fe1;
    } else if (mem.esc < 12.5) {
      el = mem.escDir * 0.2;
      er = -mem.escDir * 0.2;
    } else if (mem.esc < 17) {
      var fe2 = Math.min(0.35, escSafe);
      if (fwR < 3) fe2 = Math.min(fe2, fwR * 0.1);
      if (fwR < 1.5) fe2 = 0;
      el = fe2;
      er = fe2;
    } else {
      mem.mode = 'nav';
      mem.tI = -1;
      mem.esc = 0;
      mem.stkX = mem.x;
      mem.stkY = mem.y;
      mem.stkT = 0;
    }
    if (mem.mode === 'escape') {
      mem.cl = mem.cl + (el - mem.cl) * 0.25;
      mem.cr = mem.cr + (er - mem.cr) * 0.25;
      return {left: clamp(mem.cl, -1, 1), right: clamp(mem.cr, -1, 1), drill: false};
    }
  }

  var tl = obs.timeLeft || 0;
  var car = obs.carried || 0;
  var dBase = dist(mem.x, mem.y, mem.bx, mem.by);

  if (mem.mode !== 'drill' && car > 0) {
    var tHome = dBase / 1.5 + 20;
    var eHome = dBase * mem.epm * 2 + 0.12;
    if (tl < tHome + 30 || bat < eHome + 0.12 || car >= mem.cap || bat < 0.15) {
      mem.mode = 'deliver';
    }
  }

  if (mem.mode === 'drill') {
    var sOK = obs.site && obs.site.distance != null && isFinite(obs.site.distance) && obs.site.distance <= 1.5;
    var dP = (obs.drilling != null && isFinite(obs.drilling)) ? obs.drilling : 0;
    if (bat < 0.08) {
      mem.mode = 'deliver';
    } else if (dP >= 6) {
      mem.mode = 'nav';
      mem.tI = -1;
      mem.dT = 0;
      for (i = 0; i < mem.hints.length; i++) {
        if (mem.hints[i].st < 2 && dist(mem.x, mem.y, mem.hints[i].x, mem.hints[i].y) < 30) {
          mem.hints[i].st = 2;
        }
      }
      if (car >= mem.cap) mem.mode = 'deliver';
      mem.cl = 0;
      mem.cr = 0;
    } else if (mem.dT > 12 && dP < 0.5) {
      mem.mode = 'nav';
      mem.tI = -1;
      mem.dT = 0;
    } else if (!sOK || obs.bumped) {
      mem.mode = 'approach';
      mem.dT = 0;
      mem.apT = 0;
    } else {
      mem.dT += dt;
      holdPos();
      return {left: clamp(mem.cl, -1, 1), right: clamp(mem.cr, -1, 1), drill: true};
    }
  }

  if (mem.mode === 'deliver') {
    if (dBase < 5) {
      var brake = clamp(-mem.spd * 0.6, -0.2, 0.05);
      var slope = clamp((obs.pitch || 0) * 0.015, -0.15, 0.15);
      mem.cl = brake + slope;
      mem.cr = brake + slope;
      if (mem.spd < 0.12 && dBase < 3) {
        if (car > 0) {
          return {left: clamp(mem.cl, -1, 1), right: clamp(mem.cr, -1, 1), drill: false};
        }
        if (tl > 250 && bat > 0.35) {
