      mem.tI = -1;
    } else if (obs.site && obs.site.distance != null && isFinite(obs.site.distance)) {
      var sd = obs.site.distance;
      var sb = obs.site.bearing || 0;
      if (sd < 1.3 && mem.spd < 0.12) {
