      }
    } else if (mem.sP) {
      navTo(mem.sP.x, mem.sP.y);
      if (dist(mem.x, mem.y, mem.sP.x, mem.sP.y) < 3) {
        mem.mode = 'search';
        mem.sT = 0;
        mem.maxSci = 0;
        mem.scX = mem.sP.x;
        mem.scY = mem.sP.y;
      }
      return {left: clamp(mem.cl, -1, 1), right: clamp(mem.cr, -1, 1), drill: false};
    } else {
      mem.mode = 'nav';
      mem.tI = -1;
    }
  }

  if (mem.mode === 'search') {
    if (obs.site && obs.site.distance != null && isFinite(obs.site.distance)) {
      mem.mode = 'approach';
      mem.apT = 0;
    } else {
      mem.sT += dt;
      var sci = obs.science || 0;
      if (sci > mem.maxSci) mem.maxSci = sci;
      var maxS = (mem.maxSci > 0.5) ? 65 : 35;
      if (mem.sT > maxS) {
        if (mem.tI >= 0 && mem.tI < mem.hints.length) {
          mem.hints[mem.tI].st = 3;
          mem.hints[mem.tI].fl = (mem.hints[mem.tI].fl || 0) + 1;
        }
        mem.mode = 'nav';
        mem.tI = -1;
      } else {
        var sA = mem.sT * 0.06;
        var sR = 3 + mem.sT * 0.5;
