      mem.cl *= 0.85;
      mem.cr *= 0.85;
      return;
    }
    var tH = Math.atan2(dy, dx) * 180 / Math.PI;
    var hE = wrap(tH - mem.h);
    var aE = Math.abs(hE);
    var fwd = 0;
    var turn = 0;
    var safeCmd = 0.75 / Math.max(mem.mg || 3.0, 1.5);

    if (aE > 55) {
      fwd = 0;
      turn = (hE > 0 ? 1 : -1) * Math.min(0.28, aE * 0.005);
    } else if (aE > 22) {
      fwd = 0.12;
      turn = clamp(hE * 0.004, -0.16, 0.16);
    } else {
      fwd = safeCmd;
      if (dd < 25) fwd = Math.min(fwd, 0.1 + dd * 0.016);
      if (dd < 10) fwd = Math.min(fwd, 0.05 + dd * 0.022);
      turn = clamp(hE * 0.0035, -0.09, 0.09);
    }

    if (fwR < 4.5) {
      fwd = Math.min(fwd, fwR * 0.08);
      turn = clamp(turn + eD * (4.5 - fwR) * 0.04, -0.25, 0.25);
    }
    if (mnR < 1.5) {
      fwd = Math.min(fwd, 0.05);
      turn = clamp(eD * 0.22, -0.3, 0.3);
    }
    if (mnR < 0.6) {
      fwd = -0.25;
      turn = eD * 0.3;
    }

    var mgEdge = 12;
    if (mem.x < mgEdge || mem.x > mem.sz - mgEdge || mem.y < mgEdge || mem.y > mem.sz - mgEdge) {
      var cH = Math.atan2(mem.sz / 2 - mem.y, mem.sz / 2 - mem.x) * 180 / Math.PI;
      turn = clamp(turn + wrap(cH - mem.h) * 0.003, -0.18, 0.18);
    }

    if (iS > 0.85) {
      fwd = fwd * 0.6;
      turn = turn * 0.6;
    }

    fwd = clamp(fwd, -0.3, safeCmd);
    var cl = clamp(fwd - turn, -0.55, 0.55);
    var cr = clamp(fwd + turn, -0.55, 0.55);

