      var fwdAvg = (cl + cr) / 2;
      cl = fwdAvg + (cl - fwdAvg) * dampF;
      cr = fwdAvg + (cr - fwdAvg) * dampF;
    }

    var maxD = (fwR < 3 || mnR < 1.5) ? 0.12 : 0.065;
    mem.cl = clamp(mem.cl + clamp(cl - mem.cl, -maxD, maxD), -1, 1);
    mem.cr = clamp(mem.cr + clamp(cr - mem.cr, -maxD, maxD), -1, 1);
