      else if (sd > 3) fwd = 0.08;
      else if (sd > 2) fwd = 0.04;
      else if (sd > 1.5) fwd = 0.015;
      else fwd = 0.005;
      turn = clamp(sb * 0.004, -0.07, 0.07);
    }
    if (mnR < 2) {
      fwd = Math.min(fwd, 0.025);
      turn = clamp(turn + eD * 0.1, -0.2, 0.2);
    }
    var cl = clamp(fwd - turn, -0.22, 0.22);
    var cr = clamp(fwd + turn, -0.22, 0.22);
    var maxD = 0.035;
    mem.cl = clamp(mem.cl + clamp(cl - mem.cl, -maxD, maxD), -1, 1);
    mem.cr = clamp(mem.cr + clamp(cr - mem.cr, -maxD, maxD), -1, 1);
  }

  function holdPos() {
    var dx = mem.hx - mem.x;
    var dy = mem.hy - mem.y;
    var dd = Math.sqrt(dx * dx + dy * dy);
    if (dd > 3) {
