      return;
    }
    var fwd = 0;
    var turn = 0;
    if (dd > 0.12) {
      var tH = Math.atan2(dy, dx) * 180 / Math.PI;
      turn = clamp(wrap(tH - mem.h) * 0.003, -0.05, 0.05);
      fwd = clamp(dd * 0.025, -0.05, 0.05);
    }
    fwd -= clamp((obs.pitch || 0) * 0.015, -0.12, 0.12);
    fwd -= mem.spd * 0.4;
    fwd = clamp(fwd, -0.12, 0.12);
    var cl = clamp(fwd - turn, -0.15, 0.15);
    var cr = clamp(fwd + turn, -0.15, 0.15);
    var maxD = 0.03;
    mem.cl = clamp(mem.cl + clamp(cl - mem.cl, -maxD, maxD), -1, 1);
    mem.cr = clamp(mem.cr + clamp(cr - mem.cr, -maxD, maxD), -1, 1);
