      mem.mapH = num(sz.height, num(sz.y, num(sz.h, 400)));
    } else {
      mem.mapW = num(sz, 400);
      mem.mapH = num(sz, 400);
    }
    mem.mapW = clamp(mem.mapW, 40, 2000);
    mem.mapH = clamp(mem.mapH, 40, 2000);

    var base = mission.base || { x: rawX, y: rawY };
    mem.baseX = num(base.x, rawX);
    mem.baseY = num(base.y, rawY);
    mem.capacity = clamp(Math.floor(num(mission.capacity, 5)), 1, 20);
    mem.missionSeconds = num(mission.seconds, 1200);

