    mem.nextSiteId = 0;
    mem.activeHintId = -1;
    mem.activeSiteId = -1;
    mem.samplingSiteId = -1;
    mem.search = null;
    mem.returning = false;
    mem.departing = false;
    mem.homeTicks = 0;

    mem.epm = 0.0015;
    mem.epmHigh = 0.0016;
    mem.drillRate = 0.001;
    mem.speedAvg = 0.82;
    mem.batteryMax = Math.max(0.2, battery);

    mem.lastCarried = carried;
    mem.lastBattery = battery;
    mem.lastSolar = solar;
    mem.energyReady = false;
    mem.energyWindow = 0;
    mem.energyDistance = 0;
    mem.energyTime = 0;
    mem.drillEnergy = 0;
    mem.drillTime = 0;

    mem.gainL = 3.0;
    mem.gainR = 3.0;
    mem.iL = 0;
    mem.iR = 0;
    mem.prevTargetL = 0;
    mem.prevTargetR = 0;
    mem.lastCmdL = 0;
    mem.lastCmdR = 0;
    mem.lastDesiredV = 0;

    mem.rayLast = [];
    mem.raySame = [];
    mem.rayBad = [];
    mem.rayMoved = 0;

    mem.gpsSpeed = 0;
    mem.gpsAge = 0;
    mem.gpsSame = 0;
    mem.gpsMoveSince = 0;
    mem.gpsFrozen = false;
    mem.prevGpsFrozen = false;

    mem.headingBias = 0;
    mem.compassIgnore = 0;
    mem.calOn = false;
    mem.clock = 0;
    mem.lastObsT = undefined;

    mem.sweepTarget = -1;
    mem.sweepPts = null;
    mem.sweepDone = null;

    mem.stuckSec = 0;
    mem.lastEscape = -100;
    mem.recoverUntil = -1;
    mem.recoverStart = -1;
    mem.recoverSide = 1;
    mem.lastBump = -100;
    mem.bumpPrev = false;
    mem.avoidSide = 0;
    mem.avoidClearT = 0;
    mem.lastSteer = 0;

