  var obsT = num(obs.t, mem.lastObsT === undefined ? 0 : mem.lastObsT + 0.1);
  var dt = 0.1;
  if (mem.lastObsT !== undefined) {
    var td = obsT - mem.lastObsT;
    if (td > 0.015 && td < 0.5) dt = td;
  }
  dt = clamp(dt, 0.04, 0.2);
  mem.clock += dt;
  var now = mem.clock;

  var oldPX = mem.posX;
  var oldPY = mem.posY;
  var oldHeading = mem.hEst;
  var rawGPSDist = 0;
  var gpsFrozen = false;
  var thawed = false;
  var dPos = 0;

  if (!mem.poseReady) {
    mem.posX = rawX;
    mem.posY = rawY;
    mem.hEst = rawHeading;
    mem.lastRawH = rawHeading;
    mem.lastGX = rawX;
    mem.lastGY = rawY;
    mem.gpsSame = 0;
    mem.gpsMoveSince = 0;
    mem.gpsAge = 0;
    mem.gpsSpeed = 0;
    mem.poseReady = true;
    oldPX = rawX;
    oldPY = rawY;
    oldHeading = rawHeading;
  } else {
    var yawRate = (wheelR - wheelL) / 0.6;
    var predHeading = wrap(oldHeading + yawRate * dt / RAD);
    var rawDelta = wrap(rawHeading - mem.lastRawH);
    var predDelta = wrap(predHeading - oldHeading);
    var mismatch = Math.abs(wrap(rawDelta - predDelta));

    if (mismatch > 45 && dt < 0.25) mem.compassIgnore = Math.max(mem.compassIgnore, 12);
    var compassAlpha = mem.compassIgnore > 0 ? 0.01 : 0.22;
    if (mem.compassIgnore > 0) mem.compassIgnore = Math.max(0, mem.compassIgnore - dt);
    var compassTarget = wrap(rawHeading + mem.headingBias);
    mem.hEst = wrap(predHeading + compassAlpha * wrap(compassTarget - predHeading));

    var midHeading = (oldHeading + mem.hEst) * 0.5 * RAD;
    var predX = mem.posX + wheelV * dt * Math.cos(midHeading);
    var predY = mem.posY + wheelV * dt * Math.sin(midHeading);

    rawGPSDist = distance(rawX, rawY, mem.lastGX, mem.lastGY);
    if (rawGPSDist < 0.025) {
      mem.gpsSame++;
      mem.gpsMoveSince += Math.abs(wheelV) * dt;
    } else {
      mem.gpsSame = 0;
      mem.gpsMoveSince = 0;
    }

    gpsFrozen = mem.gpsSame >= 14 && mem.gpsMoveSince > 0.8 && Math.abs(wheelV) > 0.25;
    thawed = mem.prevGpsFrozen && !gpsFrozen && rawGPSDist > 0.15;

    if (gpsFrozen) {
      mem.posX = predX;
      mem.posY = predY;
    } else {
      var gxErr = rawX - predX;
      var gyErr = rawY - predY;
      var errLen = Math.hypot(gxErr, gyErr);
      var alpha = thawed ? 0.72 : (Math.abs(wheelV) < 0.12 ? 0.25 : 0.34);
      if (errLen > 18 && !thawed) alpha = 0.04;
      if (errLen > 18 && thawed) alpha = 0.65;
      mem.posX = predX + alpha * gxErr;
      mem.posY = predY + alpha * gyErr;
    }

    if (!gpsFrozen && rawGPSDist > 0.08) {
      mem.gpsAge += dt;
      var gpsV = rawGPSDist / Math.max(dt, mem.gpsAge);
