  mem.gpsFrozen = gpsFrozen;
  mem.lastRawH = rawHeading;
  mem.lastGX = rawX;
  mem.lastGY = rawY;
  mem.lastObsT = obsT;

  var speedNow = Math.max(
    Math.abs(wheelV),
    mem.gpsSpeed * 0.62,
    Math.abs(wheelR - wheelL) * 0.22
