      if (gl > 0.45 && gl < 5.2) mem.gainL = clamp(0.96 * mem.gainL + 0.04 * gl, 0.65, 5.0);
    }
    if (Math.abs(mem.lastCmdR) > 0.18 && Math.abs(wheelR - prevWheelR) < 0.22) {
      var gr = Math.abs(wheelR) / Math.max(0.12, Math.abs(mem.lastCmdR) - 0.045);
      if (gr > 0.45 && gr < 5.2) mem.gainR = clamp(0.96 * mem.gainR + 0.04 * gr, 0.65, 5.0);
    }
  }

  var docked = !!obs.docked;
  var netEnergy = 0;
  if (mem.energyReady) {
    netEnergy = mem.lastBattery - battery + 0.5 * (mem.lastSolar + solar) * dt;
    if (docked || mem.prevDocked) {
      mem.energyWindow = 0;
      mem.energyDistance = 0;
      mem.energyTime = 0;
    } else {
      mem.energyWindow += netEnergy;
      mem.energyDistance += dPos;
      mem.energyTime += dt;
      if (mem.energyTime >= 4.5) {
        if (mem.energyDistance > 1.4 && mem.energyWindow > 0.0003) {
