        }
        mem.energyWindow = 0;
        mem.energyDistance = 0;
        mem.energyTime = 0;
      }
    }

    if (mem.lastDrillCmd) {
      mem.drillEnergy += Math.max(0, netEnergy);
      mem.drillTime += dt;
      if (mem.drillTime >= 3.0) {
