        mem.drillTime = 0;
      }
    } else {
      mem.drillEnergy = 0;
      mem.drillTime = 0;
    }
  }
  mem.energyReady = true;
  mem.lastBattery = battery;
  mem.lastSolar = solar;
  mem.prevDocked = docked;
  mem.batteryMax = Math.max(mem.batteryMax, battery);

  var rayInput = obs.rays || [];
  var rayVals = [];
  mem.rayMoved += dPos;
  for (var ri = 0; ri < 9; ri++) {
    var rv = clamp(num(rayInput[ri], 15), 0, 15);
    if (mem.rayLast[ri] !== undefined && Math.abs(rv - mem.rayLast[ri]) < 0.015) {
      mem.raySame[ri] = (mem.raySame[ri] || 0) + 1;
    } else {
      mem.raySame[ri] = 0;
      mem.rayBad[ri] = false;
    }
    if (mem.raySame[ri] > 90 && rv < 14.5 && mem.rayMoved > 3) mem.rayBad[ri] = true;
    mem.rayLast[ri] = rv;
    rayVals[ri] = mem.rayBad[ri] ? 15 : rv;
  }
  mem.rays = rayVals;

  if (Math.abs(mem.lastDesiredV || 0) > 0.34 && !gpsFrozen &&
      Math.abs(wheelV) > 0.20 && dPos < 0.006) {
    mem.stuckSec += dt;
  } else if (dPos > 0.018 || Math.abs(mem.lastDesiredV || 0) < 0.18) {
    mem.stuckSec = Math.max(0, mem.stuckSec - 2 * dt);
  }

  function sideClear(side) {
    var inds = side > 0 ? [5, 6, 7, 8] : [0, 1, 2, 3];
    var sum = 0;
    for (var ii = 0; ii < inds.length; ii++) sum += rayVals[inds[ii]];
    return sum / inds.length;
  }

  function startRecovery(side) {
    mem.recoverStart = now;
    mem.recoverUntil = now + 1.35;
    mem.recoverSide = side || 1;
    mem.lastEscape = now;
    mem.stuckSec = 0;
  }

  if (obs.bumped && (!mem.bumpPrev || now - mem.lastBump > 4.0)) {
    var lclear = sideClear(1);
    var rclear = sideClear(-1);
    startRecovery(lclear >= rclear ? 1 : -1);
    mem.lastBump = now;
  } else if (mem.stuckSec > 3.8 && now - mem.lastEscape > 5) {
    var lclear2 = sideClear(1);
    var rclear2 = sideClear(-1);
    startRecovery(lclear2 >= rclear2 ? 1 : -1);
  }
  mem.bumpPrev = !!obs.bumped;

  var carriedIncrease = carried > num(mem.lastCarried, carried) + 0.01;

  function findHint(id) {
    for (var i = 0; i < mem.hints.length; i++) {
      if (mem.hints[i].id === id) return mem.hints[i];
    }
    return null;
  }

  function findSite(id) {
    for (var i = 0; i < mem.sites.length; i++) {
      if (mem.sites[i].id === id) return mem.sites[i];
    }
    return null;
  }

  function markSampled(id) {
    var s = findSite(id);
    if (!s) return;
    s.state = 2;
    var hid = s.hintId;
    if (hid < 0 && mem.activeHintId >= 0) {
      var ah = findHint(mem.activeHintId);
      if (ah && distance(s.x, s.y, ah.x, ah.y) < 28) hid = ah.id;
    }
    if (hid >= 0) {
      var h = findHint(hid);
      if (h) h.state = 2;
      if (mem.activeHintId === hid) mem.activeHintId = -1;
      if (mem.search && mem.search.type === "hint" && mem.search.hintId === hid) mem.search = null;
    }
    if (mem.activeSiteId === id) mem.activeSiteId = -1;
    if (mem.samplingSiteId === id) mem.samplingSiteId = -1;
    mem.sampleStable = 0;
    mem.sampleAnchor = null;
  }

  if (carriedIncrease) {
    var completedId = mem.samplingSiteId >= 0 ? mem.samplingSiteId :
      (mem.activeSiteId >= 0 ? mem.activeSiteId : mem.currentSiteId);
    if (completedId >= 0) markSampled(completedId);
  }
  mem.lastCarried = carried;

  function recordSite(siteObs) {
    var sd = clamp(num(siteObs.distance, 99), 0, 50);
    var rel = num(siteObs.bearing, 0);
    var abs = (mem.hEst + rel) * RAD;
    var sx = mem.posX + sd * Math.cos(abs);
    var sy = mem.posY + sd * Math.sin(abs);
    sx = clamp(sx, 0, mem.mapW);
    sy = clamp(sy, 0, mem.mapH);
    var value = Math.max(0.01, num(siteObs.value, 0.1));

    var best = null;
    var bd = 6.5;
    for (var i = 0; i < mem.sites.length; i++) {
      var s = mem.sites[i];
      if (s.state === 2) continue;
      var d = distance(sx, sy, s.x, s.y);
      if (d < bd) {
        bd = d;
        best = s;
      }
    }

    if (!best) {
      best = {
        id: mem.nextSiteId++,
        x: sx,
        y: sy,
        value: value,
        state: 0,
        hintId: -1
      };
      mem.sites.push(best);
    } else {
      best.x = 0.58 * best.x + 0.42 * sx;
      best.y = 0.58 * best.y + 0.42 * sy;
      best.value = 0.68 * best.value + 0.32 * value;
    }

    if (best.hintId < 0) {
      var nearestHint = null;
      var nearestD = 25;
      for (var j = 0; j < mem.hints.length; j++) {
        var h = mem.hints[j];
        if (h.state === 2 || h.assoc >= 0) continue;
        var hd = distance(best.x, best.y, h.x, h.y);
        if (hd < nearestD) {
          nearestD = hd;
          nearestHint = h;
        }
      }
      if (nearestHint) {
        best.hintId = nearestHint.id;
        nearestHint.assoc = best.id;
        nearestHint.state = 1;
      }
    }

    mem.currentSiteId = best.id;
    mem.lastSiteSeenAt = now;
    return best;
  }

  var sensedSiteId = -1;
  var siteObs = obs.site || null;
  var sensedSite = null;
  if (siteObs && num(siteObs.distance, 99) <= 8.5) {
    sensedSite = recordSite(siteObs);
    sensedSiteId = sensedSite.id;
  }

  var beacon = obs.beacon || null;
  var gpsBaseDist = distance(mem.posX, mem.posY, mem.baseX, mem.baseY);
  var baseDist = beacon && num(beacon.distance, 99) <= 20.5
    ? clamp(num(beacon.distance, gpsBaseDist), 0, 25)
    : gpsBaseDist;

  if (mem.departing && baseDist > 3.5) mem.departing = false;
  var atHome = docked || (!mem.departing && baseDist < 2.35 && speedNow < 0.30) ||
    (mem.returning && baseDist < 2.45 && speedNow < 0.25);
  if (atHome) {
    mem.returning = false;
    mem.departing = false;
    if (docked) mem.homeTicks = 0;
  }

  function maxOtherValue(excludeId) {
    var mx = 0;
    for (var i = 0; i < mem.sites.length; i++) {
      var s = mem.sites[i];
      if (s.id !== excludeId && (s.state === 0 || s.state === 1)) mx = Math.max(mx, s.value);
    }
    for (var j = 0; j < mem.hints.length; j++) {
      var h = mem.hints[j];
      if (h.assoc < 0 && (h.state === 0 || h.state === 1)) mx = Math.max(mx, h.value);
    }
    return mx;
  }

  function shouldTakeSite(s) {
    if (!s || carried >= mem.capacity) return false;
    if (s.value < 0.04) return false;
    if (carried >= mem.capacity - 1) {
      var other = maxOtherValue(s.id);
      if (other > s.value * 2.25 && other > 0.5) return false;
    }
    return true;
  }

  if (sensedSite && !mem.returning && atHome === false || (sensedSite && atHome && !mem.returning)) {
    if (sensedSite.state === 0 || sensedSite.state === 1) {
      if (shouldTakeSite(sensedSite)) {
        if (mem.activeSiteId >= 0 && mem.activeSiteId !== sensedSite.id) {
          var oldActive = findSite(mem.activeSiteId);
          if (oldActive && oldActive.state === 1 && mem.samplingSiteId !== oldActive.id) oldActive.state = 0;
        }
        mem.activeSiteId = sensedSite.id;
        sensedSite.state = 1;
        if (sensedSite.hintId >= 0) {
          var sh = findHint(sensedSite.hintId);
          if (sh && sh.state === 0) sh.state = 1;
        }
      } else if (sensedSite.state === 0) {
        sensedSite.state = 3;
        if (sensedSite.hintId >= 0) {
          var skippedHint = findHint(sensedSite.hintId);
          if (skippedHint && skippedHint.state !== 2) skippedHint.state = 3;
          if (mem.activeHintId === sensedSite.hintId) mem.activeHintId = -1;
        }
      }
    }
  }

  function safeEpm() {
    return clamp(Math.max(0.0008, mem.epm * 1.65, mem.epmHigh * 1.22), 0.0008, 0.04);
  }

  function hintSearchRemaining(h) {
    var s = mem.search;
    if (!s || s.type !== "hint" || s.hintId !== h.id) return 28;
    if (s.stage === "center") return 30;
    if (s.stage === "probe") return Math.max(8, (4 - s.probeIndex) * 6 + 8);
    if (s.stage === "ring") return Math.max(8, (8 - s.ringIndex) * 6 + 8);
    return Math.max(8, (7 - s.hillSteps) * 6);
  }

  function candidateMetrics(c) {
    var isHint = c.kind === "hint";
    var x = c.obj.x;
    var y = c.obj.y;
    var offset = isHint ? 12 : 0;
    var out = distance(mem.posX, mem.posY, x, y) + offset;
    var back = distance(x, y, mem.baseX, mem.baseY) + offset;
    var extra = isHint ? hintSearchRemaining(c.obj) : 0;
    var load = 1 + 0.10 * Math.max(0, carried);
    var reserve = 0.095 + 0.018 * Math.max(0, carried);
    var meters = 1.38 * out + 1.48 * back + extra;
    var need = safeEpm() * meters * load + reserve + 6 * mem.drillRate;
    var sp = clamp(mem.speedAvg, 0.48, 1.5);
    var tneed = (out + back + extra) * 1.62 / sp + 22 + 6 + carried * 6;
    return {
      need: need,
      time: tneed,
      out: out,
      back: back,
      extra: extra,
      value: c.obj.value
    };
  }

  function findActive() {
    if (mem.activeSiteId >= 0) {
      var s = findSite(mem.activeSiteId);
      if (s && (s.state === 0 || s.state === 1)) return { kind: "site", obj: s };
      mem.activeSiteId = -1;
    }
    if (mem.activeHintId >= 0) {
      var h = findHint(mem.activeHintId);
      if (!h || h.state === 2 || h.state === 3) {
        mem.activeHintId = -1;
      } else {
        if (h.assoc >= 0) {
          var as = findSite(h.assoc);
          if (as && (as.state === 0 || as.state === 1)) {
            mem.activeSiteId = as.id;
            return { kind: "site", obj: as };
          }
          if (as && (as.state === 2 || as.state === 3)) {
            if (as.state === 2) h.state = 2;
            else h.state = 3;
            mem.activeHintId = -1;
          }
        }
        if (mem.activeHintId >= 0) return { kind: "hint", obj: h };
      }
    }
    return null;
  }

  function activate(c) {
    if (!c) return;
    if (c.kind === "site") {
      c.obj.state = 1;
      mem.activeSiteId = c.obj.id;
      if (c.obj.hintId >= 0) mem.activeHintId = c.obj.hintId;
    } else {
      c.obj.state = 1;
      mem.activeHintId = c.obj.id;
    }
  }

  function release(c) {
    if (!c) return;
    if (c.kind === "site") {
      if (c.obj.state === 1 && mem.samplingSiteId !== c.obj.id) c.obj.state = 0;
      if (mem.activeSiteId === c.obj.id) mem.activeSiteId = -1;
    } else {
      if (c.obj.state === 1) c.obj.state = 0;
      if (mem.activeHintId === c.obj.id) mem.activeHintId = -1;
      if (mem.search && mem.search.type === "hint" && mem.search.hintId === c.obj.id) mem.search = null;
    }
  }

  function pendingCount() {
    var count = 0;
    for (var i = 0; i < mem.sites.length; i++) {
      if (mem.sites[i].state === 0 || mem.sites[i].state === 1) count++;
    }
    for (var j = 0; j < mem.hints.length; j++) {
      var h = mem.hints[j];
      if (h.assoc < 0 && (h.state === 0 || h.state === 1)) count++;
    }
    return count;
  }

  function pickCandidate(allowCharge) {
    var best = null;
    var bestScore = -1;
    var topVal = maxOtherValue(-999999);
    var chargeLimit = Math.max(1.04, mem.batteryMax + 0.03);
    var timeLeft = num(obs.timeLeft, Math.max(0, mem.missionSeconds - now));

    for (var i = 0; i < mem.sites.length; i++) {
      var s = mem.sites[i];
      if (s.state !== 0 && s.state !== 1) continue;
      var c = { kind: "site", obj: s };
      var mt = candidateMetrics(c);
      if (allowCharge) {
        if (mt.need > chargeLimit) continue;
      } else if (mt.need > battery - 0.015) {
        continue;
      }
      if (mt.time > timeLeft - 7) continue;
      var score = s.value / (14 + mt.out + 0.60 * mt.back + 0.40 * mt.extra);
      if (carried >= mem.capacity - 1 && topVal > s.value * 2.2) score *= 0.18;
      if (score > bestScore) {
        bestScore = score;
        best = c;
      }
    }

    for (var j = 0; j < mem.hints.length; j++) {
      var h = mem.hints[j];
      if (h.assoc >= 0 || (h.state !== 0 && h.state !== 1)) continue;
      var hc = { kind: "hint", obj: h };
      var hm = candidateMetrics(hc);
      if (allowCharge) {
        if (hm.need > chargeLimit) continue;
      } else if (hm.need > battery - 0.015) {
        continue;
      }
      if (hm.time > timeLeft - 7) continue;
      var hs = 0.82 * h.value / (16 + hm.out + 0.60 * hm.back + 0.48 * hm.extra);
      if (carried >= mem.capacity - 1 && topVal > h.value * 2.2) hs *= 0.18;
      if (hs > bestScore) {
        bestScore = hs;
        best = hc;
      }
    }
    return best;
  }

  function makeSearch(type, hintId, x, y) {
    return {
      type: type,
      hintId: hintId,
      cx: x,
      cy: y,
      stage: "center",
      wpX: x,
      wpY: y,
      probeIndex: 0,
      ringIndex: 0,
      hillSteps: 0,
      turns: 0,
      bestS: 0,
      bestX: x,
      bestY: y,
      dirX: 1,
      dirY: 0,
      lastHillS: 0,
      probeVals: [0, 0, 0, 0],
      ringVals: [0, 0, 0, 0, 0, 0, 0, 0],
      probeOffsets: [[7, 0], [0, 7], [-7, 0], [0, -7]],
      ringOffsets: [
        [12, 0], [8.5, 8.5], [0, 12], [-8.5, 8.5],
        [-12, 0], [-8.5, -8.5], [0, -12], [8.5, -8.5]
      ]
    };
  }

  function setSearchWp(s, x, y) {
    s.wpX = clamp(x, 2, mem.mapW - 2);
    s.wpY = clamp(y, 2, mem.mapH - 2);
  }

  function saveSearchSample(s, x, y, val) {
    if (val > s.bestS) {
      s.bestS = val;
      s.bestX = x;
      s.bestY = y;
    }
  }

  function finishSearch(s) {
    if (s.type === "hint") {
      var h = findHint(s.hintId);
      if (h && h.state !== 2) h.state = 3;
      if (mem.activeHintId === s.hintId) mem.activeHintId = -1;
    }
    if (mem.search === s) mem.search = null;
  }

  function beginHill(s, gx, gy) {
    var norm = Math.hypot(gx, gy);
    if (norm < 1e-8) {
      gx = s.bestX - s.cx;
      gy = s.bestY - s.cy;
      norm = Math.hypot(gx, gy);
    }
    if (norm < 1e-8) {
      var seed = s.type === "hint" ? s.hintId + 1 : Math.floor(now * 3) + 1;
      var a = seed * 2.399963;
      gx = Math.cos(a);
      gy = Math.sin(a);
      norm = 1;
    }
    s.dirX = gx / norm;
    s.dirY = gy / norm;
    s.stage = "hill";
    s.hillSteps = 0;
    s.turns = 0;
    s.lastHillS = s.bestS;
    setSearchWp(s, s.bestX + 7 * s.dirX, s.bestY + 7 * s.dirY);
  }

  function processSearch() {
    var s = mem.search;
    if (!s) return;
    if (s.stage === "center") {
      if (distance(mem.posX, mem.posY, s.cx, s.cy) > 3.0) return;
      s.centerS = science;
      s.bestS = science;
      s.bestX = mem.posX;
      s.bestY = mem.posY;
      s.stage = "probe";
      s.probeIndex = 0;
      setSearchWp(s, s.cx + s.probeOffsets[0][0], s.cy + s.probeOffsets[0][1]);
      return;
    }

    if (distance(mem.posX, mem.posY, s.wpX, s.wpY) > 2.7) return;

    if (s.stage === "probe") {
      var pi = s.probeIndex;
      s.probeVals[pi] = science;
      saveSearchSample(s, s.wpX, s.wpY, science);
      s.probeIndex++;
      if (s.probeIndex < 4) {
        var po = s.probeOffsets[s.probeIndex];
        setSearchWp(s, s.cx + po[0], s.cy + po[1]);
        return;
      }
      var pv = s.probeVals;
      var pmax = Math.max(s.centerS, pv[0], pv[1], pv[2], pv[3]);
      var pmin = Math.min(s.centerS, pv[0], pv[1], pv[2], pv[3]);
      if (pmax <= 0.00001) {
        finishSearch(s);
        return;
      }
      var pgx = (pv[0] - pv[2]) / 14;
      var pgy = (pv[1] - pv[3]) / 14;
      if (Math.hypot(pgx, pgy) > Math.max(0.00001, pmax * 0.0015) ||
          pmax - pmin > Math.max(0.001, pmax * 0.004)) {
        beginHill(s, pgx, pgy);
      } else {
        s.stage = "ring";
        s.ringIndex = 0;
        var ro = s.ringOffsets[0];
        setSearchWp(s, s.cx + ro[0], s.cy + ro[1]);
      }
      return;
    }

    if (s.stage === "ring") {
      var ri2 = s.ringIndex;
      s.ringVals[ri2] = science;
      saveSearchSample(s, s.wpX, s.wpY, science);
      s.ringIndex++;
      if (s.ringIndex < 8) {
        var ro2 = s.ringOffsets[s.ringIndex];
        setSearchWp(s, s.cx + ro2[0], s.cy + ro2[1]);
        return;
      }
      if (s.bestS <= 0.00001) {
        finishSearch(s);
        return;
      }
      var rvv = s.ringVals;
      var rgx = (rvv[0] - rvv[4]) + 0.7 * (rvv[1] - rvv[5]) + 0.7 * (rvv[7] - rvv[3]);
      var rgy = (rvv[2] - rvv[6]) + 0.7 * (rvv[1] - rvv[5]) + 0.7 * (rvv[3] - rvv[7]);
      beginHill(s, rgx, rgy);
      return;
    }

    if (s.stage === "hill") {
      var currentS = science;
      var currentX = s.wpX;
      var currentY = s.wpY;
      saveSearchSample(s, currentX, currentY, currentS);
      s.hillSteps++;
      if (s.hillSteps >= 7) {
        finishSearch(s);
        return;
      }
      var tol = Math.max(0.01, s.lastHillS * 0.05);
      if (currentS + tol >= s.lastHillS) {
        s.lastHillS = currentS;
        setSearchWp(s, currentX + 7 * s.dirX, currentY + 7 * s.dirY);
      } else {
        s.turns++;
        var turnDeg = s.turns === 1 ? 45 : (s.turns === 2 ? -90 : 135);
        var ang = turnDeg * RAD;
        var nx = s.dirX * Math.cos(ang) - s.dirY * Math.sin(ang);
        var ny = s.dirX * Math.sin(ang) + s.dirY * Math.cos(ang);
        s.dirX = nx;
        s.dirY = ny;
        s.lastHillS = s.bestS;
        setSearchWp(s, s.bestX + 7 * s.dirX, s.bestY + 7 * s.dirY);
      }
    }
  }

  function searchMetrics(s) {
    var tx = s.stage === "center" ? s.cx : s.wpX;
    var ty = s.stage === "center" ? s.cy : s.wpY;
    var out = distance(mem.posX, mem.posY, tx, ty);
    var back = distance(tx, ty, mem.baseX, mem.baseY);
    var extra = 24;
    if (s.stage === "probe") extra = Math.max(8, (4 - s.probeIndex) * 6);
    else if (s.stage === "ring") extra = Math.max(8, (8 - s.ringIndex) * 6);
    else if (s.stage === "hill") extra = Math.max(6, (7 - s.hillSteps) * 6);
    var reserve = 0.10 + 0.018 * carried;
    var load = 1 + 0.10 * carried;
    var need = safeEpm() * (1.38 * (out + extra) + 1.48 * (back + 5)) * load + reserve + 0.01;
    var sp = clamp(mem.speedAvg, 0.48, 1.5);
    var tneed = (out + back + extra) * 1.62 / sp + 18 + carried * 6;
    return { need: need, time: tneed, x: tx, y: ty };
  }

  function ensureSweep() {
    if (mem.sweepPts) return;
    mem.sweepPts = [];
    mem.sweepDone = [];
    for (var y = 22; y <= mem.mapH - 22; y += 50) {
      for (var x = 22; x <= mem.mapW - 22; x += 50) {
        mem.sweepPts.push({ x: x, y: y });
        mem.sweepDone.push(false);
      }
    }
    mem.sweepTarget = -1;
  }

  function sweepMetrics(index) {
    var p = mem.sweepPts[index];
    var out = distance(mem.posX, mem.posY, p.x, p.y);
    var back = distance(p.x, p.y, mem.baseX, mem.baseY);
    var load = 1 + 0.10 * carried;
    var need = safeEpm() * (1.42 * (out + 4) + 1.48 * (back + 5)) * load +
      0.10 + 0.018 * carried;
    var sp = clamp(mem.speedAvg, 0.48, 1.5);
    var tneed = (out + back) * 1.62 / sp + 18 + carried * 6;
    return { need: need, time: tneed, x: p.x, y: p.y };
  }

  function pickSweep(allowCharge) {
    ensureSweep();
    var timeLeft = num(obs.timeLeft, Math.max(0, mem.missionSeconds - now));
    var chargeLimit = Math.max(1.04, mem.batteryMax + 0.03);
    var best = -1;
    var bestScore = Infinity;
    for (var i = 0; i < mem.sweepPts.length; i++) {
      if (mem.sweepDone[i]) continue;
      var mt = sweepMetrics(i);
      if (allowCharge) {
        if (mt.need > chargeLimit) continue;
      } else if (mt.need > battery - 0.02) {
        continue;
      }
      if (mt.time > timeLeft - 8) continue;
      var score = distance(mem.posX, mem.posY, mt.x, mt.y) +
        0.30 * distance(mt.x, mt.y, mem.baseX, mem.baseY);
      if (score < bestScore) {
        bestScore = score;
        best = i;
      }
    }
    mem.sweepTarget = best;
    return best;
  }

  var batterySafeRate = safeEpm();
