    mem.posY = rawY;
    mem.hEst = rawH;
    mem.lastRawH = rawH;
    mem.lastGX = rawX;
    mem.lastGY = rawY;
    mem.gpsSame = 0;
    mem.gpsMoveSince = 0;
    mem.poseReady = true;
