      var gr = Math.abs(wheelR) / Math.max(0.10, Math.abs(mem.lastCmdR) - 0.04);
      if (gr > 0.45 && gr < 5.5) {
        mem.gainR = clamp(0.985 * mem.gainR + 0.015 * gr, 0.55, 5.2);
