            h.state = 2;
            mem.activeType = null;
            mem.activeId = -1;
          }
        }
        if (mem.activeType === "hint") return { kind: "hint", obj: h };
      }

      if (mem.activeType === "hint") {
        mem.activeType = null;
        mem.activeId = -1;
      }
    }

    return null;
  }

  function activate(c) {
    if (!c) return;
    if (mem.activeType &&
        (mem.activeType !== c.kind || mem.activeId !== c.obj.id)) {
      clearActive();
    }

    mem.activeType = c.kind;
    mem.activeId = c.obj.id;
    c.obj.state = 1;

    if (c.kind === "site" && c.obj.hintId >= 0) {
      var h = findHint(c.obj.hintId);
      if (h && h.state !== 2) {
        h.assoc = c.obj.id;
        h.state = 1;
      }
    }

    if (mem.search && mem.search.type === "free") mem.search = null;
    if (mem.search && mem.search.type === "hint" &&
        c.kind === "hint" && mem.search.hintId !== c.obj.id) {
      mem.search = null;
    }
  }

  function setActiveSite(s) {
    if (!s || s.state === 2 || drillProgress > 0.01) return;
    if (mem.activeType === "site" && mem.activeId === s.id) {
      s.state = 1;
      return;
    }

    clearActive();
    mem.activeType = "site";
    mem.activeId = s.id;
    s.state = 1;

    if (s.hintId >= 0) {
      var h = findHint(s.hintId);
      if (h && h.state !== 2) {
        h.assoc = s.id;
        h.state = 1;
      }
    }

    if (mem.search) mem.search = null;
  }

  if (sensedSite && carried < mem.capacity && mem.mode !== "return") {
    setActiveSite(sensedSite);
  }

  function pickCandidate(atHome, exclude) {
    var best = null;
    var bestScore = -1;
    var limit = atHome
      ? Math.max(battery, mem.batteryMax + 0.035)
      : battery - 0.035;
    var timeLeft = num(obs.timeLeft,
      Math.max(0, mem.missionSeconds - now));

    function consider(kind, obj) {
      if (!obj || (obj.state !== 0 && obj.state !== 1)) return;
      if (kind === "hint" && obj.assoc >= 0) return;
      if (exclude && exclude.kind === kind &&
          exclude.obj.id === obj.id) return;

      var c = { kind: kind, obj: obj };
      var m = candidateMetrics(c);
      if (m.need > limit || m.time > timeLeft - 8) return;

      var score = Math.max(0.01, obj.value) /
        (18 + m.out + 0.64 * m.back + 0.48 * m.extra);

      if (carried >= mem.capacity - 1) {
        var otherMax = 0;
        for (var k = 0; k < mem.sites.length; k++) {
          if (mem.sites[k].state === 0 || mem.sites[k].state === 1) {
            otherMax = Math.max(otherMax, mem.sites[k].value);
          }
        }
        for (var j = 0; j < mem.hints.length; j++) {
          var hh = mem.hints[j];
          if (hh.assoc < 0 && (hh.state === 0 || hh.state === 1)) {
            otherMax = Math.max(otherMax, hh.value);
          }
        }
        if (otherMax > obj.value * 2.5 && otherMax > 0.5) score *= 0.2;
      }

      if (score > bestScore) {
        bestScore = score;
        best = c;
      }
    }

    for (var i = 0; i < mem.sites.length; i++) {
      consider("site", mem.sites[i]);
    }
    for (var j = 0; j < mem.hints.length; j++) {
      consider("hint", mem.hints[j]);
    }

    return best;
  }

  function makeSearch(type, hintId, x, y) {
    return {
      type: type,
      hintId: hintId,
      cx: x,
      cy: y,
      phase: "center",
      targets: [{ x: x, y: y }],
      idx: 0,
      waitAt: -1,
      sum: 0,
      count: 0,
      centerVal: 0,
      crossVals: [0, 0, 0, 0],
      ringVals: [0, 0, 0, 0, 0, 0, 0, 0],
      bestS: 0,
      bestX: x,
      bestY: y,
      dirX: 1,
      dirY: 0
    };
  }

  function setSearchTargets(s, phase, targets) {
    s.phase = phase;
    s.targets = targets;
    s.idx = 0;
    s.waitAt = -1;
    s.sum = 0;
    s.count = 0;
  }

  function saveSearchBest(s, x, y, value) {
    if (value > s.bestS) {
      s.bestS = value;
      s.bestX = x;
      s.bestY = y;
    }
  }

  function finishSearch(s) {
    if (s.type === "hint") {
      var h = findHint(s.hintId);
      if (h && h.state !== 2 && h.assoc < 0) h.state = 3;
      if (mem.activeType === "hint" &&
          mem.activeId === s.hintId) {
        mem.activeType = null;
        mem.activeId = -1;
      }
    } else {
      mem.freeDone.push({ x: s.cx, y: s.cy });
      if (mem.freeDone.length > 80) mem.freeDone.shift();
    }

    if (mem.search === s) mem.search = null;
  }

  function beginHill(s, gx, gy) {
    var norm = Math.hypot(gx, gy);
    if (norm < 1e-8) {
      gx = s.bestX - s.cx;
      gy = s.bestY - s.cy;
      norm = Math.hypot(gx, gy);
    }

    if (norm < 1e-8) {
      var seed = s.type === "hint" ? s.hintId + 1 : Math.floor(now) + 1;
      var angle = seed * 2.399963;
      gx = Math.cos(angle);
      gy = Math.sin(angle);
      norm = 1;
    }

    s.dirX = gx / norm;
    s.dirY = gy / norm;

    var targets = [];
    for (var i = 1; i <= 5; i++) {
      targets.push({
        x: clamp(s.bestX + 6 * i * s.dirX, 2, mem.mapW - 2),
        y: clamp(s.bestY + 6 * i * s.dirY, 2, mem.mapH - 2)
      });
    }
    setSearchTargets(s, "hill", targets);
  }

  function searchStep(s) {
    if (!s) return { action: motor(0, 0), done: true };

    if (s.idx >= s.targets.length) {
      finishSearch(s);
      return { action: motor(0, 0), done: true };
    }

    var target = s.targets[s.idx];
    var d = dist(mem.posX, mem.posY, target.x, target.y);

    if (d > 2.65) {
      s.waitAt = -1;
      s.sum = 0;
      s.count = 0;
      return {
        action: goPoint(target.x, target.y, 1.55, 0.74),
        done: false
      };
    }

    if (s.waitAt < 0) {
      s.waitAt = now;
      s.sum = 0;
      s.count = 0;
    }

    s.sum += science;
    s.count++;

    if (now - s.waitAt < 0.55) {
      return { action: motor(0, 0), done: false };
    }

    var value = s.sum / Math.max(1, s.count);
    saveSearchBest(s, target.x, target.y, value);

    if (s.phase === "center") {
      s.centerVal = value;
      var cross = [
        { x: clamp(s.cx + 9, 2, mem.mapW - 2), y: s.cy },
        { x: s.cx, y: clamp(s.cy + 9, 2, mem.mapH - 2) },
        { x: clamp(s.cx - 9, 2, mem.mapW - 2), y: s.cy },
        { x: s.cx, y: clamp(s.cy - 9, 2, mem.mapH - 2) }
      ];
      setSearchTargets(s, "cross", cross);
      return { action: motor(0, 0), done: false };
    }

    if (s.phase === "cross") {
      s.crossVals[s.idx] = value;
      s.idx++;

      if (s.idx < 4) {
        s.waitAt = -1;
        s.sum = 0;
        s.count = 0;
        return { action: motor(0, 0), done: false };
      }

      var cv = s.crossVals;
      var vals = [s.centerVal, cv[0], cv[1], cv[2], cv[3]];
      var pmax = Math.max.apply(null, vals);
      var pmin = Math.min.apply(null, vals);

      if (pmax <= 0.000001) {
        finishSearch(s);
        return { action: motor(0, 0), done: true };
      }

      var gx = (cv[0] - cv[2]) / 18;
      var gy = (cv[1] - cv[3]) / 18;
      var span = pmax - pmin;
      var threshold = Math.max(0.00003, pmax * 0.025);

      if (span > threshold &&
          Math.hypot(gx, gy) > threshold / 24) {
        beginHill(s, gx, gy);
      } else {
        var ring = [
          [15, 0], [10.6, 10.6], [0, 15], [-10.6, 10.6],
          [-15, 0], [-10.6, -10.6], [0, -15], [10.6, -10.6]
        ];
        var ringTargets = [];
        for (var ri = 0; ri < ring.length; ri++) {
          ringTargets.push({
            x: clamp(s.cx + ring[ri][0], 2, mem.mapW - 2),
            y: clamp(s.cy + ring[ri][1], 2, mem.mapH - 2)
          });
        }
        setSearchTargets(s, "ring", ringTargets);
      }

      return { action: motor(0, 0), done: false };
    }

    if (s.phase === "ring") {
      s.ringVals[s.idx] = value;
      s.idx++;

      if (s.idx < 8) {
        s.waitAt = -1;
        s.sum = 0;
        s.count = 0;
        return { action: motor(0, 0), done: false };
      }

      var rv = s.ringVals;
      var rgx = (rv[0] - rv[4]) +
        0.7 * (rv[1] - rv[5]) +
        0.7 * (rv[7] - rv[3]);
      var rgy = (rv[2] - rv[6]) +
        0.7 * (rv[1] - rv[5]) +
        0.7 * (rv[3] - rv[7]);
      var rmax = Math.max.apply(null, rv);
      var rmin = Math.min.apply(null, rv);

      if (rmax - rmin > Math.max(0.00003, rmax * 0.025) &&
          Math.hypot(rgx, rgy) > Math.max(0.00005, rmax * 0.001)) {
        beginHill(s, rgx, rgy);
        return { action: motor(0, 0), done: false };
      }

      finishSearch(s);
      return { action: motor(0, 0), done: true };
    }

    if (s.phase === "hill") {
      s.idx++;
      if (s.idx >= s.targets.length) {
        finishSearch(s);
        return { action: motor(0, 0), done: true };
      }

      s.waitAt = -1;
      s.sum = 0;
      s.count = 0;
      return { action: motor(0, 0), done: false };
    }

    finishSearch(s);
    return { action: motor(0, 0), done: true };
  }

  function freeNear(x, y) {
    for (var i = 0; i < mem.freeDone.length; i++) {
      if (dist(x, y, mem.freeDone[i].x, mem.freeDone[i].y) < 15) {
        return true;
      }
    }
    return false;
  }

  function ensureSweep() {
    if (mem.sweepPts) return;

    mem.sweepPts = [];
    mem.sweepDone = [];

    for (var y = 35; y <= mem.mapH - 35; y += 66) {
      for (var x = 35; x <= mem.mapW - 35; x += 66) {
        mem.sweepPts.push({ x: x, y: y });
        mem.sweepDone.push(false);
      }
    }

    mem.sweepTarget = -1;
  }

  function sweepMetrics(index) {
    var p = mem.sweepPts[index];
    var out = dist(mem.posX, mem.posY, p.x, p.y);
    var back = dist(p.x, p.y, mem.baseX, mem.baseY);
    var extra = 22;
    var load = 1 + 0.12 * carried;
    var rate = safeEpm();
    var work = (1.25 * (out + extra) + 1.45 * (back + 5)) * load;
    var speed = Math.max(0.36, mem.speedAvg * 0.78);
    var time = (out + extra + back) / speed + 24;
    var credit = Math.min(0.12, solar * time * 0.07);

    return {
      need: Math.max(0.02, rate * work + 0.11 + 0.02 * carried -
        credit),
      time: time,
      x: p.x,
      y: p.y
    };
  }

  function pickSweep(atHome) {
    ensureSweep();

    var limit = atHome
      ? Math.max(battery, mem.batteryMax + 0.035)
      : battery - 0.035;
    var timeLeft = num(obs.timeLeft,
      Math.max(0, mem.missionSeconds - now));
    var best = -1;
    var bestScore = Infinity;

    for (var i = 0; i < mem.sweepPts.length; i++) {
      if (mem.sweepDone[i]) continue;

      var m = sweepMetrics(i);
      if (m.need > limit || m.time > timeLeft - 8) continue;

      var score = dist(mem.posX, mem.posY, m.x, m.y) +
        0.30 * dist(m.x, m.y, mem.baseX, mem.baseY);

      if (score < bestScore) {
        bestScore = score;
        best = i;
      }
    }

    mem.sweepTarget = best;
    return best;
  }

  function motor(v, omega) {
    v = clamp(v, -0.95, 0.88);
    omega = clamp(omega, -1.25, 1.25);

    var targetL = clamp(v - 0.3 * omega, -1.35, 1.35);
    var targetR = clamp(v + 0.3 * omega, -1.35, 1.35);

    function one(target, actual, side) {
      var gain = side === 0 ? mem.gainL : mem.gainR;
      var integral = side === 0 ? mem.iL : mem.iR;
      var prevTarget = side === 0 ? mem.prevTargetL : mem.prevTargetR;

      if (target * prevTarget < -0.02 ||
          Math.abs(target - prevTarget) > 1.0) {
        integral *= 0.35;
      }

      var err = target - actual;
      integral = clamp(integral +
        err * dt * 0.10 / Math.max(0.7, gain), -0.15, 0.15);

      var u = target / Math.max(0.7, gain) +
        0.40 * err / Math.max(0.7, gain) +
        integral;

      if (Math.abs(target) > 0.07) {
        u += (target > 0 ? 1 : -1) * 0.04;
      }

      u = clamp(u, -1, 1);

      if (side === 0) {
        mem.iL = integral;
        mem.prevTargetL = target;
      } else {
        mem.iR = integral;
        mem.prevTargetR = target;
      }

      return u;
    }

    return {
      l: one(targetL, wheelL, 0),
      r: one(targetR, wheelR, 1),
      v: v,
      targetL: targetL,
      targetR: targetR
    };
  }

  function finish(action, drill) {
    var l = clamp(num(action && action.l, 0), -1, 1);
    var r = clamp(num(action && action.r, 0), -1, 1);

    mem.lastCmdL = l;
    mem.lastCmdR = r;
    mem.lastDesiredV = num(action && action.v, 0);
    mem.lastWheelL = wheelL;
    mem.lastWheelR = wheelR;
    mem.lastDrillCmd = !!drill;

    return { left: l, right: r, drill: !!drill };
  }

  function chooseDirection(goalRel) {
    goalRel = wrap(goalRel);

    var front = rayAt(0);
    var directClear = rayAt(clamp(goalRel, -80, 80));
    var urgent = front < 5.0 || directClear < 4.5;

    if (!urgent) {
      return { angle: clamp(goalRel, -80, 80), clear: directClear };
    }

    if (mem.avoidSide === 0) {
      mem.avoidSide = sideClear(1) >= sideClear(-1) ? 1 : -1;
    }

    var candidates = [-80, -60, -40, -20, 0, 20, 40, 60, 80];
    candidates.push(clamp(goalRel, -80, 80));

    var bestA = clamp(goalRel, -80, 80);
    var bestCost = Infinity;
    var bestClear = rayAt(bestA);

    for (var i = 0; i < candidates.length; i++) {
      var a = candidates[i];
      var clear = rayAt(a);
      var dev = Math.abs(wrap(a - goalRel));
      var cost = dev;

      if (clear < 2.5) cost += 140 + (2.5 - clear) * 25;
      else if (clear < 5.5) cost += (5.5 - clear) * 18;

      if (Math.abs(a) > 8 && Math.sign(a) !== mem.avoidSide) {
        cost += 4;
      }

      if (Math.abs(a - mem.lastSteer) < 18) cost -= 0.8;

      if (cost < bestCost) {
        bestCost = cost;
        bestA = a;
        bestClear = clear;
      }
    }

    if (front > 7 && directClear > 7) {
      mem.avoidSide = 0;
    }
    mem.lastSteer = bestA;

    return { angle: bestA, clear: bestClear };
  }

  function driveToRelative(rel, d, stopRadius, maxV) {
    rel = wrap(rel);
    d = Math.max(0, num(d, 0));
    stopRadius = Math.max(0, stopRadius);

    var remain = d - stopRadius;
    if (remain <= 0.12) return motor(0, 0);

    if (Math.abs(rel) > 105) {
      return motor(0, rel > 0 ? 0.82 : -0.82);
    }

    var absMove = (mem.hEst + rel) * RAD;
    var dirX = Math.cos(absMove);
    var dirY = Math.sin(absMove);

    var pointsOut = (mem.posX < 4 && dirX < -0.15) ||
      (mem.posX > mem.mapW - 4 && dirX > 0.15) ||
      (mem.posY < 4 && dirY < -0.15) ||
      (mem.posY > mem.mapH - 4 && dirY > 0.15);

    if (pointsOut) {
      var centerBearing = Math.atan2(mem.mapH * 0.5 - mem.posY,
        mem.mapW * 0.5 - mem.posX) / RAD;
      rel = wrap(centerBearing - mem.hEst);
    }

    var steerInfo = chooseDirection(rel);
    var steer = steerInfo.angle;

    var speed = Math.min(maxV, Math.sqrt(Math.max(0, 0.78 * remain)));

    if (Math.abs(steer) > 70) speed = 0;
    else if (Math.abs(steer) > 53) speed = Math.min(speed, 0.28);
    else if (Math.abs(steer) > 38) speed = Math.min(speed, 0.46);
    else if (Math.abs(steer) > 25) speed = Math.min(speed, 0.67);

    if (steerInfo.clear < 2.0) speed = Math.min(speed, 0.16);
    else if (steerInfo.clear < 3.5) speed = Math.min(speed, 0.28);
    else if (steerInfo.clear < 5.5) speed = Math.min(speed, 0.48);

    var front = rayAt(0);
    if (front < 1.7) speed = Math.min(speed, 0.12);
    else if (front < 2.8) speed = Math.min(speed, 0.22);
    else if (front < 4.2) speed = Math.min(speed, 0.40);

    if (pointsOut) speed = Math.min(speed, 0.35);

    var omega = clamp(1.65 * steer * RAD, -1.18, 1.18);
    if (Math.abs(steer) < 1.5) omega = 0;

    return motor(speed, omega);
  }

  function goPoint(x, y, stopRadius, maxV) {
    x = clamp(x, 1, mem.mapW - 1);
    y = clamp(y, 1, mem.mapH - 1);

    var dx = x - mem.posX;
    var dy = y - mem.posY;
    var d = Math.hypot(dx, dy);
    var rel = d < 0.01
      ? 0
      : wrap(Math.atan2(dy, dx) / RAD - mem.hEst);

    return driveToRelative(rel, d, stopRadius, maxV);
  }

  function goBase(stopRadius) {
    if (hasBeacon) {
      return driveToRelative(num(beacon.bearing, 0),
        num(beacon.distance, baseDist), stopRadius, 0.82);
    }

    var dx = mem.baseX - mem.posX;
    var dy = mem.baseY - mem.posY;
    var d = Math.hypot(dx, dy);
    var rel = d < 0.01
      ? 0
      : wrap(Math.atan2(dy, dx) / RAD - mem.hEst);

    return driveToRelative(rel, d, stopRadius, 0.82);
  }

  function recoveryAction() {
    var elapsed = now - mem.recoverStart;
    if (now >= mem.recoverUntil) return null;
    if (elapsed < 0.42) return motor(-0.24, 0);
    return motor(0, mem.recoverSide * 0.78);
  }

  function sampleAction(site, live, liveDistance, liveBearing) {
    var globalD = dist(mem.posX, mem.posY, site.x, site.y);
    var d = live ? liveDistance : globalD;
    var continuing = drillProgress > 0.01 || mem.drillStarted;

    if (d > 1.34 && !continuing) {
      mem.sampleStableTime = 0;

      var rel;
      if (live) {
        rel = liveBearing;
      } else {
        var dx = site.x - mem.posX;
        var dy = site.y - mem.posY;
        rel = globalD < 0.01
          ? 0
          : wrap(Math.atan2(dy, dx) / RAD - mem.hEst);
      }

      return {
        action: driveToRelative(rel, d, 0.95, 0.72),
        drill: false
      };
    }

    if (!mem.sampleAnchor || mem.sampleAnchor.id !== site.id) {
      mem.sampleAnchor = {
        id: site.id,
        x: mem.posX,
        y: mem.posY,
        h: mem.hEst
      };
      mem.sampleStableTime = 0;
    }

    var hRad = mem.hEst * RAD;
    var errX = mem.sampleAnchor.x - mem.posX;
    var errY = mem.sampleAnchor.y - mem.posY;
    var forwardError = errX * Math.cos(hRad) + errY * Math.sin(hRad);
    var sideError = -errX * Math.sin(hRad) + errY * Math.cos(hRad);
    var pitch = num(obs.pitch, 0) * RAD;

    var vHold = clamp(
      0.58 * forwardError - 0.58 * wheelV + 0.14 * Math.sin(pitch),
      -0.22, 0.22
    );

    var yawRateNow = (wheelR - wheelL) / 0.6;
    var headingError = wrap(mem.sampleAnchor.h - mem.hEst) * RAD;
    var omegaHold = clamp(
      0.85 * headingError - 0.38 * yawRateNow - 0.20 * sideError,
      -0.38, 0.38
    );

    var stableSpeed = Math.max(
      Math.abs(wheelV),
      Math.abs(wheelR - wheelL) * 0.09,
      mem.gpsSpeed * 0.32
    );

    if (stableSpeed < 0.13 && d <= 1.42) {
      mem.sampleStableTime += dt;
    } else if (!continuing) {
      mem.sampleStableTime = 0;
    }

    var drill = continuing ||
      (mem.sampleStableTime >= 0.45 && d <= 1.35);

    if (drill && !mem.drillStarted) {
      mem.drillStarted = true;
      mem.drillStartTime = now;
      mem.drillSiteId = site.id;
    }

    if (drill) mem.drillSiteId = site.id;

    return {
      action: motor(vHold, omegaHold),
      drill: drill
    };
  }

  function executeCandidate(c) {
    if (c.kind === "site") {
      var site = c.obj;
      var live = !!(sensedSite && sensedSite.id === site.id);
      var d = live
        ? clamp(num(siteObs.distance, 99), 0, 50)
        : dist(mem.posX, mem.posY, site.x, site.y);
      var bearing = live ? num(siteObs.bearing, 0) : 0;

      var sa = sampleAction(site, live, d, bearing);
      return { action: sa.action, drill: sa.drill };
    }

    var hint = c.obj;
    if (!mem.search || mem.search.type !== "hint" ||
        mem.search.hintId !== hint.id) {
      var hd = dist(mem.posX, mem.posY, hint.x, hint.y);
      if (hd > 3.0) {
        return {
          action: goPoint(hint.x, hint.y, 2.0, 0.78),
          drill: false
        };
      }
      mem.search = makeSearch("hint", hint.id, hint.x, hint.y);
    }

    var result = searchStep(mem.search);
    return { action: result.action, drill: false };
  }

  function freeSearchStep() {
    if (!mem.search || mem.search.type !== "free") {
      mem.search = makeSearch("free", -1, mem.posX, mem.posY);
    }
    return searchStep(mem.search);
  }

  function executeSweep(index) {
