      }
    }
  }

  function markSampled(id) {
    var s = findSite(id);

    if (!s) {
      var nearest = null;
      var nearestD = 10;
      for (var i = 0; i < mem.sites.length; i++) {
        var candidate = mem.sites[i];
        if (candidate.state === 2) continue;
        var d = dist(mem.posX, mem.posY, candidate.x, candidate.y);
        if (d < nearestD) {
          nearest = candidate;
          nearestD = d;
        }
      }
      s = nearest;
    }

    var hid = s ? s.hintId : -1;
    if (s) {
      s.state = 2;

      if (hid < 0) {
        var nearestHint = null;
        var hintD = 29;
        for (var j = 0; j < mem.hints.length; j++) {
          var h0 = mem.hints[j];
          if (h0.assoc >= 0 || h0.state === 2) continue;
          var hd = dist(s.x, s.y, h0.x, h0.y);
          if (hd < hintD) {
            hintD = hd;
            nearestHint = h0;
          }
        }
        if (nearestHint) {
          hid = nearestHint.id;
          s.hintId = hid;
          nearestHint.assoc = s.id;
        }
      }
    }

    if (hid >= 0) {
      var h = findHint(hid);
      if (h) {
        h.state = 2;
        if (s) h.assoc = s.id;
      }
    }

    if (mem.task && mem.task.kind === "site" &&
        (!s || mem.task.id === s.id)) {
      mem.task = null;
      mem.search = null;
    } else if (mem.search && mem.search.type === "hint" &&
        mem.search.hintId === hid) {
      mem.search = null;
      if (mem.task && mem.task.kind === "hint" &&
          mem.task.id === hid) mem.task = null;
    } else if (mem.search && mem.search.type === "free") {
      mem.search = null;
    }

    mem.sampleSiteId = -1;
    mem.drillStarted = false;
    mem.drillStartTime = -1;
    mem.sampleAnchor = null;
    mem.sampleStableTime = 0;
  }

  var siteObs = obs.site || null;
  var sensedSite = null;
  if (siteObs && num(siteObs.distance, 99) <= 8.5) {
    sensedSite = recordSite(siteObs);
  }

  if (carried > mem.lastCarried + 0.01) {
    var sampledId = mem.sampleSiteId;
    if (sampledId < 0 && mem.task && mem.task.kind === "site") {
      sampledId = mem.task.id;
    }
    markSampled(sampledId);
  }

  if (carried < mem.lastCarried - 0.01) {
    mem.sampleSiteId = -1;
    mem.drillStarted = false;
    mem.drillStartTime = -1;
    mem.sampleAnchor = null;
    mem.sampleStableTime = 0;
  }
  mem.lastCarried = carried;

  var delivered = num(obs.delivered, mem.lastDelivered);
  var deliveredChanged = delivered > mem.lastDelivered + 0.001;
  mem.lastDelivered = delivered;

  var prevDesired = mem.lastDesiredV || 0;
  if (Math.abs(prevDesired) > 0.35 && !gpsFrozen) {
    if (mem.stuckStart < 0) {
      mem.stuckStart = now;
      mem.stuckX = mem.posX;
      mem.stuckY = mem.posY;
    }

    if (now - mem.stuckStart > 4.2) {
      var stuckDisp = dist(mem.posX, mem.posY, mem.stuckX, mem.stuckY);
      if (stuckDisp < 0.55 && Math.abs(wheelV) > 0.22 &&
          now - mem.lastBump > 2.5) {
        var clearLeft = 0;
        var clearRight = 0;
        for (var ai = 5; ai <= 8; ai++) clearLeft += mem.rays[ai];
        for (var bi = 0; bi <= 3; bi++) clearRight += mem.rays[bi];
        mem.recoverSide = clearLeft >= clearRight ? 1 : -1;
        mem.recoverStart = now;
        mem.recoverUntil = now + 1.2;
        mem.lastBump = now;
      }

      mem.stuckStart = now;
      mem.stuckX = mem.posX;
      mem.stuckY = mem.posY;
    }
  } else {
    mem.stuckStart = -1;
  }

  if (obs.bumped && !mem.bumpPrev && now - mem.lastBump > 1.5) {
    var lc = 0;
    var rc = 0;
    for (var li = 5; li <= 8; li++) lc += mem.rays[li];
    for (var ri2 = 0; ri2 <= 3; ri2++) rc += mem.rays[ri2];
    mem.recoverSide = lc >= rc ? 1 : -1;
    mem.recoverStart = now;
    mem.recoverUntil = now + 1.2;
    mem.lastBump = now;
  }
  mem.bumpPrev = !!obs.bumped;

  function rayAt(angle) {
    angle = clamp(angle, -80, 80);
    var index = (angle + 80) / 20;
    var lo = clamp(Math.floor(index), 0, 8);
    var hi = clamp(Math.ceil(index), 0, 8);
    var f = index - lo;
    return clamp(mem.rays[lo] * (1 - f) + mem.rays[hi] * f, 0, 15);
  }

  function sideClear(side) {
    var sum = 0;
    var count = 0;
    var start = side > 0 ? 5 : 0;
    var end = side > 0 ? 8 : 3;
    for (var i = start; i <= end; i++) {
      sum += mem.rays[i];
      count++;
    }
    return sum / Math.max(1, count);
  }

  function safeEpm() {
    return clamp(Math.max(0.00065, mem.epm * 1.42, mem.epmHigh * 1.2),
      0.00065, 0.025);
  }

  function finish(action, drill) {
    var l = clamp(num(action && action.l, 0), -1, 1);
    var r = clamp(num(action && action.r, 0), -1, 1);

    mem.lastCmdL = l;
    mem.lastCmdR = r;
    mem.lastWheelL = wheelL;
    mem.lastWheelR = wheelR;
    mem.lastDesiredV = num(action && action.v, 0);
    mem.lastDesiredOmega = num(action && action.omega, 0);
    mem.lastDrillCmd = !!drill;

    return { left: l, right: r, drill: !!drill };
  }

  function motor(v, omega, bias) {
    v = clamp(v, -0.9, 0.84);
    omega = clamp(omega, -1.2, 1.2);
    bias = clamp(num(bias, 0), -0.16, 0.16);

    var targetL = clamp(v - 0.3 * omega, -1.65, 1.65);
    var targetR = clamp(v + 0.3 * omega, -1.65, 1.65);

    function one(target, actual, side) {
      var gain = side === 0 ? mem.gainL : mem.gainR;
      var integral = side === 0 ? mem.iL : mem.iR;
      var prevCmd = side === 0 ? mem.lastCmdL : mem.lastCmdR;

      if (target * prevCmd < -0.025) integral *= 0.35;

      var err = target - actual;
      integral = clamp(integral +
        err * dt * 0.16 / Math.max(0.65, gain), -0.18, 0.18);

      var u = target / Math.max(0.65, gain) +
        0.42 * err / Math.max(0.65, gain) +
        integral +
        bias;

      if (Math.abs(target) > 0.055) {
        u += target > 0 ? 0.045 : -0.045;
      }

      u = clamp(u, -1, 1);

      if (side === 0) mem.iL = integral;
      else mem.iR = integral;

      return u;
    }

    return {
      l: one(targetL, wheelL, 0),
      r: one(targetR, wheelR, 1),
      v: v,
      omega: omega
    };
  }

  function zeroAction() {
    if (docked) return { l: 0, r: 0, v: 0, omega: 0 };
    var pitchFF = clamp(0.15 * Math.sin(num(obs.pitch, 0) * RAD),
      -0.12, 0.12);
    return motor(0, 0, pitchFF);
  }

  function chooseDirection(goalRel) {
    goalRel = wrap(goalRel);
    var direct = clamp(goalRel, -80, 80);
    var front = rayAt(0);
    var directClear = rayAt(direct);

    if (front > 5.2 && directClear > 5.0) {
      if (front > 8.5 && directClear > 8.5) mem.avoidSide = 0;
      return { angle: direct, clear: directClear, front: front };
    }

    if (mem.avoidSide === 0) {
      mem.avoidSide = sideClear(1) >= sideClear(-1) ? 1 : -1;
    }

    var candidates = [-80, -60, -40, -20, 0, 20, 40, 60, 80, direct];
    var bestA = direct;
    var bestC = directClear;
    var bestScore = Infinity;

    for (var i = 0; i < candidates.length; i++) {
      var a = candidates[i];
      var clear = rayAt(a);
      var deviation = Math.abs(wrap(a - goalRel));
      var shortfall = Math.max(0, 6.5 - clear);
      var score = deviation + 8.0 * shortfall;

      if (clear < 2.0) score += 75;
      if (clear < 1.0) score += 120;
      if (Math.abs(a) > 10 && Math.sign(a) !== mem.avoidSide) {
        score += 2.0;
      }

      if (score < bestScore) {
        bestScore = score;
        bestA = a;
        bestC = clear;
      }
    }

    return { angle: bestA, clear: bestC, front: front };
  }

  function driveRel(rel, distance, stopRadius, maxV) {
    rel = wrap(rel);
    distance = Math.max(0, num(distance, 0));
    stopRadius = Math.max(0, stopRadius);

    if (distance <= stopRadius + 0.08) return zeroAction();

    var absGoal = (mem.hEst + rel) * RAD;
    var dirX = Math.cos(absGoal);
    var dirY = Math.sin(absGoal);
    var edgeOut =
      (mem.posX < 5 && dirX < -0.12) ||
      (mem.posX > mem.mapW - 5 && dirX > 0.12) ||
      (mem.posY < 5 && dirY < -0.12) ||
      (mem.posY > mem.mapH - 5 && dirY > 0.12);

    if (edgeOut) {
      var centerBearing = Math.atan2(mem.mapH * 0.5 - mem.posY,
        mem.mapW * 0.5 - mem.posX) / RAD;
      rel = wrap(centerBearing - mem.hEst);
    }

    if (Math.abs(rel) > 72) {
      var turnOmega = clamp(1.75 * rel * RAD -
        0.42 * ((wheelR - wheelL) / 0.6), -1.12, 1.12);
      var pitchTurn = clamp(0.12 * Math.sin(num(obs.pitch, 0) * RAD),
        -0.10, 0.10);
      return motor(0, turnOmega, pitchTurn);
    }

    var info = chooseDirection(rel);
    var steer = info.angle;
    var remain = Math.max(0, distance - stopRadius);
    var speed = Math.min(maxV, Math.sqrt(0.68 * remain));

    if (Math.abs(steer) > 54) speed = 0;
    else if (Math.abs(steer) > 39) speed = Math.min(speed, 0.32);
    else if (Math.abs(steer) > 27) speed = Math.min(speed, 0.52);

    if (Math.abs(wrap(steer - rel)) > 35) speed *= 0.65;

    if (info.clear < 1.7) speed = Math.min(speed, 0.10);
    else if (info.clear < 2.7) speed = Math.min(speed, 0.18);
    else if (info.clear < 4.2) speed = Math.min(speed, 0.34);
    else if (info.clear < 6.0) speed = Math.min(speed, 0.55);

    if (info.front < 1.6) speed = Math.min(speed, 0.10);
    else if (info.front < 2.5) speed = Math.min(speed, 0.18);
    else if (info.front < 3.8) speed = Math.min(speed, 0.34);

    if (edgeOut) speed = Math.min(speed, 0.28);

    var yawRate = (wheelR - wheelL) / 0.6;
    var omega = clamp(2.05 * steer * RAD - 0.48 * yawRate,
      -1.15, 1.15);
    if (Math.abs(steer) < 1.5 && Math.abs(yawRate) < 0.12) omega = 0;

    var pitchFF = clamp(0.12 * Math.sin(num(obs.pitch, 0) * RAD),
      -0.10, 0.10);
    return motor(speed, omega, pitchFF);
  }

  function goPoint(x, y, stopRadius, maxV) {
    x = clamp(x, 1.5, mem.mapW - 1.5);
    y = clamp(y, 1.5, mem.mapH - 1.5);

    var dx = x - mem.posX;
    var dy = y - mem.posY;
    var d = Math.hypot(dx, dy);
    var rel = d < 0.01 ? 0 :
      wrap(Math.atan2(dy, dx) / RAD - mem.hEst);

    return driveRel(rel, d, stopRadius, maxV);
  }

  var beacon = obs.beacon || null;
  var gpsBaseDist = dist(mem.posX, mem.posY, mem.baseX, mem.baseY);
  var hasBeacon = beacon && num(beacon.distance, 99) <= 20.5;
  var baseDist = hasBeacon ?
    clamp(num(beacon.distance, gpsBaseDist), 0, 25) :
    gpsBaseDist;

  function goBase(stopRadius) {
    if (hasBeacon) {
      return driveRel(num(beacon.bearing, 0),
        num(beacon.distance, baseDist), stopRadius, 0.82);
    }

    var dx = mem.baseX - mem.posX;
    var dy = mem.baseY - mem.posY;
    var d = Math.hypot(dx, dy);
    var rel = d < 0.01 ? 0 :
      wrap(Math.atan2(dy, dx) / RAD - mem.hEst);

    return driveRel(rel, d, stopRadius, 0.82);
  }

  function recoveryAction() {
    if (now >= mem.recoverUntil) return null;
    var elapsed = now - mem.recoverStart;
    if (elapsed < 0.38) {
      return motor(-0.24, mem.recoverSide * 0.16, 0);
    }
    return motor(0, mem.recoverSide * 0.78, 0);
  }

  function makePoint(x, y) {
    return {
      x: clamp(x, 2, mem.mapW - 2),
      y: clamp(y, 2, mem.mapH - 2)
    };
  }

  function setSearchPoints(s, stage, points) {
    s.stage = stage;
    s.points = points;
    s.idx = 0;
    s.waitAt = -1;
    s.sum = 0;
    s.count = 0;
  }

  function startSearch(type, hintId, x, y) {
    mem.search = {
      type: type,
      hintId: hintId,
      cx: x,
      cy: y,
      stage: "center",
      points: [makePoint(x, y)],
      idx: 0,
      waitAt: -1,
      sum: 0,
      count: 0,
      centerS: 0,
      crossVals: [0, 0, 0, 0],
      diagVals: [0, 0, 0, 0],
      refineVals: [0, 0, 0, 0],
      bestS: 0,
      bestX: x,
      bestY: y,
      dirX: 1,
      dirY: 0,
      hillSteps: 0,
      refineBaseS: 0
    };
  }

  function saveSearchBest(s, x, y, value) {
    if (value > s.bestS) {
      s.bestS = value;
      s.bestX = x;
      s.bestY = y;
    }
  }

  function finishSearch(s) {
    if (s.type === "hint") {
      var h = findHint(s.hintId);
      if (h && h.state !== 2 && h.assoc < 0) h.state = 3;

      if (mem.task && mem.task.kind === "hint" &&
          mem.task.id === s.hintId) {
        mem.task = null;
      }
    } else {
      mem.freeDone.push({ x: s.cx, y: s.cy });
      if (mem.freeDone.length > 100) mem.freeDone.shift();
    }

    if (mem.search === s) mem.search = null;
  }

  function beginHill(s, gx, gy) {
    var n = Math.hypot(gx, gy);

    if (n < 1e-8) {
      gx = s.bestX - s.cx;
      gy = s.bestY - s.cy;
      n = Math.hypot(gx, gy);
    }

    if (n < 1e-8) {
      var seed = s.type === "hint" ? s.hintId + 1 : Math.floor(now) + 1;
      var a = seed * 2.399963;
      gx = Math.cos(a);
      gy = Math.sin(a);
      n = 1;
    }

    s.dirX = gx / n;
    s.dirY = gy / n;
    s.hillSteps = 0;

    setSearchPoints(s, "hill", [
      makePoint(s.bestX + 6 * s.dirX, s.bestY + 6 * s.dirY)
    ]);
  }

  function beginRefine(s) {
    s.refineBaseS = s.bestS;
    setSearchPoints(s, "refine", [
      makePoint(s.bestX + 6, s.bestY),
      makePoint(s.bestX, s.bestY + 6),
      makePoint(s.bestX - 6, s.bestY),
      makePoint(s.bestX, s.bestY - 6)
    ]);
  }

  function searchAction() {
    var s = mem.search;
    if (!s) return zeroAction();

    if (s.idx >= s.points.length) {
      finishSearch(s);
      return zeroAction();
    }

    var p = s.points[s.idx];
    var d = dist(mem.posX, mem.posY, p.x, p.y);

    if (d > 2.25) {
      s.waitAt = -1;
      s.sum = 0;
      s.count = 0;
      return goPoint(p.x, p.y, 1.55, 0.68);
    }

    if (s.waitAt < 0) {
      s.waitAt = now;
      s.sum = 0;
      s.count = 0;
    }

    s.sum += science;
    s.count++;

    if (now - s.waitAt < 0.45) return zeroAction();

    var value = s.sum / Math.max(1, s.count);
    var px = p.x;
    var py = p.y;
    var oldBest = s.bestS;
    s.waitAt = -1;
    s.sum = 0;
    s.count = 0;

    if (s.stage !== "hill") saveSearchBest(s, px, py, value);

    if (s.stage === "center") {
      s.centerS = value;
      setSearchPoints(s, "cross", [
        makePoint(s.cx + 9, s.cy),
        makePoint(s.cx, s.cy + 9),
        makePoint(s.cx - 9, s.cy),
        makePoint(s.cx, s.cy - 9)
      ]);
      return zeroAction();
    }

    if (s.stage === "cross") {
      var ci = s.idx;
      s.crossVals[ci] = value;
      s.idx++;

      if (s.idx < 4) return zeroAction();

      var cv = s.crossVals;
      var maxCross = Math.max(s.centerS, cv[0], cv[1], cv[2], cv[3]);
      if (maxCross <= 0.000001) {
        finishSearch(s);
        return zeroAction();
      }

      var gx = (cv[0] - cv[2]) / 18;
      var gy = (cv[1] - cv[3]) / 18;
      var gmag = Math.hypot(gx, gy);
      var threshold = Math.max(0.0000002, maxCross * 0.0014);

      if (gmag > threshold) {
        beginHill(s, gx, gy);
      } else {
        setSearchPoints(s, "diag", [
          makePoint(s.cx + 13, s.cy + 13),
          makePoint(s.cx - 13, s.cy + 13),
          makePoint(s.cx - 13, s.cy - 13),
          makePoint(s.cx + 13, s.cy - 13)
        ]);
      }
      return zeroAction();
    }

    if (s.stage === "diag") {
      var di = s.idx;
      s.diagVals[di] = value;
      s.idx++;

      if (s.idx < 4) return zeroAction();

      if (s.bestS <= 0.000001) {
        finishSearch(s);
        return zeroAction();
      }

      var dgx = (s.diagVals[0] + s.diagVals[3] -
        s.diagVals[1] - s.diagVals[2]);
      var dgy = (s.diagVals[0] + s.diagVals[1] -
        s.diagVals[2] - s.diagVals[3]);

      if (Math.hypot(dgx, dgy) < 1e-8) {
        dgx = s.bestX - s.cx;
        dgy = s.bestY - s.cy;
      }

      beginHill(s, dgx, dgy);
      return zeroAction();
    }

    if (s.stage === "hill") {
      var tol = Math.max(0.0000002, s.bestS * 0.02);
      s.hillSteps++;

      if (value >= oldBest - tol && s.hillSteps <= 6) {
        if (value > s.bestS) {
          s.bestS = value;
        }
        s.bestX = px;
        s.bestY = py;

        if (s.hillSteps >= 6) {
          finishSearch(s);
          return zeroAction();
        }

        setSearchPoints(s, "hill", [
          makePoint(px + 6 * s.dirX, py + 6 * s.dirY)
        ]);
        return zeroAction();
      }

      beginRefine(s);
      return zeroAction();
    }

    if (s.stage === "refine") {
      var ri3 = s.idx;
      s.refineVals[ri3] = value;
      s.idx++;

      if (s.idx < 4) return zeroAction();

      var improveTol = Math.max(0.0000002, s.refineBaseS * 0.025);
      if (s.bestS > s.refineBaseS + improveTol) {
        var rgx = (s.refineVals[0] - s.refineVals[2]) / 12;
        var rgy = (s.refineVals[1] - s.refineVals[3]) / 12;
        if (Math.hypot(rgx, rgy) < 1e-8) {
          rgx = s.bestX - px;
          rgy = s.bestY - py;
        }
        beginHill(s, rgx, rgy);
      } else {
        finishSearch(s);
      }
      return zeroAction();
    }

    finishSearch(s);
    return zeroAction();
  }

  function freeNear(x, y) {
    for (var i = 0; i < mem.freeDone.length; i++) {
      if (dist(x, y, mem.freeDone[i].x, mem.freeDone[i].y) < 18) {
        return true;
      }
    }
    return false;
  }

  function ensureGrid() {
    if (mem.gridPts) return;

    mem.gridPts = [];
    mem.gridDone = [];

    var step = 75;
    var startX = Math.min(35, mem.mapW * 0.5);
    var startY = Math.min(35, mem.mapH * 0.5);

    for (var y = startY; y <= mem.mapH - 20; y += step) {
      for (var x = startX; x <= mem.mapW - 20; x += step) {
        mem.gridPts.push({ x: x, y: y });
        mem.gridDone.push(false);
      }
    }

    if (mem.gridPts.length === 0) {
      mem.gridPts.push({ x: mem.mapW * 0.5, y: mem.mapH * 0.5 });
      mem.gridDone.push(false);
    }
  }

  function calcMetrics(pathOut, back, extraTime) {
    pathOut = Math.max(0, pathOut);
    back = Math.max(0, back);

    var load = 1 + 0.12 * carried;
    var rate = safeEpm();
    var work = (1.27 * pathOut + 1.46 * (back + 5)) * load;
    var need = rate * work + 0.105 + 0.018 * carried +
      6 * mem.drillRate;
    var speedForPlan = Math.max(0.42, Math.min(1.25,
      mem.speedAvg * 0.78));
    var time = (pathOut + back) / speedForPlan +
      22 + 6 * (carried + 1) + Math.max(0, extraTime || 0);

    return {
      need: Math.max(0.02, need),
      time: time,
      path: pathOut,
      back: back
    };
  }

  function candidateMetrics(kind, obj) {
    var out = dist(mem.posX, mem.posY, obj.x, obj.y);
    var back = dist(obj.x, obj.y, mem.baseX, mem.baseY);
    var extra = kind === "hint" ? 45 : 0;
    var backPad = kind === "hint" ? 10 : 0;
    var m = calcMetrics(out + extra, back + backPad, 0);
    m.out = out;
    m.back = back;
    m.extra = extra;
    m.value = obj.value;
    return m;
  }

  function searchMetrics(s) {
    var path = 0;
    var px = mem.posX;
    var py = mem.posY;
    var endX = mem.posX;
    var endY = mem.posY;

    if (s && s.points) {
      for (var i = s.idx; i < s.points.length; i++) {
        path += dist(px, py, s.points[i].x, s.points[i].y);
        px = s.points[i].x;
        py = s.points[i].y;
        endX = px;
        endY = py;
      }

      if (s.stage === "center") path += 45;
      else if (s.stage === "cross") path += 15;
      else if (s.stage === "diag") path += 12;
      else if (s.stage === "hill") {
        path += Math.max(0, 6 - s.hillSteps) * 6;
      }
    }

    if (s && s.type === "free" && mem.task) {
      if (mem.task.kind === "hint") {
