    var predY = mem.posY + wheelV * dt * Math.sin(midH);

    if (gpsFrozen) {
      mem.posX = predX;
      mem.posY = predY;
    } else {
      var ex = rawX - predX;
      var ey = rawY - predY;
      var errLen = Math.hypot(ex, ey);
      var posAlpha = Math.abs(wheelV) > 0.15 ? 0.34 : 0.22;

      if (thawed) posAlpha = 0.55;
      if (errLen > 14 && !thawed) posAlpha = 0.025;
      if (errLen > 35 && thawed) posAlpha = 0.3;

      mem.posX = predX + posAlpha * ex;
      mem.posY = predY + posAlpha * ey;
    }

    dPos = dist(mem.posX, mem.posY, oldPX, oldPY);

    if (!gpsFrozen) {
      var groundSpeed = dPos / Math.max(dt, 0.04);
      if (groundSpeed < 4) {
        mem.gpsSpeed = 0.82 * mem.gpsSpeed + 0.18 * groundSpeed;
      }
    } else {
      mem.gpsSpeed = 0.85 * mem.gpsSpeed + 0.15 * Math.abs(wheelV);
    }

    var straight = !gpsFrozen &&
      (mem.lastDesiredV || 0) > 0.3 &&
      Math.abs(mem.lastDesiredOmega || 0) < 0.14 &&
      wheelV > 0.25 &&
      Math.abs(wheelR - wheelL) < 0.34;

    if (straight) {
      if (!mem.calOn) {
        mem.calOn = true;
        mem.calX = rawX;
        mem.calY = rawY;
        mem.calTime = 0;
        mem.calSin = 0;
        mem.calCos = 0;
      }

      mem.calTime += dt;
      mem.calSin += Math.sin(rawH * RAD);
      mem.calCos += Math.cos(rawH * RAD);

      if (dist(rawX, rawY, mem.calX, mem.calY) > 5 &&
          mem.calTime > 3.5) {
        var course = Math.atan2(rawY - mem.calY, rawX - mem.calX) / RAD;
        var avgCompass = Math.atan2(mem.calSin, mem.calCos) / RAD;
        var measuredBias = wrap(course - avgCompass);

        if (Math.abs(measuredBias) < 40) {
          mem.headingBias = wrap(0.85 * mem.headingBias +
            0.15 * measuredBias);
        }

        mem.calX = rawX;
        mem.calY = rawY;
        mem.calTime = 0;
        mem.calSin = 0;
        mem.calCos = 0;
      }
    } else {
      mem.calOn = false;
    }
  }

  mem.prevGpsFrozen = gpsFrozen;
  mem.gpsFrozen = gpsFrozen;
  mem.lastRawH = rawH;
  mem.lastGX = rawX;
  mem.lastGY = rawY;
  mem.lastT = now;

  function updateGain(side, cmd, actual) {
    var gainName = side === 0 ? "gainL" : "gainR";
    var failName = side === 0 ? "failL" : "failR";
    var g = mem[gainName];
    var fail = mem[failName];

    if (Math.abs(cmd) > 0.13 && actual * cmd > 0.002 &&
        Math.abs(actual) < 2.8) {
      var observed = Math.abs(actual) /
        Math.max(0.07, Math.abs(cmd) - 0.035);
      if (observed > 0.5 && observed < 5.5) {
        mem[gainName] = clamp(0.992 * g + 0.008 * observed, 0.55, 5.3);
      }
      fail = 0;
    } else if (Math.abs(cmd) > 0.38 && Math.abs(actual) < 0.035) {
      fail += dt;
      if (fail > 1.5) {
        mem[gainName] = Math.max(0.55, g * 0.88);
        fail = 0;
      }
    } else {
      fail = Math.max(0, fail - dt * 0.5);
    }

    mem[failName] = fail;
  }

  updateGain(0, mem.lastCmdL || 0, wheelL);
  updateGain(1, mem.lastCmdR || 0, wheelR);

  var energyNet = 0;
  if (mem.energyReady) {
    energyNet = mem.lastBattery - battery +
      0.5 * (mem.lastSolar + solar) * dt;

    if (!docked && !mem.prevDocked &&
        Math.abs(mem.lastDesiredV || 0) > 0.18 &&
        Math.abs(wheelV) > 0.1 &&
        !mem.lastDrillCmd) {
      mem.energyWindow += energyNet;
      mem.energyDistance += Math.max(dPos, Math.abs(wheelV) * dt * 0.55);
      mem.energyTime += dt;

      if (mem.energyTime >= 8) {
        if (mem.energyDistance > 3 && mem.energyWindow > 0.0002) {
          var measuredEpm = mem.energyWindow / mem.energyDistance;
          if (measuredEpm > 0.00015 && measuredEpm < 0.05) {
            mem.epm = 0.8 * mem.epm + 0.2 * measuredEpm;
            mem.epmHigh = Math.max(mem.epmHigh * 0.996,
              measuredEpm * 1.25);
          }
        }

        mem.energyWindow = 0;
        mem.energyDistance = 0;
        mem.energyTime = 0;
      }
    } else if (docked || mem.prevDocked) {
      mem.energyWindow = 0;
      mem.energyDistance = 0;
      mem.energyTime = 0;
    }
  }

  mem.energyReady = true;
  mem.lastBattery = battery;
  mem.lastSolar = solar;
  mem.prevDocked = docked;

  var rayInput = obs.rays || [];
  mem.rayMoved += dPos;

  for (var ri = 0; ri < 9; ri++) {
    var rv = clamp(num(rayInput[ri], 15), 0, 15);

    if (mem.rayLast[ri] !== undefined &&
        Math.abs(rv - mem.rayLast[ri]) < 0.015) {
      mem.raySame[ri] = (mem.raySame[ri] || 0) + 1;
    } else {
      mem.raySame[ri] = 0;
      mem.rayBad[ri] = false;
    }

    if (mem.raySame[ri] > 120 && rv < 14.5 && mem.rayMoved > 6) {
      mem.rayBad[ri] = true;
    }

    mem.rayLast[ri] = rv;
    mem.rays[ri] = mem.rayBad[ri] ? 15 : rv;
  }

  function rayAt(angle) {
    angle = clamp(angle, -80, 80);
    var index = (angle + 80) / 20;
    var lo = clamp(Math.floor(index), 0, 8);
    var hi = clamp(Math.ceil(index), 0, 8);
    var f = index - lo;
    return clamp(mem.rays[lo] * (1 - f) + mem.rays[hi] * f, 0, 15);
  }

  function sideClear(side) {
    var start = side > 0 ? 5 : 0;
    var end = side > 0 ? 8 : 3;
    var sum = 0;
    var count = 0;
    for (var i = start; i <= end; i++) {
      sum += mem.rays[i];
      count++;
    }
    return sum / Math.max(1, count);
  }

  function startRecovery(side) {
    mem.recoverStart = now;
    mem.recoverUntil = now + 1.05;
    mem.recoverSide = side || 1;
    mem.lastBump = now;
    mem.stuckStart = -1;
  }

  if (!mem.sampleActive && drillProgress <= 0.01 &&
      obs.bumped && !mem.bumpPrev && now - mem.lastBump > 1.4) {
    startRecovery(sideClear(1) >= sideClear(-1) ? 1 : -1);
  }
  mem.bumpPrev = !!obs.bumped;

  if (!mem.sampleActive &&
      Math.abs(mem.lastDesiredV || 0) > 0.38 &&
      Math.abs(wheelV) > 0.2 &&
      !gpsFrozen) {
    if (mem.stuckStart < 0) {
      mem.stuckStart = now;
      mem.stuckX = mem.posX;
      mem.stuckY = mem.posY;
    } else if (now - mem.stuckStart > 5.5) {
      var stuckDisp = dist(mem.posX, mem.posY, mem.stuckX, mem.stuckY);
      if (stuckDisp < 0.55 && now - mem.lastBump > 2) {
        startRecovery(sideClear(1) >= sideClear(-1) ? 1 : -1);
      } else {
        mem.stuckStart = now;
        mem.stuckX = mem.posX;
        mem.stuckY = mem.posY;
      }
    }
  } else {
    mem.stuckStart = -1;
  }

  function findHint(id) {
    for (var i = 0; i < mem.hints.length; i++) {
      if (mem.hints[i].id === id) return mem.hints[i];
    }
    return null;
  }

  function findSite(id) {
    for (var i = 0; i < mem.sites.length; i++) {
      if (mem.sites[i].id === id) return mem.sites[i];
    }
    return null;
  }

  function recordSite(siteObs) {
    var sd = clamp(num(siteObs.distance, 99), 0, 50);
    var rel = num(siteObs.bearing, 0);
    var abs = (mem.hEst + rel) * RAD;
    var sx = clamp(mem.posX + sd * Math.cos(abs), 0, mem.mapW);
    var sy = clamp(mem.posY + sd * Math.sin(abs), 0, mem.mapH);
    var value = Math.max(0.01, num(siteObs.value, 0.5));

    var best = null;
    var bestD = 10;

    for (var i = 0; i < mem.sites.length; i++) {
      var s = mem.sites[i];
      if (s.state === 2) continue;
      var d = dist(sx, sy, s.x, s.y);
      if (d < bestD) {
        bestD = d;
        best = s;
      }
    }

    if (!best) {
      best = {
        id: mem.nextSiteId++,
        x: sx,
        y: sy,
        value: value,
        state: 0,
        hintId: -1,
        lastSeen: now
      };
      mem.sites.push(best);
    } else {
      best.x = 0.72 * best.x + 0.28 * sx;
      best.y = 0.72 * best.y + 0.28 * sy;
      best.value = 0.72 * best.value + 0.28 * value;
      best.lastSeen = now;
      if (best.state === 3) best.state = 0;
    }

    if (best.hintId < 0) {
      var nearestHint = null;
      var nearD = 28;

      for (var j = 0; j < mem.hints.length; j++) {
        var h = mem.hints[j];
        if (h.state === 2 || (h.assoc >= 0 && h.assoc !== best.id)) continue;
        var hd = dist(best.x, best.y, h.x, h.y);
        if (hd < nearD) {
          nearD = hd;
          nearestHint = h;
        }
      }

      if (nearestHint) {
        best.hintId = nearestHint.id;
        nearestHint.assoc = best.id;
        if (nearestHint.state !== 2) nearestHint.state = 1;
      }
    }

    if (best.hintId >= 0) {
      var linkedHint = findHint(best.hintId);
      if (linkedHint && linkedHint.state !== 2) {
        linkedHint.assoc = best.id;
        linkedHint.state = 1;
      }
    }

    mem.currentSiteId = best.id;
    return best;
  }

  function taskStillValid(t) {
    if (!t) return false;

    if (t.kind === "site") {
      var s = findSite(t.id);
      return !!s && s.state !== 2;
    }

    if (t.kind === "hint") {
      var h = findHint(t.id);
      return !!h && (h.state === 0 || h.state === 1) && h.assoc < 0;
    }

    if (t.kind === "grid") {
      ensureGrid();
      return !!mem.gridPts[t.id] && !mem.gridDone[t.id];
    }

    if (t.kind === "free") {
      return !!mem.search && mem.search.kind === "free";
    }

    return false;
  }

  function restoreResume() {
    if (mem.resumeTask && taskStillValid(mem.resumeTask)) {
      mem.task = { kind: mem.resumeTask.kind, id: mem.resumeTask.id };
    }
    mem.resumeTask = null;
  }

  function markSampled(id) {
    var s = id >= 0 ? findSite(id) : null;

    if (!s) {
      var closest = null;
      var closestD = 12;
      for (var i = 0; i < mem.sites.length; i++) {
        var ss = mem.sites[i];
        if (ss.state === 2) continue;
        var dd = dist(mem.posX, mem.posY, ss.x, ss.y);
        if (dd < closestD) {
          closestD = dd;
          closest = ss;
        }
      }
      s = closest;
    }

    var hid = s ? s.hintId : -1;
    if (s) {
      s.state = 2;

      if (hid < 0) {
        var nearest = null;
        var nearestD = 29;
        for (var j = 0; j < mem.hints.length; j++) {
          var hh = mem.hints[j];
          if (hh.state === 2 || (hh.assoc >= 0 && hh.assoc !== s.id)) continue;
          var hd = dist(s.x, s.y, hh.x, hh.y);
          if (hd < nearestD) {
            nearestD = hd;
            nearest = hh;
          }
        }
        if (nearest) {
          hid = nearest.id;
          s.hintId = hid;
          nearest.assoc = s.id;
        }
      }
    }

    if (hid < 0 && mem.task && mem.task.kind === "hint") {
      var activeHint = findHint(mem.task.id);
      if (activeHint) {
        var siteDistance = s ? dist(s.x, s.y, activeHint.x, activeHint.y) : 0;
        if (!s || siteDistance < 30) hid = activeHint.id;
      }
    }

    if (hid >= 0) {
      var h = findHint(hid);
      if (h) {
        h.state = 2;
        if (s) h.assoc = s.id;
      }
    }

    if (mem.search && mem.search.kind === "hint" &&
        mem.search.id === hid) {
      mem.search = null;
    }

    if (mem.task && mem.task.kind === "site" &&
        (!s || mem.task.id === s.id)) {
      mem.task = null;
    } else if (mem.task && mem.task.kind === "hint" &&
        mem.task.id === hid) {
      mem.task = null;
      mem.search = null;
    }

    if (mem.resumeTask && mem.resumeTask.kind === "site" &&
        s && mem.resumeTask.id === s.id) {
      mem.resumeTask = null;
    }
    if (mem.resumeTask && mem.resumeTask.kind === "hint" &&
        mem.resumeTask.id === hid) {
      mem.resumeTask = null;
    }

    mem.sampleSiteId = -1;
    mem.sampleActive = false;
    mem.sampleStart = -1;
    mem.sampleAnchor = null;
    mem.sampleStable = 0;

    if (!mem.task) restoreResume();
  }

  var siteObs = obs.site || null;
  var sensedSite = null;
  if (siteObs && num(siteObs.distance, 99) <= 8.5) {
    sensedSite = recordSite(siteObs);
  }

  if (carried > mem.lastCarried + 0.01) {
    var sampledId = mem.sampleSiteId;
    if (sampledId < 0 && mem.task && mem.task.kind === "site") {
      sampledId = mem.task.id;
    }
    markSampled(sampledId);
  } else if (carried < mem.lastCarried - 0.01) {
    mem.sampleSiteId = -1;
    mem.sampleActive = false;
    mem.sampleStart = -1;
    mem.sampleAnchor = null;
    mem.sampleStable = 0;
  }
  mem.lastCarried = carried;

  var delivered = num(obs.delivered, mem.lastDelivered);
  if (delivered > mem.lastDelivered + 0.001) {
    mem.returning = false;
  }
  mem.lastDelivered = delivered;

  var beacon = obs.beacon || null;
  var gpsBaseDist = dist(mem.posX, mem.posY, mem.baseX, mem.baseY);
  var hasBeacon = beacon && num(beacon.distance, 99) <= 20.5;
  var baseDist = hasBeacon
    ? clamp(num(beacon.distance, gpsBaseDist), 0, 25)
    : gpsBaseDist;

  function safeEpm() {
    return clamp(Math.max(0.00075, mem.epm * 1.32, mem.epmHigh * 1.08),
      0.00075, 0.025);
  }

  function finish(action, drill) {
    var l = clamp(num(action && action.l, 0), -1, 1);
    var r = clamp(num(action && action.r, 0), -1, 1);

    mem.lastCmdL = l;
    mem.lastCmdR = r;
    mem.lastDesiredV = num(action && action.v, 0);
    mem.lastDesiredOmega = num(action && action.omega, 0);
    mem.lastDrillCmd = !!drill;

    return { left: l, right: r, drill: !!drill };
  }

  function motor(v, omega) {
    v = clamp(v, -0.95, 0.88);
    omega = clamp(omega, -1.0, 1.0);

    var targetL = clamp(v - 0.3 * omega, -1.2, 1.2);
    var targetR = clamp(v + 0.3 * omega, -1.2, 1.2);

    function one(target, actual, side) {
      var gain = side === 0 ? mem.gainL : mem.gainR;
      var integral = side === 0 ? mem.iL : mem.iR;
      var prevTarget = side === 0 ? mem.prevTargetL : mem.prevTargetR;

      if (target * prevTarget < -0.02 ||
          Math.abs(target - prevTarget) > 0.8) {
        integral *= 0.4;
      }

      var err = target - actual;
      integral = clamp(integral +
        err * dt * 0.07 / Math.max(0.7, gain), -0.12, 0.12);

      var u = target / Math.max(0.7, gain) +
        0.48 * err / Math.max(0.7, gain) +
        integral;

      if (Math.abs(target) > 0.06) {
        u += target > 0 ? 0.035 : -0.035;
      }

      u = clamp(u, -1, 1);

      if (side === 0) {
        mem.iL = integral;
        mem.prevTargetL = target;
      } else {
        mem.iR = integral;
        mem.prevTargetR = target;
      }

      return u;
    }

    return {
      l: one(targetL, wheelL, 0),
      r: one(targetR, wheelR, 1),
      v: v,
      omega: omega
    };
  }

  function chooseDirection(goalRel) {
    goalRel = wrap(goalRel);
    var direct = clamp(goalRel, -80, 80);
    var directClear = rayAt(direct);

    if (directClear > 4.5) {
      mem.avoidSide = 0;
      return { angle: direct, clear: directClear };
    }

    if (!mem.avoidSide) {
      mem.avoidSide = sideClear(1) >= sideClear(-1) ? 1 : -1;
    }

    var candidates = [-80, -60, -40, -20, 0, 20, 40, 60, 80, direct];
    var bestA = direct;
    var bestClear = directClear;
    var bestCost = Infinity;

    for (var i = 0; i < candidates.length; i++) {
      var a = candidates[i];
      var clear = rayAt(a);
      var dev = Math.abs(wrap(a - goalRel));
      var cost = dev;

      if (clear < 1.1) cost += 220 + (1.1 - clear) * 35;
      else if (clear < 2.5) cost += 85 + (2.5 - clear) * 24;
      else if (clear < 4.5) cost += (4.5 - clear) * 13;

      if (Math.abs(a) > 10 && Math.sign(a) !== mem.avoidSide) {
        cost += 2.5;
      }
      if (Math.abs(a - (mem.lastSteer || 0)) < 14) cost -= 0.5;

      if (cost < bestCost) {
        bestCost = cost;
        bestA = a;
        bestClear = clear;
      }
    }

    mem.lastSteer = bestA;
    return { angle: bestA, clear: bestClear };
  }

  function driveRel(rel, distance, stopRadius, maxV) {
    rel = wrap(rel);
    distance = Math.max(0, num(distance, 0));
    stopRadius = Math.max(0, stopRadius);

    if (distance <= stopRadius + 0.08) return motor(0, 0);

    var absGoal = (mem.hEst + rel) * RAD;
    var dirX = Math.cos(absGoal);
    var dirY = Math.sin(absGoal);
    var edgeOut =
      (mem.posX < 3 && dirX < -0.18) ||
      (mem.posX > mem.mapW - 3 && dirX > 0.18) ||
      (mem.posY < 3 && dirY < -0.18) ||
      (mem.posY > mem.mapH - 3 && dirY > 0.18);

    if (edgeOut) {
      var centerBearing = Math.atan2(mem.mapH * 0.5 - mem.posY,
        mem.mapW * 0.5 - mem.posX) / RAD;
      rel = wrap(centerBearing - mem.hEst);
    }

    var remain = Math.max(0, distance - stopRadius);
    if (Math.abs(rel) > 78) {
      var turnOmega = clamp(1.15 * rel * RAD - 0.28 * yawRate,
        -0.65, 0.65);
      return motor(0, turnOmega);
    }

    var info = chooseDirection(rel);
    var steer = info.angle;
    var speed = Math.min(maxV, Math.sqrt(0.72 * remain));

    if (Math.abs(steer) > 58) speed = Math.min(speed, 0.12);
    else if (Math.abs(steer) > 44) speed = Math.min(speed, 0.28);
    else if (Math.abs(steer) > 30) speed = Math.min(speed, 0.52);

    if (Math.abs(wrap(steer - rel)) > 32) speed *= 0.65;

    if (info.clear < 1.1) speed = Math.min(speed, 0.08);
    else if (info.clear < 2.2) speed = Math.min(speed, 0.18);
    else if (info.clear < 3.6) speed = Math.min(speed, 0.34);
    else if (info.clear < 5.0) speed = Math.min(speed, 0.58);

    var front = rayAt(0);
    if (front < 1.2) speed = Math.min(speed, 0.08);
    else if (front < 2.2) speed = Math.min(speed, 0.18);
    else if (front < 3.6) speed = Math.min(speed, 0.34);

    if (edgeOut) speed = Math.min(speed, 0.28);

    var omega = clamp(1.2 * steer * RAD - 0.28 * yawRate, -0.65, 0.65);
    if (Math.abs(steer) < 1.2 && Math.abs(yawRate) < 0.1) omega = 0;

    return motor(speed, omega);
  }

  function goPoint(x, y, stopRadius, maxV) {
    x = clamp(x, 2, mem.mapW - 2);
    y = clamp(y, 2, mem.mapH - 2);

    var dx = x - mem.posX;
    var dy = y - mem.posY;
    var d = Math.hypot(dx, dy);
    var rel = d < 0.01
      ? 0
      : wrap(Math.atan2(dy, dx) / RAD - mem.hEst);

    return driveRel(rel, d, stopRadius, maxV);
  }

  function goBase(stopRadius) {
    if (hasBeacon) {
      return driveRel(num(beacon.bearing, 0),
        num(beacon.distance, baseDist), stopRadius, 0.78);
    }

    var dx = mem.baseX - mem.posX;
    var dy = mem.baseY - mem.posY;
    var d = Math.hypot(dx, dy);
    var rel = d < 0.01
      ? 0
      : wrap(Math.atan2(dy, dx) / RAD - mem.hEst);

    return driveRel(rel, d, stopRadius, 0.78);
  }

  function recoveryAction() {
    if (now >= mem.recoverUntil) return null;
    if (now - mem.recoverStart < 0.36) return motor(-0.24, 0);
    return motor(0, mem.recoverSide * 0.55);
  }

  function ensureGrid() {
    if (mem.gridPts) return;

    mem.gridPts = [];
    mem.gridDone = [];

    for (var y = 40; y <= mem.mapH - 25; y += 80) {
      for (var x = 40; x <= mem.mapW - 25; x += 80) {
        mem.gridPts.push({ x: x, y: y });
        mem.gridDone.push(false);
      }
    }

    if (mem.gridPts.length === 0) {
      mem.gridPts.push({ x: mem.mapW * 0.5, y: mem.mapH * 0.5 });
      mem.gridDone.push(false);
    }
  }

  function hintSearchLength(h) {
    return h && h.value > 1.4 ? 165 : 125;
  }

  function addSearchPoint(points, x, y) {
    x = clamp(x, 2, mem.mapW - 2);
    y = clamp(y, 2, mem.mapH - 2);

    for (var i = 0; i < points.length; i++) {
      if (dist(x, y, points[i].x, points[i].y) < 3) return;
    }
    points.push({ x: x, y: y });
  }

  function beginHintSearch(h) {
    mem.search = {
      kind: "hint",
      id: h.id,
      cx: h.x,
      cy: h.y,
      points: [{ x: h.x, y: h.y }],
      idx: 0,
      waitAt: -1,
      sum: 0,
      count: 0,
      centerVal: 0
    };
  }

  function beginFreeSearch(x, y, gridId) {
    mem.search = {
      kind: "free",
      id: -1,
      gridId: gridId === undefined ? -1 : gridId,
      cx: x,
      cy: y,
      points: [{ x: x, y: y }],
      idx: 0,
      waitAt: -1,
      sum: 0,
      count: 0,
      centerVal: 0
    };
    mem.task = { kind: "free", id: -1 };
  }

  function finishSearch(s) {
    if (s.kind === "hint") {
      var h = findHint(s.id);
      if (h && h.state !== 2) {
        if (h.assoc >= 0) {
          var linked = findSite(h.assoc);
          if (linked && linked.state !== 2) {
            h.state = 1;
            if (mem.task && mem.task.kind === "hint" &&
                mem.task.id === h.id) {
              mem.task = { kind: "site", id: linked.id };
              linked.state = 1;
            }
          } else {
            h.state = 3;
          }
        } else {
          h.state = 3;
        }
      }

      if (mem.task && mem.task.kind === "hint" &&
          mem.task.id === s.id &&
          (!h || h.state !== 1)) {
        mem.task = null;
      }
    } else {
      mem.freeDone.push({ x: s.cx, y: s.cy });
      if (mem.freeDone.length > 100) mem.freeDone.shift();

      if (s.gridId >= 0) {
        ensureGrid();
        if (mem.gridDone[s.gridId] !== undefined) {
          mem.gridDone[s.gridId] = true;
        }
      }

      if (mem.task && mem.task.kind === "free") mem.task = null;
    }

    if (mem.search === s) mem.search = null;
  }

  function searchStep() {
    var s = mem.search;
    if (!s) return motor(0, 0);

    if (s.idx >= s.points.length) {
      finishSearch(s);
      return motor(0, 0);
    }

    var p = s.points[s.idx];
    var d = dist(mem.posX, mem.posY, p.x, p.y);

    if (d > 1.9) {
      s.waitAt = -1;
      s.sum = 0;
      s.count = 0;
      return goPoint(p.x, p.y, 1.35, 0.72);
    }

    if (s.waitAt < 0) {
      s.waitAt = now;
      s.sum = 0;
      s.count = 0;
    }

    s.sum += science;
    s.count++;

    if (now - s.waitAt < 0.28) return motor(0, 0);

    var value = s.sum / Math.max(1, s.count);

    if (s.idx === 0) {
      s.centerVal = value;

      if (s.kind === "free" && value < 0.12) {
        finishSearch(s);
        return motor(0, 0);
      }

      var points = [{ x: s.cx, y: s.cy }];

      if (s.kind === "hint" &&
          (value > 0.16 || (findHint(s.id) &&
            findHint(s.id).value > 1.4))) {
        addSearchPoint(points, s.cx + 8.5, s.cy);
        addSearchPoint(points, s.cx, s.cy + 8.5);
        addSearchPoint(points, s.cx - 8.5, s.cy);
        addSearchPoint(points, s.cx, s.cy - 8.5);
      }

      var ringRadius = s.kind === "hint" ? 16 : 13;
      var startAngle = s.kind === "hint"
        ? Math.atan2(mem.baseY - s.cy, mem.baseX - s.cx)
        : 0;

      for (var ri2 = 0; ri2 < 8; ri2++) {
        var a = startAngle + ri2 * Math.PI / 4;
        addSearchPoint(points,
          s.cx + ringRadius * Math.cos(a),
          s.cy + ringRadius * Math.sin(a));
      }

      s.points = points;
      s.idx = 1;
      s.waitAt = -1;
      s.sum = 0;
      s.count = 0;
      return motor(0, 0);
    }

    s.idx++;
    s.waitAt = -1;
    s.sum = 0;
    s.count = 0;

    if (s.idx >= s.points.length) {
      finishSearch(s);
    }

    return motor(0, 0);
  }

  function freeNear(x, y) {
    for (var i = 0; i < mem.freeDone.length; i++) {
      if (dist(x, y, mem.freeDone[i].x, mem.freeDone[i].y) < 15) {
        return true;
      }
    }
    return false;
  }

  function searchInfo(s) {
    var px = mem.posX;
    var py = mem.posY;
    var total = 0;
    var endX = px;
    var endY = py;

    for (var i = s.idx; i < s.points.length; i++) {
      total += dist(px, py, s.points[i].x, s.points[i].y);
      px = s.points[i].x;
      py = s.points[i].y;
      endX = px;
      endY = py;
    }

    if (s.idx === 0 && s.points.length === 1) {
      if (s.kind === "hint") {
        var sh = findHint(s.id);
        total += hintSearchLength(sh);
      } else {
        total += 95;
      }
      endX = s.cx;
      endY = s.cy;
    }

    return { length: total, x: endX, y: endY };
  }

  function requiredEnergy(out, searchDist, back) {
    var load = 1 + 0.14 * carried;
    var rate = safeEpm();
    return rate * (1.18 * out + 1.16 * searchDist +
      1.38 * back + 18) * load + 0.075 + 0.018 * carried;
  }

  function candidateMetrics(kind, obj) {
    var out = 0;
    var searchDist = 0;
    var back = 0;
    var value = Math.max(0.02, obj.value);

    if (kind === "site") {
      out = dist(mem.posX, mem.posY, obj.x, obj.y);
      if (sensedSite && sensedSite.id === obj.id) {
        out = Math.min(out, num(siteObs.distance, out));
      }
      back = dist(obj.x, obj.y, mem.baseX, mem.baseY);
    } else if (kind === "hint") {
      if (mem.search && mem.search.kind === "hint" &&
          mem.search.id === obj.id) {
        var info = searchInfo(mem.search);
        searchDist = info.length;
        back = dist(info.x, info.y, mem.baseX, mem.baseY) + 8;
      } else {
        out = dist(mem.posX, mem.posY, obj.x, obj.y);
        searchDist = hintSearchLength(obj);
        back = dist(obj.x, obj.y, mem.baseX, mem.baseY) + 18;
      }
    } else if (kind === "grid") {
      out = dist(mem.posX, mem.posY, obj.x, obj.y);
      searchDist = 55;
      back = dist(obj.x, obj.y, mem.baseX, mem.baseY) + 10;
      value = 0.35;
    } else if (kind === "free") {
      if (mem.search) {
        var freeInfo = searchInfo(mem.search);
        searchDist = freeInfo.length;
        back = dist(freeInfo.x, freeInfo.y, mem.baseX, mem.baseY) + 8;
      } else {
        out = dist(mem.posX, mem.posY, obj.x, obj.y);
        searchDist = 70;
        back = dist(obj.x, obj.y, mem.baseX, mem.baseY) + 8;
      }
      value = 0.35;
    }

    var totalDistance = out + searchDist + back;
    var time = totalDistance / 0.76 + 28 + 5 * carried;
    if (kind === "hint") time += 8;

    return {
      out: out,
      search: searchDist,
      back: back,
      need: requiredEnergy(out, searchDist, back),
      time: time,
      total: totalDistance,
