    var bestScore = -1;
    var fallback = null;
    var fallbackScore = -1;
    var timeLeft = num(obs.timeLeft,
      Math.max(0, mem.missionSeconds - now));

    function consider(kind, obj) {
      if (!obj || (obj.state !== 0 && obj.state !== 1)) return;
      if (kind === "hint" && obj.assoc >= 0) return;

      var m = candidateMetrics(kind, obj);
      var score = Math.max(0.02, obj.value) /
        (28 + m.out + 0.68 * m.back + 0.56 * m.search);

      if (kind === "site") score *= 1.22;

      if (m.need <= battery - 0.04 &&
          m.time <= timeLeft - 6) {
        if (score > bestScore) {
