    var d = live ? clamp(num(siteObs.distance, 99), 0, 50) : globalD;
    var continuing = mem.sampleActive || drillProgress > 0.01;

    if (!continuing && d > 1.34) {
      mem.sampleStable = 0;
      mem.sampleAnchor = null;

      if (live) {
        return {
          action: driveRel(num(siteObs.bearing, 0), d, 1.1, 0.55),
          drill: false
        };
      }

      var speed = globalD > 10 ? 0.78 : 0.45;
      return {
        action: goPoint(site.x, site.y, 1.05, speed),
        drill: false
      };
    }

    if (!mem.sampleAnchor || mem.sampleAnchor.id !== site.id) {
      mem.sampleAnchor = {
        id: site.id,
        x: mem.posX,
        y: mem.posY,
        h: mem.hEst
      };
      mem.sampleStable = 0;
    }

    if (drillProgress > 0.01 && !mem.sampleActive) {
      mem.sampleActive = true;
      mem.sampleStart = now;
      mem.sampleSiteId = site.id;
    }

    var hrad = mem.hEst * RAD;
    var ex = mem.sampleAnchor.x - mem.posX;
    var ey = mem.sampleAnchor.y - mem.posY;
    var forwardError = ex * Math.cos(hrad) + ey * Math.sin(hrad);
    var pitch = num(obs.pitch, 0) * RAD;
    var holdV = clamp(
      1.0 * forwardError - 0.9 * wheelV + 0.42 * Math.sin(pitch),
      -0.12, 0.12
    );

    var yawNow = (wheelR - wheelL) / 0.6;
    var headingError = wrap(mem.sampleAnchor.h - mem.hEst) * RAD;
    var holdOmega = clamp(0.9 * headingError - 0.32 * yawNow, -0.16, 0.16);

    var stableSpeed = Math.max(
      Math.abs(wheelL),
      Math.abs(wheelR),
      Math.abs(wheelV),
      mem.gpsSpeed * 0.16
    );

