      (mem.sampleStable >= 0.45 && stableSpeed < 0.16 && d <= 1.43);

    if (drill && !mem.sampleActive) {
      mem.sampleActive = true;
      mem.sampleStart = now;
      mem.sampleSiteId = site.id;
    }

    if (drill) mem.sampleSiteId = site.id;

    return {
      action: motor(holdV, holdOmega),
      drill: drill
    };
  }

  function executeTask() {
