    if (mem.task.kind === "site") {
      var site = findSite(mem.task.id);
      if (!site) return { action: motor(0, 0), drill: false };
      var sample = sampleAction(site);
      return sample;
    }

    if (mem.task.kind === "hint") {
      var hint = findHint(mem.task.id);
      if (!hint) return { action: motor(0, 0), drill: false };

      if (!mem.search || mem.search.kind !== "hint" ||
          mem.search.id !== hint.id) {
        var hd = dist(mem.posX, mem.posY, hint.x, hint.y);
        if (hd > 3.2) {
          return {
            action: goPoint(hint.x, hint.y, 2.25, 0.82),
            drill: false
          };
        }
        beginHintSearch(hint);
      }

      return { action: searchStep(), drill: false };
    }

    if (mem.task.kind === "grid") {
      ensureGrid();
      var index = mem.task.id;
      var p = mem.gridPts[index];

      if (!p || mem.gridDone[index]) {
        mem.task = null;
        return { action: motor(0, 0), drill: false };
      }

      var gd = dist(mem.posX, mem.posY, p.x, p.y);
      if (gd > 2.5) {
        return {
          action: goPoint(p.x, p.y, 1.8, 0.78),
          drill: false
        };
      }

      if (science > 0.16 && !freeNear(mem.posX, mem.posY)) {
        beginFreeSearch(p.x, p.y, index);
        return { action: searchStep(), drill: false };
      }

      mem.gridDone[index] = true;
      mem.task = null;
      return { action: motor(0, 0), drill: false };
    }

    if (mem.task.kind === "free") {
      return { action: searchStep(), drill: false };
    }

    return { action: motor(0, 0), drill: false };
  }

  var speedNow = Math.max(
    Math.abs(wheelL),
    Math.abs(wheelR),
    Math.abs(wheelV),
    mem.gpsSpeed * 0.18
  );

  var atBase = docked ||
    (baseDist < 2.55 && speedNow < 0.22);

  if (atBase) {
    mem.batteryMax = Math.max(mem.batteryMax, battery);
  }

  if (sensedSite && carried < mem.capacity &&
      !mem.returning &&
      !mem.sampleActive &&
      drillProgress <= 0.01 &&
      sensedSite.state !== 2) {
    if (!mem.task ||
        mem.task.kind !== "site" ||
        mem.task.id !== sensedSite.id) {
      if (mem.task && !mem.resumeTask) {
        mem.resumeTask = { kind: mem.task.kind, id: mem.task.id };
      }
      mem.task = { kind: "site", id: sensedSite.id };
      sensedSite.state = 1;
    }
  }

  if (drillProgress > 0.01 && !mem.sampleActive &&
      mem.task && mem.task.kind === "site") {
    mem.sampleSiteId = mem.task.id;
    mem.sampleActive = true;
    if (mem.sampleStart < 0) mem.sampleStart = now;
  }

  if (mem.sampleActive || drillProgress > 0.01) {
    var activeSample = mem.sampleSiteId >= 0
      ? findSite(mem.sampleSiteId)
      : null;

    if (!activeSample && mem.task && mem.task.kind === "site") {
      activeSample = findSite(mem.task.id);
      if (activeSample) mem.sampleSiteId = activeSample.id;
    }
    if (!activeSample && sensedSite) {
      activeSample = sensedSite;
      mem.sampleSiteId = activeSample.id;
    }

    if (activeSample) {
      var sampleResult = sampleAction(activeSample);
      return finish(sampleResult.action, true);
    }
  }

  function returnNeed() {
    var load = 1 + 0.14 * carried;
    return safeEpm() * (baseDist + 12) * 1.35 * load +
      0.075 + 0.014 * carried;
  }

  function returnTime() {
    return baseDist / 0.72 + 22 + 5 * carried;
  }

  function releaseForRecharge() {
    if (mem.task && mem.task.kind === "hint" &&
        mem.search && mem.search.kind === "hint" &&
        mem.search.id === mem.task.id) {
      mem.search = null;
    }
    releaseTask(true);
    mem.resumeTask = null;
  }

  if (mem.returning) {
    if (atBase && carried <= 0.01) {
      mem.returning = false;
    } else if (atBase && carried > 0.01) {
      return finish(motor(0, 0), false);
    } else {
      if (mem.recoverUntil > now) {
        var ra0 = recoveryAction();
        if (ra0) return finish(ra0, false);
      }
      return finish(goBase(1.35), false);
    }
  }

  if (atBase && carried > 0.01) {
    mem.returning = true;
    return finish(motor(0, 0), false);
  }

  ensureTask();

  if (atBase) {
    if (mem.task) {
      var homeMetrics = taskMetrics();
      var timeLeftHome = num(obs.timeLeft,
        Math.max(0, mem.missionSeconds - now));

      if (homeMetrics &&
          (homeMetrics.need > battery - 0.035 ||
           homeMetrics.time > timeLeftHome - 5)) {
        if (battery < mem.batteryMax - 0.025) {
          return finish(motor(0, 0), false);
        }

        releaseForRecharge();
        ensureTask();
        homeMetrics = taskMetrics();
      }

      if (homeMetrics &&
          (homeMetrics.need > battery - 0.035 ||
           homeMetrics.time > timeLeftHome - 5)) {
        return finish(motor(0, 0), false);
      }
    }

    if (!mem.task) return finish(motor(0, 0), false);

    if (mem.recoverUntil > now) {
      var ra1 = recoveryAction();
      if (ra1) return finish(ra1, false);
    }

    var homeAction = executeTask();
    return finish(homeAction.action, homeAction.drill);
  }

  if (carried >= mem.capacity) {
    mem.returning = true;
    if (mem.recoverUntil > now) {
      var ra2 = recoveryAction();
      if (ra2) return finish(ra2, false);
    }
    return finish(goBase(1.35), false);
  }

  var timeLeft = num(obs.timeLeft,
    Math.max(0, mem.missionSeconds - now));
  var retNeed = returnNeed();
  var retTime = returnTime();

  if (battery <= retNeed + 0.035 ||
      (carried > 0 && timeLeft <= retTime + 8)) {
    mem.returning = true;
    if (mem.recoverUntil > now) {
      var ra3 = recoveryAction();
      if (ra3) return finish(ra3, false);
    }
    return finish(goBase(1.35), false);
  }

  if (mem.task) {
    var outboundMetrics = taskMetrics();

    if (outboundMetrics &&
        (outboundMetrics.need > battery - 0.025 ||
         outboundMetrics.time > timeLeft - 4)) {
      mem.returning = true;
      if (mem.recoverUntil > now) {
        var ra4 = recoveryAction();
        if (ra4) return finish(ra4, false);
      }
      return finish(goBase(1.35), false);
    }
  } else if (carried > 0.01) {
    mem.returning = true;
    return finish(goBase(1.35), false);
  } else if (baseDist > 3) {
    mem.returning = true;
    return finish(goBase(1.35), false);
  }

  if (mem.recoverUntil > now) {
    var ra5 = recoveryAction();
    if (ra5) return finish(ra5, false);
  }

  var action = executeTask();
  return finish(action.action, action.drill);
}

function act(obs, mem) {
