  function clamp(x, lo, hi) {
    return Math.max(lo, Math.min(hi, x));
  }

  function num(x, fallback) {
    if (x === null || x === undefined) return fallback;
    var v = Number(x);
    return isFinite(v) ? v : fallback;
  }

  function wrap(a) {
    a = (a + 180) % 360;
    if (a < 0) a += 360;
    return a - 180;
  }

  function dist(x1, y1, x2, y2) {
    return Math.hypot(x2 - x1, y2 - y1);
  }

  var rawX = num(obs.x, 0);
  var rawY = num(obs.y, 0);
  var rawH = wrap(num(obs.heading, 0));
  var wheelL = num(obs.wheelLeft, 0);
  var wheelR = num(obs.wheelRight, 0);
  var wheelV = 0.5 * (wheelL + wheelR);
  var battery = Math.max(0, num(obs.battery, 1));
  var solar = Math.max(0, num(obs.solar, 0));
  var carried = Math.max(0, num(obs.carried, 0));
  var drillProgress = Math.max(0, num(obs.drilling, 0));
  var science = Math.max(0, num(obs.science, 0));
  var docked = !!obs.docked;

  if (!mem._v5) {
    var mission = obs.mission || {};
    var size = mission.size;
    var mapW = 400;
    var mapH = 400;

    if (Array.isArray(size)) {
      mapW = num(size[0], 400);
      mapH = num(size[1], 400);
    } else if (size && typeof size === "object") {
      mapW = num(size.width, num(size.w, num(size.x, 400)));
      mapH = num(size.height, num(size.h, num(size.y, 400)));
    } else if (size !== undefined && size !== null && isFinite(Number(size))) {
      mapW = Number(size);
      mapH = Number(size);
    }

    mem.mapW = clamp(mapW, 40, 2000);
    mem.mapH = clamp(mapH, 40, 2000);

    var base = mission.base || { x: rawX, y: rawY };
    mem.baseX = num(base.x, rawX);
    mem.baseY = num(base.y, rawY);
