    mem.scan = null;
    mem.returning = false;

    mem.poseReady = false;
    mem.posX = rawX;
    mem.posY = rawY;
    mem.hEst = rawH;
    mem.headingBias = 0;
    mem.compassBadUntil = -1;
    mem.lastRawH = rawH;
    mem.lastGX = rawX;
    mem.lastGY = rawY;
    mem.gpsSame = 0;
    mem.gpsMoveSince = 0;
    mem.prevGpsFrozen = false;
    mem.gpsFrozen = false;
    mem.speedAvg = 0.72;
    mem.calOn = false;

    mem.gainL = 3.0;
    mem.gainR = 3.0;
    mem.iL = 0;
    mem.iR = 0;
    mem.prevTargetL = 0;
    mem.prevTargetR = 0;
    mem.lastCmdL = 0;
    mem.lastCmdR = 0;
    mem.lastDesiredV = 0;
    mem.lastDesiredOmega = 0;
    mem.lastDrillCmd = false;
    mem.failL = 0;
    mem.failR = 0;

    mem.epm = 0.0010;
    mem.epmHigh = 0.0012;
    mem.energyReady = false;
    mem.energyWindow = 0;
    mem.energyDistance = 0;
    mem.energyTime = 0;
    mem.batteryMax = Math.max(0.2, battery);

