    mem.raySame = [];
    mem.rayBad = [];
    mem.rayMoved = 0;
    mem.rays = [];

    mem.bumpPrev = false;
    mem.lastBump = -100;
    mem.recoverStart = -1;
    mem.recoverUntil = -1;
    mem.recoverSide = 1;
    mem.stuckStart = -1;
    mem.stuckX = rawX;
    mem.stuckY = rawY;

    mem.sampleTarget = false;
    mem.sampleHintId = -1;
    mem.sampleLocValid = false;
    mem.sampleX = rawX;
    mem.sampleY = rawY;
    mem.sampleAnchorSet = false;
    mem.sampleAnchorX = rawX;
    mem.sampleAnchorY = rawY;
    mem.sampleStable = 0;
    mem.drillCommanded = false;
    mem.drillStart = -1;

    mem.liveLocValid = false;
    mem.liveX = rawX;
    mem.liveY = rawY;
    mem.liveSeen = -1;
    mem.liveDistance = 99;
    mem.liveBearing = 0;

    mem.gridReady = false;
    mem.gridPts = [];
    mem.gridDone = [];
    mem.gridSerial = 0;
    mem.nextSignalId = 1;
    mem.freeDone = [];

    mem.lastCarried = carried;
    mem.lastDelivered = num(obs.delivered, 0);
    mem.lastT = undefined;
    mem.prevDocked = docked;
    mem.lastBattery = battery;
    mem.lastSolar = solar;
