  var dPos = 0;
  var rawGpsDist = 0;
  var gpsFrozen = false;
  var thawed = false;

  if (!mem.poseReady) {
    mem.posX = rawX;
    mem.posY = rawY;
    mem.hEst = rawH;
    mem.lastRawH = rawH;
    mem.lastGX = rawX;
    mem.lastGY = rawY;
    mem.gpsSame = 0;
    mem.gpsMoveSince = 0;
    mem.poseReady = true;
  } else {
    var oldX = mem.posX;
    var oldY = mem.posY;
    var oldH = mem.hEst;

    var predH = wrap(oldH + yawRate * dt / RAD);
    var rawDelta = wrap(rawH - mem.lastRawH);
    var predDelta = wrap(predH - oldH);
    var headingMismatch = Math.abs(wrap(rawDelta - predDelta));

    if (headingMismatch > 65 && Math.abs(yawRate) < 3.5 &&
