    } else {
      var compassTarget = wrap(rawH + mem.headingBias);
      var compassError = clamp(wrap(compassTarget - predH), -35, 35);
      var compassAlpha = Math.abs(wheelV) > 0.22 ? 0.15 : 0.22;
      mem.hEst = wrap(predH + compassAlpha * compassError);
