  mem.prevGpsFrozen = gpsFrozen;
  mem.gpsFrozen = gpsFrozen;
  mem.lastRawH = rawH;
  mem.lastGX = rawX;
  mem.lastGY = rawY;
  mem.lastT = now;

  function adaptGain(side, cmd, actual) {
