    var targetR = clamp(v + 0.3 * omega, -1.05, 1.05);
    var pitch = num(obs.pitch, 0) * RAD;
    var pitchU = docked ? 0 : clamp(0.16 * Math.sin(pitch), -0.10, 0.10);

