        }
      }

      if (docked && Math.abs(target) < 0.025) u = 0;
      u = clamp(u, -1, 1);

      if (side === 0) {
        mem.iL = integral;
        mem.prevTargetL = target;
      } else {
        mem.iR = integral;
        mem.prevTargetR = target;
      }
