    var candidates = [-80, -60, -40, -20, 0, 20, 40, 60, 80, direct];
    var bestA = direct;
    var bestClear = directClear;
    var bestCost = Infinity;

    for (var i = 0; i < candidates.length; i++) {
      var a = candidates[i];
      var clear = rayAt(a);
      var cost = Math.abs(wrap(a - goalRel));

      if (clear < 1.25) cost += 180 + (1.25 - clear) * 30;
      else if (clear < 2.2) cost += 65 + (2.2 - clear) * 22;
      else if (clear < 4.0) cost += (4.0 - clear) * 17;
      else if (clear < 6.0) cost += (6.0 - clear) * 2.0;

