    var speed = Math.min(maxV, Math.sqrt(0.34 * remain));

    if (Math.abs(steer) > 58) speed = Math.min(speed, 0.13);
    else if (Math.abs(steer) > 43) speed = Math.min(speed, 0.28);
    else if (Math.abs(steer) > 30) speed = Math.min(speed, 0.48);

    if (Math.abs(wrap(steer - rel)) > 35) speed *= 0.68;

    if (info.clear < 1.35) speed = Math.min(speed, 0.07);
    else if (info.clear < 2.2) speed = Math.min(speed, 0.16);
    else if (info.clear < 3.6) speed = Math.min(speed, 0.31);
    else if (info.clear < 5.2) speed = Math.min(speed, 0.52);

