    var sb0 = num(siteObs.bearing, 0);
    var absSite = (mem.hEst + sb0) * RAD;
    var sx0 = clamp(mem.posX + sd0 * Math.cos(absSite), 0, mem.mapW);
    var sy0 = clamp(mem.posY + sd0 * Math.sin(absSite), 0, mem.mapH);

    if (!mem.liveLocValid ||
