      centerX: h.x,
      centerY: h.y,
      points: points,
      idx: 0,
      waitAt: -1,
      sum: 0,
      count: 0,
      bestScience: 0,
      bestX: h.x,
      bestY: h.y,
      phase: "all"
    };
  }

  function startOuterSignalRing(s) {
    var points = [];
    var start = Math.atan2(mem.posY - s.centerY, mem.posX - s.centerX);
    for (var i = 0; i < 8; i++) {
      var a = start + i * Math.PI / 4;
      addUniquePoint(points,
        s.centerX + 18.5 * Math.cos(a),
        s.centerY + 18.5 * Math.sin(a));
    }
    s.phase = "outer";
    s.points = points;
    s.idx = 0;
    s.waitAt = -1;
    s.sum = 0;
    s.count = 0;
  }

  function startSignalScan(x, y, gridId) {
    var cx = clamp(x, 2, mem.mapW - 2);
    var cy = clamp(y, 2, mem.mapH - 2);
    var points = [];
    addUniquePoint(points, cx, cy);

    for (var i = 0; i < 8; i++) {
      var a = i * Math.PI / 4;
      addUniquePoint(points,
        cx + 10 * Math.cos(a),
        cy + 10 * Math.sin(a));
    }

    var id = mem.nextSignalId++;
    mem.task = { kind: "signal", id: id };
    mem.scan = {
      kind: "signal",
      id: id,
      gridId: gridId === undefined ? -1 : gridId,
      centerX: cx,
      centerY: cy,
      points: points,
      idx: 0,
      waitAt: -1,
      sum: 0,
      count: 0,
      bestScience: -1,
      bestX: cx,
      bestY: cy,
      centerScience: 0,
      phase: "initial",
      hillDirX: 0,
      hillDirY: 0,
      hillBest: 0,
      hillSteps: 0
    };
  }

  function finishScan(s) {
    if (s.kind === "hint") {
      var h = findHint(s.id);
      if (h && h.state !== 2) h.state = 3;
      if (mem.task && mem.task.kind === "hint" &&
          mem.task.id === s.id) {
        mem.task = null;
      }
    } else if (s.kind === "signal") {
      mem.freeDone.push({ x: s.centerX, y: s.centerY });
      if (mem.freeDone.length > 100) mem.freeDone.shift();

      if (s.gridId >= 0) {
        ensureGrid();
        if (mem.gridDone[s.gridId] !== undefined) {
          mem.gridDone[s.gridId] = true;
        }
      }

      if (mem.task && mem.task.kind === "signal" &&
          mem.task.id === s.id) {
        mem.task = null;
      }
    }

    if (mem.scan === s) mem.scan = null;
  }

  function completeGrid(index) {
    ensureGrid();
    if (index >= 0 && mem.gridDone[index] !== undefined) {
      mem.gridDone[index] = true;
    }
    if (mem.task && mem.task.kind === "grid" &&
        mem.task.id === index) {
      mem.task = null;
    }
  }

  function scanStep() {
    var s = mem.scan;
    if (!s) return zeroAction();

    if (s.idx >= s.points.length) {
      if (s.kind === "signal" && s.phase === "initial") {
        var improve = s.bestScience >
          s.centerScience + Math.max(0.025, s.centerScience * 0.07);
        var bx = s.bestX - s.centerX;
        var by = s.bestY - s.centerY;
        var bn = Math.hypot(bx, by);

        if (improve && bn > 3) {
          s.phase = "hill";
          s.hillDirX = bx / bn;
          s.hillDirY = by / bn;
          s.hillBest = s.bestScience;
          s.hillSteps = 0;
          s.points = [makePoint(
            s.bestX + 8 * s.hillDirX,
            s.bestY + 8 * s.hillDirY
          )];
          s.idx = 0;
          s.waitAt = -1;
          return zeroAction();
        }

        startOuterSignalRing(s);
        return zeroAction();
      }

      if (s.kind === "signal" && s.phase === "hill") {
        startOuterSignalRing(s);
        return zeroAction();
      }

      finishScan(s);
      return zeroAction();
    }

    var p = s.points[s.idx];
    var d = dist(mem.posX, mem.posY, p.x, p.y);

    if (d > 1.8) {
      s.waitAt = -1;
      s.sum = 0;
      s.count = 0;
      return drivePoint(p.x, p.y, 1.25, 0.70);
    }

    if (s.waitAt < 0) {
      s.waitAt = now;
      s.sum = 0;
      s.count = 0;
    }

    s.sum += science;
    s.count++;

    if (now - s.waitAt < 0.40) return zeroAction();

    var value = s.sum / Math.max(1, s.count);
    var px = p.x;
    var py = p.y;
    var oldIdx = s.idx;

    if (value > s.bestScience) {
      s.bestScience = value;
      s.bestX = px;
      s.bestY = py;
    }
    if (s.kind === "signal" && s.phase === "initial" && oldIdx === 0) {
      s.centerScience = value;
    }

    s.idx++;
    s.waitAt = -1;
    s.sum = 0;
    s.count = 0;

    if (s.kind === "signal" && s.phase === "hill") {
      var threshold = Math.max(0.012, s.hillBest * 0.025);
      if (value > s.hillBest + threshold && s.hillSteps < 4) {
        s.hillBest = value;
        s.hillSteps++;
        s.points = [makePoint(
          px + 8 * s.hillDirX,
          py + 8 * s.hillDirY
        )];
        s.idx = 0;
      } else {
        startOuterSignalRing(s);
      }
    } else if (s.idx >= s.points.length &&
        s.kind === "signal" && s.phase === "initial") {
      var gradient = s.bestScience >
        s.centerScience + Math.max(0.025, s.centerScience * 0.07);
      var gx = s.bestX - s.centerX;
      var gy = s.bestY - s.centerY;
      var gn = Math.hypot(gx, gy);

      if (gradient && gn > 3) {
        s.phase = "hill";
        s.hillDirX = gx / gn;
        s.hillDirY = gy / gn;
        s.hillBest = s.bestScience;
        s.hillSteps = 0;
        s.points = [makePoint(
          s.bestX + 8 * s.hillDirX,
          s.bestY + 8 * s.hillDirY
        )];
        s.idx = 0;
      } else {
        startOuterSignalRing(s);
      }
    } else if (s.idx >= s.points.length) {
      finishScan(s);
    }

    return zeroAction();
  }

  function scanRoute(s) {
    if (!s || !s.points || s.points.length === 0) {
      return { length: 0, x: mem.posX, y: mem.posY };
    }

    var px = mem.posX;
    var py = mem.posY;
    var length = 0;
    var endX = px;
    var endY = py;

    for (var i = s.idx; i < s.points.length; i++) {
      length += dist(px, py, s.points[i].x, s.points[i].y);
      px = s.points[i].x;
      py = s.points[i].y;
      endX = px;
      endY = py;
    }

    if (s.kind === "signal" && s.phase === "initial") length += 45;
    else if (s.kind === "signal" && s.phase === "hill") length += 25;

    return { length: length, x: endX, y: endY };
  }

  function planForHint(h) {
    var out = 0;
    var scanLen = 130;
    var endX = h.x;
    var endY = h.y;

    if (mem.scan && mem.scan.kind === "hint" &&
        mem.scan.id === h.id) {
      var sr = scanRoute(mem.scan);
      scanLen = sr.length;
      out = 0;
      endX = sr.x;
      endY = sr.y;
    } else {
      out = dist(mem.posX, mem.posY, h.x, h.y);
    }

    var back = dist(endX, endY, mem.baseX, mem.baseY);
    var load = 1 + 0.12 * carried;
    var need = safeEpm() *
      (out + scanLen + 1.25 * back + 10) * load +
      0.12 + 0.015 * carried;
    var total = out + scanLen + back;
    var time = total * 1.30 / Math.max(0.45, mem.speedAvg) +
      30 + 6 * carried;

    return {
      out: out,
      scan: scanLen,
      back: back,
      need: need,
      time: time,
      total: total
    };
  }

  function taskPlan() {
    if (!mem.task) return null;

    if (mem.task.kind === "hint") {
      var h = findHint(mem.task.id);
      if (!h) return null;
      return planForHint(h);
    }

    if (mem.task.kind === "signal" && mem.scan &&
        mem.scan.kind === "signal") {
      var sr = scanRoute(mem.scan);
      var backSignal = dist(sr.x, sr.y, mem.baseX, mem.baseY);
      var needSignal = safeEpm() *
        (sr.length + 1.25 * backSignal + 10) *
        (1 + 0.12 * carried) + 0.12 + 0.015 * carried;
      return {
        out: 0,
        scan: sr.length,
        back: backSignal,
        need: needSignal,
        time: (sr.length + backSignal) * 1.30 /
          Math.max(0.45, mem.speedAvg) + 30 + 6 * carried
      };
    }

    if (mem.task.kind === "grid") {
      ensureGrid();
      var gp = mem.gridPts[mem.task.id];
      if (!gp) return null;
      var out = dist(mem.posX, mem.posY, gp.x, gp.y);
      var search = 35;
      var ex = gp.x;
      var ey = gp.y;

      if (mem.scan && mem.scan.kind === "signal" &&
          mem.scan.gridId === mem.task.id) {
        var gr = scanRoute(mem.scan);
        out = 0;
        search = gr.length;
        ex = gr.x;
        ey = gr.y;
      }

      var back = dist(ex, ey, mem.baseX, mem.baseY);
      var need = safeEpm() *
        (out + search + 1.25 * back + 10) *
        (1 + 0.12 * carried) + 0.12 + 0.015 * carried;
      return {
        out: out,
        scan: search,
        back: back,
        need: need,
        time: (out + search + back) * 1.30 /
          Math.max(0.45, mem.speedAvg) + 30 + 6 * carried
      };
    }

    return null;
  }

  function selectTask(timeLeft) {
    if (mem.task) return;

    if (science > 0.34 && !freeNear(mem.posX, mem.posY)) {
      startSignalScan(mem.posX, mem.posY, -1);
      return;
    }

    var best = null;
    var bestScore = -1;

    for (var i = 0; i < mem.hints.length; i++) {
      var h = mem.hints[i];
      if (h.state !== 0) continue;

      var m = planForHint(h);
      if (m.need > battery - 0.025) continue;
      if (m.time > timeLeft - 3) continue;

      var score = Math.max(0.02, h.value) /
        (28 + m.out + 0.72 * m.back + 0.55 * m.scan);

      if (score > bestScore) {
        bestScore = score;
        best = h;
      }
    }

    if (best) {
      mem.task = { kind: "hint", id: best.id };
      best.state = 1;
      return;
    }

    ensureGrid();
    var gridBest = -1;
    var gridScore = Infinity;

    for (var gi = 0; gi < mem.gridPts.length; gi++) {
      if (mem.gridDone[gi]) continue;

      var point = mem.gridPts[gi];
      var go = dist(mem.posX, mem.posY, point.x, point.y);
      var gb = dist(point.x, point.y, mem.baseX, mem.baseY);
      var gridNeed = safeEpm() *
        (go + 35 + 1.25 * gb + 10) *
        (1 + 0.12 * carried) + 0.12 + 0.015 * carried;
      var gridTime = (go + 35 + gb) * 1.30 /
        Math.max(0.45, mem.speedAvg) + 30 + 6 * carried;

      if (gridNeed > battery - 0.025 || gridTime > timeLeft - 3) continue;

      var scoreGrid = go + 0.34 * gb;
      if (scoreGrid < gridScore) {
        gridScore = scoreGrid;
        gridBest = gi;
      }
    }

    if (gridBest >= 0) {
      mem.task = {
        kind: "grid",
        id: gridBest,
        waitAt: -1,
        sum: 0,
        count: 0
      };
    }
  }

  function clearTask() {
    if (mem.task && mem.task.kind === "hint") {
      var h = findHint(mem.task.id);
      if (h && h.state === 1) h.state = 0;
    }
    mem.task = null;
    mem.scan = null;
  }

  function executeTask() {
    if (!mem.task) return zeroAction();

    if (mem.task.kind === "hint") {
      var h = findHint(mem.task.id);
      if (!h || h.state === 2 || h.state === 3) {
        mem.task = null;
        mem.scan = null;
        return zeroAction();
      }

      if (!mem.scan || mem.scan.kind !== "hint" ||
          mem.scan.id !== h.id) {
        startHintScan(h);
      }
      return scanStep();
    }

    if (mem.task.kind === "signal") {
      if (!mem.scan || mem.scan.kind !== "signal") {
        mem.task = null;
        return zeroAction();
      }
      return scanStep();
    }

    if (mem.task.kind === "grid") {
      ensureGrid();
      var id = mem.task.id;
      var p = mem.gridPts[id];

      if (!p || mem.gridDone[id]) {
        mem.task = null;
        return zeroAction();
      }

      var d = dist(mem.posX, mem.posY, p.x, p.y);
      if (d > 1.8) {
        mem.task.waitAt = -1;
        mem.task.sum = 0;
        mem.task.count = 0;
        return drivePoint(p.x, p.y, 1.25, 0.72);
      }

      if (mem.task.waitAt < 0) {
        mem.task.waitAt = now;
        mem.task.sum = 0;
        mem.task.count = 0;
      }

      mem.task.sum += science;
      mem.task.count++;

      if (now - mem.task.waitAt < 0.40) return zeroAction();

      var value = mem.task.sum / Math.max(1, mem.task.count);
      if (value > 0.24 && !freeNear(p.x, p.y)) {
        startSignalScan(p.x, p.y, id);
        return zeroAction();
      }

      completeGrid(id);
      return zeroAction();
    }

    return zeroAction();
  }

  function startSampleTarget() {
    mem.sampleTarget = true;
    mem.sampleHintId = associateLiveSite();
    mem.sampleLocValid = mem.liveLocValid;
    if (mem.liveLocValid) {
      mem.sampleX = mem.liveX;
      mem.sampleY = mem.liveY;
    } else {
      mem.sampleX = mem.posX;
      mem.sampleY = mem.posY;
    }
    mem.sampleAnchorSet = false;
    mem.sampleStable = 0;
    mem.drillCommanded = false;
    mem.drillStart = -1;
  }

  function sampleAction() {
    var d;
    var live = sensedSite;

    if (live) {
      d = clamp(num(siteObs.distance, 99), 0, 50);
      if (mem.liveLocValid) {
        mem.sampleX = 0.72 * mem.sampleX + 0.28 * mem.liveX;
        mem.sampleY = 0.72 * mem.sampleY + 0.28 * mem.liveY;
        mem.sampleLocValid = true;
      }
    } else if (mem.sampleLocValid) {
      d = dist(mem.posX, mem.posY, mem.sampleX, mem.sampleY);
    } else {
      d = 99;
    }

    if (d > 1.38 && drillProgress <= 0.01) {
      mem.sampleAnchorSet = false;
      mem.sampleStable = 0;

      if (live) {
        return {
          action: driveBearing(num(siteObs.bearing, 0), d, 0.92, 0.52),
          drill: false
        };
      }

      if (mem.sampleLocValid) {
        return {
          action: drivePoint(mem.sampleX, mem.sampleY, 0.92, 0.48),
          drill: false
        };
      }

      mem.sampleTarget = false;
      return { action: zeroAction(), drill: false };
    }

    if (!mem.sampleAnchorSet) {
      mem.sampleAnchorX = mem.posX;
      mem.sampleAnchorY = mem.posY;
      mem.sampleAnchorSet = true;
      mem.sampleStable = 0;
    }

    var hrad = mem.hEst * RAD;
    var errX = mem.sampleAnchorX - mem.posX;
    var errY = mem.sampleAnchorY - mem.posY;
    var forwardError = errX * Math.cos(hrad) + errY * Math.sin(hrad);
    var holdV = clamp(0.46 * forwardError - 0.86 * wheelV,
      -0.12, 0.12);
    var holdOmega = clamp(-0.42 * yawRate, -0.12, 0.12);

    var stableSpeed = Math.max(
      Math.abs(wheelL),
      Math.abs(wheelR),
      Math.abs(wheelR - wheelL) * 0.08
    );

    var inRange = d <= 1.43;
    if (stableSpeed < 0.125 && inRange) {
      mem.sampleStable += dt;
    } else if (drillProgress <= 0.01) {
      mem.sampleStable = 0;
    }

    var drill = inRange && stableSpeed < 0.145 &&
      (drillProgress > 0.01 || mem.sampleStable >= 0.38);

    if (drill) {
      if (!mem.drillCommanded) mem.drillStart = now;
      mem.drillCommanded = true;
    } else if (drillProgress <= 0.01 ||
        !inRange || stableSpeed >= 0.145) {
      mem.drillCommanded = false;
      if (!inRange || stableSpeed >= 0.145) {
        mem.sampleStable = 0;
        mem.drillStart = -1;
      }
    }

    return {
      action: motor(holdV, holdOmega),
      drill: drill
    };
  }

  function finishSample() {
    var hintId = mem.sampleHintId;

    if (hintId < 0 && mem.sampleLocValid) {
      var near = nearestHint(mem.sampleX, mem.sampleY, 30);
      if (near) hintId = near.id;
    }

    if (hintId < 0 && mem.task && mem.task.kind === "hint" &&
        mem.scan && mem.scan.kind === "hint") {
      hintId = mem.task.id;
    }

    if (hintId >= 0) {
      var h = findHint(hintId);
      if (h) h.state = 2;
    }

    if (mem.task && mem.task.kind === "hint" &&
        mem.task.id === hintId) {
      mem.task = null;
      mem.scan = null;
    }

    if (mem.task && mem.task.kind === "grid") {
      completeGrid(mem.task.id);
    }

    if (mem.task && mem.task.kind === "signal" && mem.scan &&
        mem.scan.kind === "signal") {
      if (mem.scan.gridId >= 0) completeGrid(mem.scan.gridId);
      mem.task = null;
      mem.scan = null;
    }

    mem.sampleTarget = false;
    mem.sampleHintId = -1;
    mem.sampleLocValid = false;
    mem.sampleAnchorSet = false;
    mem.sampleStable = 0;
    mem.drillCommanded = false;
    mem.drillStart = -1;
  }

  var oldCarried = mem.lastCarried;
  if (carried > oldCarried + 0.01) {
    finishSample();
  } else if (carried < oldCarried - 0.01) {
    mem.sampleTarget = false;
    mem.sampleHintId = -1;
    mem.sampleLocValid = false;
    mem.sampleAnchorSet = false;
    mem.sampleStable = 0;
    mem.drillCommanded = false;
    mem.drillStart = -1;
  }
  mem.lastCarried = carried;

  var delivered = num(obs.delivered, mem.lastDelivered);
  var deliveredChanged = delivered > mem.lastDelivered + 0.001;
  mem.lastDelivered = delivered;
  if (deliveredChanged) mem.returning = false;

  var beacon = obs.beacon || null;
  var hasBeacon = !!beacon &&
    num(beacon.distance, 99) <= 20.5;
  var gpsBaseDist = dist(mem.posX, mem.posY, mem.baseX, mem.baseY);
  var baseDist = hasBeacon
    ? clamp(num(beacon.distance, gpsBaseDist), 0, 25)
    : gpsBaseDist;

  function goBase(stopRadius) {
    if (hasBeacon) {
      return driveBearing(num(beacon.bearing, 0),
        num(beacon.distance, baseDist), stopRadius, 0.78);
    }

    var dx = mem.baseX - mem.posX;
    var dy = mem.baseY - mem.posY;
    var d = Math.hypot(dx, dy);
    var rel = d < 0.01 ? 0 :
      wrap(Math.atan2(dy, dx) / RAD - mem.hEst);
    return driveBearing(rel, d, stopRadius, 0.78);
  }

  var speedNow = Math.max(Math.abs(wheelL), Math.abs(wheelR));
  var atHome = docked ||
    (baseDist < 2.45 && speedNow < 0.20);

  if (docked) mem.batteryMax = Math.max(mem.batteryMax, battery);

  if (atHome && carried > 0.01) {
    mem.returning = true;
    if (!docked && baseDist > 0.70) {
      return finish(goBase(0.48), false);
    }
    return finish(zeroAction(), false);
  }

  if (atHome && carried <= 0.01) {
    mem.returning = false;
  }

  var timeLeft = num(obs.timeLeft,
    Math.max(0, mem.missionSeconds - now));

  var returnNeed = safeEpm() *
    (1.50 * (baseDist + 5)) *
    (1 + 0.12 * carried) +
    0.12 + 0.015 * carried;

  var returnTime = baseDist * 1.55 /
    Math.max(0.42, mem.speedAvg) +
    25 + 5 * carried;

  var mustReturn = !atHome && (
    carried >= mem.capacity ||
    battery <= returnNeed + 0.035 ||
    (carried > 0 && timeLeft <= returnTime + 8)
  );

  if (drillProgress > 0.01 && !mem.sampleTarget) {
    startSampleTarget();
  }

  if (drillProgress > 0.01 && mem.sampleTarget) {
    var remainingDrill = Math.max(0, 6 - drillProgress);
    var afterSampleNeed = safeEpm() *
      (1.50 * (baseDist + 5)) *
      (1 + 0.12 * (carried + 1)) +
      0.12 + 0.015 * (carried + 1);

    var canFinishDrill = battery > afterSampleNeed + 0.02 &&
      timeLeft > returnTime + remainingDrill + 5;

    if (canFinishDrill) {
      var ongoing = sampleAction();
      return finish(ongoing.action, ongoing.drill);
    }

    mem.sampleTarget = false;
    mem.sampleAnchorSet = false;
    mem.drillCommanded = false;
    mem.returning = true;
    if (!atHome) return finish(goBase(0.50), false);
  }

  if (mem.returning && !atHome) {
    mem.sampleTarget = false;
    mem.sampleAnchorSet = false;
    return finish(goBase(0.50), false);
  }

  if (mustReturn) {
    mem.returning = true;
    mem.sampleTarget = false;
    mem.sampleAnchorSet = false;
    return finish(goBase(0.50), false);
  }

  if (!mem.returning && !mem.sampleTarget && sensedSite &&
      carried < mem.capacity) {
    var afterSiteNeed = safeEpm() *
      (1.50 * (baseDist + 5)) *
      (1 + 0.12 * (carried + 1)) +
      0.12 + 0.015 * (carried + 1);

    if (battery > afterSiteNeed + 0.025 &&
        timeLeft > returnTime + 10) {
      startSampleTarget();
    }
  }

  if (mem.sampleTarget && !mem.returning) {
    var siteNeedNow = safeEpm() *
      (1.50 * (baseDist + 5)) *
      (1 + 0.12 * (carried + 1)) +
      0.12 + 0.015 * (carried + 1);

    if (battery <= siteNeedNow + 0.015 ||
        timeLeft <= returnTime + 8) {
      mem.sampleTarget = false;
      mem.sampleAnchorSet = false;
      mem.drillCommanded = false;
      if (!atHome) {
        mem.returning = true;
        return finish(goBase(0.50), false);
      }
    } else {
      var sampleResult = sampleAction();
      return finish(sampleResult.action, sampleResult.drill);
    }
  }

  if (mem.returning && !atHome) {
    return finish(goBase(0.50), false);
  }

  if (!mem.task) {
    selectTask(timeLeft);
  }

  var currentPlan = taskPlan();

  if (currentPlan &&
      (currentPlan.need > battery - 0.015 ||
       currentPlan.time > timeLeft - 2)) {
    if (atHome && docked &&
        battery < mem.batteryMax - 0.008 &&
        timeLeft > 30) {
      return finish(zeroAction(), false);
    }

    if (atHome) {
      clearTask();
      selectTask(timeLeft);
      currentPlan = taskPlan();

      if (currentPlan &&
          (currentPlan.need > battery - 0.015 ||
           currentPlan.time > timeLeft - 2)) {
