    var directClear = rayAt(direct);

    if (directClear >= 4.0) {
      return { angle: direct, clear: directClear };
    }

    if (now > mem.avoidUntil || !mem.avoidSide) {
      mem.avoidSide = sideClear(1) >= sideClear(-1) ? 1 : -1;
      mem.avoidUntil = now + 1.8;
    }

    var candidates = [-80, -60, -40, -20, 0, 20, 40, 60, 80];
    var bestAngle = direct;
    var bestClear = directClear;
    var bestCost = Infinity;

    for (var i = 0; i < candidates.length; i++) {
      var a = candidates[i];
      var clear = rayAt(a);
      var cost = Math.abs(wrap(a - goalRel));

      if (clear < 1.0) cost += 270 + (1.0 - clear) * 75;
      else if (clear < 1.8) cost += 130 + (1.8 - clear) * 50;
      else if (clear < 3.2) cost += 35 + (3.2 - clear) * 22;
      else if (clear < 4.5) cost += (4.5 - clear) * 7;

      if (Math.abs(a) > 12 && Math.sign(a) !== mem.avoidSide) {
        cost += 5;
      }

      if (cost < bestCost) {
        bestCost = cost;
        bestAngle = a;
        bestClear = clear;
      }
    }

    return { angle: bestAngle, clear: bestClear };
  }

  function driveBearing(rel, distance, stopRadius, maxV) {
    rel = wrap(rel);
    distance = Math.max(0, num(distance, 0));
    stopRadius = Math.max(0, stopRadius);

    if (distance <= stopRadius + 0.08) return zeroAction();

    var remain = Math.max(0, distance - stopRadius);

    if (Math.abs(rel) > 100) {
      var spin = clamp(1.65 * rel * RAD - 0.62 * yawRate, -0.78, 0.78);
      return motor(0, spin);
    }

    var info = chooseDirection(rel);
    var steer = info.angle;
    var front = rayAt(0);
    var speed = Math.min(maxV, Math.sqrt(0.32 * remain));

    if (Math.abs(steer) > 53) speed = 0;
    else if (Math.abs(steer) > 38) speed = Math.min(speed, 0.13);
    else if (Math.abs(steer) > 26) speed = Math.min(speed, 0.25);

    if (Math.abs(wrap(steer - rel)) > 32) {
      speed = Math.min(speed, 0.17);
    }

    if (info.clear < 1.15) speed = 0;
    else if (info.clear < 1.8) speed = Math.min(speed, 0.07);
    else if (info.clear < 2.6) speed = Math.min(speed, 0.15);
    else if (info.clear < 3.6) speed = Math.min(speed, 0.27);
    else if (info.clear < 4.8) speed = Math.min(speed, 0.39);

    if (front < 1.35) speed = 0;
    else if (front < 1.9) speed = Math.min(speed, 0.07);
    else if (front < 2.7) speed = Math.min(speed, 0.15);
    else if (front < 3.5) speed = Math.min(speed, 0.26);
    else if (front < 4.6) speed = Math.min(speed, 0.38);

    var omega = clamp(1.55 * steer * RAD - 0.62 * yawRate, -0.78, 0.78);
    if (Math.abs(steer) < 1.0 && Math.abs(yawRate) < 0.08) omega = 0;

    return motor(speed, omega);
  }

  function drivePoint(x, y, stopRadius, maxV) {
    x = clamp(x, 2, mem.mapW - 2);
    y = clamp(y, 2, mem.mapH - 2);

    var dx = x - mem.posX;
    var dy = y - mem.posY;
    var d = Math.hypot(dx, dy);
    var rel = d < 0.01 ? 0 :
      wrap(Math.atan2(dy, dx) / RAD - mem.hEst);

    return driveBearing(rel, d, stopRadius, maxV);
  }

  function navigatePoint(x, y, stopRadius, maxV, key) {
    var d = dist(mem.posX, mem.posY, x, y);

    if (mem.navKey !== key) {
      mem.navKey = key;
      mem.navBestD = d;
      mem.navProgressAt = now;
    } else if (d < mem.navBestD - 0.35) {
      mem.navBestD = d;
      mem.navProgressAt = now;
    }

    if (d > stopRadius + 0.8 &&
        now - mem.navProgressAt > 22) {
      return { failed: true, action: zeroAction(), distance: d };
    }

    return {
      failed: false,
      action: drivePoint(x, y, stopRadius, maxV),
      distance: d
    };
  }

  function startRecovery(side) {
    mem.recoverStart = now;
    mem.recoverUntil = now + 1.05;
    mem.recoverSide = side || 1;
    mem.lastBump = now;
    mem.stuckStart = -1;
    mem.navKey = "";

    if (mem.task && mem.task.kind === "hint") {
      mem.task.bumpCount = (mem.task.bumpCount || 0) + 1;
    }
  }

  if (!mem.sampleTarget && drillProgress <= 0.01 &&
      obs.bumped && !mem.bumpPrev && now - mem.lastBump > 1.2) {
    startRecovery(sideClear(1) >= sideClear(-1) ? 1 : -1);
  }
  mem.bumpPrev = !!obs.bumped;

  if (!mem.sampleTarget &&
      Math.abs(mem.lastDesiredV || 0) > 0.25 &&
      !gpsFrozen) {
    if (mem.stuckStart < 0) {
      mem.stuckStart = now;
      mem.stuckX = mem.posX;
      mem.stuckY = mem.posY;
    } else if (now - mem.stuckStart > 6.5) {
      var moved = dist(mem.posX, mem.posY, mem.stuckX, mem.stuckY);
      if (moved < 0.65 && now - mem.lastBump > 2) {
        startRecovery(sideClear(1) >= sideClear(-1) ? 1 : -1);
      } else {
        mem.stuckStart = now;
        mem.stuckX = mem.posX;
        mem.stuckY = mem.posY;
      }
    }
  } else {
    mem.stuckStart = -1;
  }

  function recoveryAction() {
    if (now >= mem.recoverUntil) return null;

    if (now - mem.recoverStart < 0.32) {
      return motor(-0.20, 0);
    }

    return motor(0, mem.recoverSide * 0.55);
  }

  function makePoint(x, y) {
    return {
      x: clamp(x, 2, mem.mapW - 2),
      y: clamp(y, 2, mem.mapH - 2)
    };
  }

  function addUniquePoint(points, x, y) {
    var p = makePoint(x, y);
    for (var i = 0; i < points.length; i++) {
      if (dist(p.x, p.y, points[i].x, points[i].y) < 2.5) return;
    }
    points.push(p);
  }

  function ringPoints(cx, cy, radius, startAngle, count) {
    var points = [];
    for (var i = 0; i < count; i++) {
      var a = startAngle + i * 2 * Math.PI / count;
      addUniquePoint(points,
        cx + radius * Math.cos(a),
        cy + radius * Math.sin(a));
    }
    return points;
  }

  function localPoints(cx, cy, radius) {
    var points = [];
    addUniquePoint(points, cx + radius, cy);
    addUniquePoint(points, cx, cy + radius);
    addUniquePoint(points, cx - radius, cy);
    addUniquePoint(points, cx, cy - radius);
    return points;
  }

  function startHintScan(h) {
    mem.scan = {
      kind: "hint",
      id: h.id,
      cx: h.x,
      cy: h.y,
      points: [{ x: h.x, y: h.y }],
      idx: 0,
      waitAt: -1,
      sum: 0,
      count: 0,
      bestScience: -1,
      bestX: h.x,
      bestY: h.y,
      centerScience: 0,
      phase: "center"
    };
  }

  function startSignalScan(x, y, gridId) {
    var cx = clamp(x, 2, mem.mapW - 2);
    var cy = clamp(y, 2, mem.mapH - 2);
    var points = [{ x: cx, y: cy }];
    var startAngle = Math.atan2(mem.posY - cy, mem.posX - cx);

    var ring = ringPoints(cx, cy, 10, startAngle, 8);
    for (var i = 0; i < ring.length; i++) {
      addUniquePoint(points, ring[i].x, ring[i].y);
    }

    mem.scan = {
      kind: "signal",
      gridId: gridId === undefined ? -1 : gridId,
      cx: cx,
      cy: cy,
      points: points,
      idx: 0,
      waitAt: -1,
      sum: 0,
      count: 0,
      bestScience: -1,
      bestX: cx,
      bestY: cy,
      centerScience: 0,
      phase: "survey",
      hillDirX: 0,
      hillDirY: 0,
      hillBest: 0,
      hillSteps: 0
    };
  }

  function beginLocalScan(s, radius) {
    s.phase = "local";
    s.points = localPoints(s.bestX, s.bestY, radius);
    s.idx = 0;
    s.waitAt = -1;
    s.sum = 0;
    s.count = 0;
  }

  function finishScan(s) {
    if (s.kind === "hint") {
      var h = findHint(s.id);
      if (h && h.state !== 2) h.state = 3;

      if (mem.task && mem.task.kind === "hint" &&
          mem.task.id === s.id) {
        mem.task = null;
      }
    } else {
      if (s.gridId >= 0) {
        ensureGrid();
        if (mem.gridDone[s.gridId] !== undefined) {
          mem.gridDone[s.gridId] = true;
        }
      }

      mem.freeDone.push({ x: s.cx, y: s.cy });
      if (mem.freeDone.length > 100) mem.freeDone.shift();

      if (mem.task && mem.task.kind === "grid" &&
          mem.task.id === s.gridId) {
        mem.task = null;
      }
    }

    if (mem.scan === s) mem.scan = null;
    mem.navKey = "";
  }

  function advanceScan(s) {
    if (s.kind === "hint") {
      if (s.phase === "center") {
        var h = findHint(s.id);
        var worthSearching = !!h && h.value > 1.15;

        if (s.centerScience > 0.025 || worthSearching) {
          var startAngle = Math.atan2(mem.baseY - s.cy, mem.baseX - s.cx);
          s.phase = "main";
          s.points = ringPoints(s.cx, s.cy, 18.5, startAngle, 8);
          s.idx = 0;
          s.waitAt = -1;
          s.sum = 0;
          s.count = 0;
        } else {
          finishScan(s);
        }
        return;
      }

      if (s.phase === "main" && s.bestScience > 0.16) {
        beginLocalScan(s, 5);
        return;
      }

      finishScan(s);
      return;
    }

    if (s.phase === "survey") {
      var gx = s.bestX - s.cx;
      var gy = s.bestY - s.cy;
      var gn = Math.hypot(gx, gy);
      var improved = s.bestScience >
        s.centerScience + Math.max(0.025, s.centerScience * 0.06);

      if (improved && gn > 2.5) {
        s.phase = "hill";
        s.hillDirX = gx / gn;
        s.hillDirY = gy / gn;
        s.hillBest = s.bestScience;
        s.hillSteps = 0;
        s.points = [makePoint(
          s.bestX + 8 * s.hillDirX,
          s.bestY + 8 * s.hillDirY
        )];
        s.idx = 0;
        s.waitAt = -1;
        s.sum = 0;
        s.count = 0;
      } else if (s.bestScience > 0.16) {
        beginLocalScan(s, 5);
      } else {
        finishScan(s);
      }
      return;
    }

    if (s.phase === "hill") {
      beginLocalScan(s, 5);
      return;
    }

    finishScan(s);
  }

  function scanStep() {
    var s = mem.scan;
    if (!s) return zeroAction();

    if (s.idx >= s.points.length) {
      advanceScan(s);
      return zeroAction();
    }

    var p = s.points[s.idx];
    var d = dist(mem.posX, mem.posY, p.x, p.y);

    if (d > 2.15) {
      s.waitAt = -1;
      s.sum = 0;
      s.count = 0;

      var nav = navigatePoint(p.x, p.y, 1.85, 0.48,
        "scan:" + s.kind + ":" + s.idx);

      if (nav.failed) {
        s.idx++;
        s.waitAt = -1;
        s.sum = 0;
        s.count = 0;
        if (s.idx >= s.points.length) advanceScan(s);
        return zeroAction();
      }

      return nav.action;
    }

    if (speedNow > 0.17) return zeroAction();

    if (s.waitAt < 0) {
      s.waitAt = now;
      s.sum = 0;
      s.count = 0;
    }

    s.sum += science;
    s.count++;

    if (now - s.waitAt < 0.38) return zeroAction();

    var value = s.sum / Math.max(1, s.count);
    var px = p.x;
    var py = p.y;

    if (value > s.bestScience) {
      s.bestScience = value;
      s.bestX = px;
      s.bestY = py;
    }

    if ((s.phase === "center" || s.phase === "survey") && s.idx === 0) {
      s.centerScience = value;
    }

    if (s.kind === "signal" && s.phase === "hill") {
      var hillThreshold = Math.max(0.012, s.hillBest * 0.025);

      if (value > s.hillBest + hillThreshold && s.hillSteps < 4) {
        s.hillBest = value;
        s.hillSteps++;
        s.points = [makePoint(
          px + 8 * s.hillDirX,
          py + 8 * s.hillDirY
        )];
        s.idx = 0;
        s.waitAt = -1;
        s.sum = 0;
        s.count = 0;
        return zeroAction();
      }

      beginLocalScan(s, 5);
      return zeroAction();
    }

    s.idx++;
    s.waitAt = -1;
    s.sum = 0;
    s.count = 0;

    if (s.idx >= s.points.length) advanceScan(s);
    return zeroAction();
  }

  function scanRoute(s) {
    if (!s || !s.points || s.points.length === 0) {
      return { length: 0, x: mem.posX, y: mem.posY };
    }

    var px = mem.posX;
    var py = mem.posY;
    var length = 0;
    var endX = px;
    var endY = py;

    for (var i = s.idx; i < s.points.length; i++) {
      length += dist(px, py, s.points[i].x, s.points[i].y);
      px = s.points[i].x;
      py = s.points[i].y;
      endX = px;
      endY = py;
    }

    if (s.kind === "hint" && s.phase === "center") length += 125;
    else if (s.kind === "hint" && s.phase === "main") length += 20;
    else if (s.kind === "signal" && s.phase === "survey") length += 40;
    else if (s.kind === "signal" && s.phase === "hill") length += 20;

    return { length: length, x: endX, y: endY };
  }

  function makePlan(out, search, back) {
    var load = 1 + 0.13 * carried;
    var need = safeEpm() *
      (out + 1.12 * search + 1.27 * back + 18) * load +
      0.085 + 0.018 * carried;
    var total = out + search + back;
    var cruise = clamp(mem.speedAvg || 0.48, 0.38, 0.68);
    var time = total / cruise * 1.04 + 28 + 7 * carried;

    return {
      out: out,
      search: search,
      back: back,
      need: need,
      time: time,
      total: total
    };
  }

  function taskPlan() {
    if (!mem.task) return null;

    if (mem.task.kind === "hint") {
      var h = findHint(mem.task.id);
      if (!h) return null;

      if (mem.scan && mem.scan.kind === "hint" &&
          mem.scan.id === h.id) {
        var sr = scanRoute(mem.scan);
        return makePlan(0, sr.length,
          dist(sr.x, sr.y, mem.baseX, mem.baseY));
      }

      var out = dist(mem.posX, mem.posY, h.x, h.y);
      return makePlan(out, 125,
        dist(h.x, h.y, mem.baseX, mem.baseY));
    }

    if (mem.task.kind === "grid") {
      ensureGrid();
      var gp = mem.gridPts[mem.task.id];
      if (!gp) return null;

      if (mem.scan && mem.scan.kind === "signal" &&
          mem.scan.gridId === mem.task.id) {
        var gr = scanRoute(mem.scan);
        return makePlan(0, gr.length,
          dist(gr.x, gr.y, mem.baseX, mem.baseY));
      }

      var go = dist(mem.posX, mem.posY, gp.x, gp.y);
      return makePlan(go, 60, dist(gp.x, gp.y, mem.baseX, mem.baseY));
    }

    return null;
  }

  function releaseTask() {
    if (mem.task && mem.task.kind === "hint") {
      var h = findHint(mem.task.id);
      if (h && h.state === 1) h.state = 0;
    }
    mem.task = null;
    mem.scan = null;
    mem.navKey = "";
  }

  function selectTask(timeLeft) {
    if (mem.task) return;

    for (var oi = 0; oi < mem.hints.length; oi++) {
      if (mem.hints[oi].state === 1) mem.hints[oi].state = 0;
    }

    var bestHint = null;
    var bestHintScore = -1;
    var bestAnyHint = null;
    var bestAnyScore = -1;

    for (var i = 0; i < mem.hints.length; i++) {
      var h = mem.hints[i];
      if (h.state !== 0) continue;

      var out = dist(mem.posX, mem.posY, h.x, h.y);
      var search = 125;
      var back = dist(h.x, h.y, mem.baseX, mem.baseY);
      var m = makePlan(out, search, back);

      if (m.time > timeLeft - 8) continue;

      var score = Math.max(0.03, h.value) /
        (34 + m.out + 0.70 * m.back + 0.48 * m.search);

      if (m.need <= battery - 0.035 && score > bestHintScore) {
        bestHintScore = score;
        bestHint = h;
      }

      if (atHome && m.need <= mem.batteryMax + 0.025 &&
          score > bestAnyScore) {
        bestAnyScore = score;
        bestAnyHint = h;
      }
    }

    var chosenHint = bestHint || bestAnyHint;
    if (chosenHint) {
      mem.task = { kind: "hint", id: chosenHint.id, bumpCount: 0 };
      chosenHint.state = 1;
      return;
    }

    var pendingHint = false;
    for (var j = 0; j < mem.hints.length; j++) {
      if (mem.hints[j].state === 0 || mem.hints[j].state === 1) {
        pendingHint = true;
        break;
      }
    }
    if (pendingHint) return;

    ensureGrid();

    var bestGrid = -1;
    var bestGridCost = Infinity;
    var fallbackGrid = -1;
    var fallbackCost = Infinity;

    for (var gi = 0; gi < mem.gridPts.length; gi++) {
      if (mem.gridDone[gi]) continue;

      var p = mem.gridPts[gi];
      var gout = dist(mem.posX, mem.posY, p.x, p.y);
      var gback = dist(p.x, p.y, mem.baseX, mem.baseY);
      var gm = makePlan(gout, 60, gback);

      if (gm.time > timeLeft - 8) continue;

      var cost = gout + 0.42 * gback;
      if (gm.need <= battery - 0.035 && cost < bestGridCost) {
        bestGridCost = cost;
        bestGrid = gi;
      }

      if (atHome && gm.need <= mem.batteryMax + 0.025 &&
          cost < fallbackCost) {
        fallbackCost = cost;
        fallbackGrid = gi;
      }
    }

    var chosenGrid = bestGrid >= 0 ? bestGrid : fallbackGrid;
    if (chosenGrid >= 0) {
      mem.task = {
        kind: "grid",
        id: chosenGrid,
        waitAt: -1,
        sum: 0,
        count: 0
      };
    }
  }

  function executeTask() {
    if (!mem.task) return zeroAction();

    if (mem.task.kind === "hint") {
      var h = findHint(mem.task.id);
      if (!h || h.state === 2 || h.state === 3) {
        mem.task = null;
        mem.scan = null;
        return zeroAction();
      }

      if (mem.scan && mem.scan.kind === "hint" &&
          mem.scan.id === h.id) {
        return scanStep();
      }

      var hd = dist(mem.posX, mem.posY, h.x, h.y);
      if (hd > 3.0) {
        var hn = navigatePoint(h.x, h.y, 2.3, 0.50,
          "hint:" + h.id);

        if (hn.failed) {
          h.state = 3;
          mem.task = null;
          mem.scan = null;
          return zeroAction();
        }

        return hn.action;
      }

      startHintScan(h);
      return zeroAction();
    }

    if (mem.task.kind === "grid") {
      ensureGrid();
      var id = mem.task.id;
      var p = mem.gridPts[id];

      if (!p || mem.gridDone[id]) {
        mem.task = null;
        return zeroAction();
      }

      if (mem.scan && mem.scan.kind === "signal" &&
          mem.scan.gridId === id) {
        return scanStep();
      }

      var gd = dist(mem.posX, mem.posY, p.x, p.y);
      if (gd > 2.8) {
        mem.task.waitAt = -1;
        mem.task.sum = 0;
        mem.task.count = 0;

        var gn = navigatePoint(p.x, p.y, 2.0, 0.48,
          "grid:" + id);

        if (gn.failed) {
          mem.gridDone[id] = true;
          mem.task = null;
          return zeroAction();
        }

        return gn.action;
      }

      if (speedNow > 0.18) return zeroAction();

      if (mem.task.waitAt < 0) {
        mem.task.waitAt = now;
        mem.task.sum = 0;
        mem.task.count = 0;
      }

      mem.task.sum += science;
      mem.task.count++;

      if (now - mem.task.waitAt < 0.38) return zeroAction();

      var gridScience = mem.task.sum / Math.max(1, mem.task.count);
      if (gridScience > 0.14) {
        startSignalScan(p.x, p.y, id);
        return zeroAction();
      }

      mem.gridDone[id] = true;
      mem.task = null;
      return zeroAction();
    }

    return zeroAction();
  }

  function associateSampleHint() {
    var sx = mem.liveLocValid ? mem.liveX : mem.posX;
    var sy = mem.liveLocValid ? mem.liveY : mem.posY;
    var best = nearestHint(sx, sy, 36);

    if (mem.task && mem.task.kind === "hint") {
      var active = findHint(mem.task.id);
      if (active && dist(sx, sy, active.x, active.y) < 38) {
        best = active;
      }
    }

    return best ? best.id : -1;
  }

  function startSampleTarget() {
    mem.sampleTarget = true;
    mem.sampleHintId = associateSampleHint();
    mem.sampleLocValid = mem.liveLocValid;

    if (mem.liveLocValid) {
      mem.sampleX = mem.liveX;
      mem.sampleY = mem.liveY;
    } else {
      mem.sampleX = mem.posX;
      mem.sampleY = mem.posY;
    }

    mem.sampleAnchorSet = false;
    mem.sampleStable = 0;
    mem.sampleBestD = siteValid ? siteDistance :
      (mem.sampleLocValid ? dist(mem.posX, mem.posY, mem.sampleX, mem.sampleY) : 99);
    mem.sampleProgressAt = now;
    mem.navKey = "";
  }

  function abandonSample() {
    if (mem.sampleHintId >= 0) {
      var h = findHint(mem.sampleHintId);
      if (h && h.state !== 2) h.state = 3;
      if (mem.task && mem.task.kind === "hint" &&
          mem.task.id === mem.sampleHintId) {
        mem.task = null;
        mem.scan = null;
      }
    }

    mem.sampleIgnoreUntil = now + 18;
    clearSampleState();
    mem.navKey = "";
  }

  function sampleAction() {
    var live = siteValid;
    var d = 99;
    var rel = 0;

    if (live) {
      d = siteDistance;
      rel = siteBearing;

      if (mem.liveLocValid) {
        mem.sampleX = 0.78 * mem.sampleX + 0.22 * mem.liveX;
        mem.sampleY = 0.78 * mem.sampleY + 0.22 * mem.liveY;
        mem.sampleLocValid = true;
      }
    } else if (mem.sampleLocValid) {
      var dx = mem.sampleX - mem.posX;
      var dy = mem.sampleY - mem.posY;
      d = Math.hypot(dx, dy);
