  function clearSampleState() {
    mem.sampleTarget = false;
    mem.sampleHintId = -1;
    mem.sampleLocValid = false;
    mem.sampleAnchorSet = false;
  }

  function completeSample() {
    var sx = mem.sampleLocValid ? mem.sampleX : mem.posX;
    var sy = mem.sampleLocValid ? mem.sampleY : mem.posY;
    var h = mem.sampleHintId >= 0
      ? findHint(mem.sampleHintId)
      : null;

    if (!h) h = nearestHint(sx, sy, 40);

    if (mem.task && mem.task.kind === "hint") {
      var activeHint = findHint(mem.task.id);
      if (activeHint && dist(sx, sy, activeHint.x, activeHint.y) < 40) {
        h = activeHint;
      }
    }

    if (h) h.state = 2;

    if (mem.task && mem.task.kind === "hint" &&
        h && h.id === mem.task.id) {
      mem.task = null;
    }

    if (mem.task && mem.task.kind === "grid") {
      if (mem.gridDone[mem.task.id] !== undefined) {
        mem.gridDone[mem.task.id] = true;
      }
      mem.task = null;
    }

    if (mem.search) {
      storeSearched(mem.search.originX, mem.search.originY,
        mem.search.bestScience);
      if (mem.search.hintId >= 0) {
        var sh = findHint(mem.search.hintId);
        if (sh) sh.state = 2;
        if (mem.task && mem.task.kind === "hint" &&
            mem.task.id === mem.search.hintId) {
          mem.task = null;
        }
      }
      if (mem.search.gridId >= 0 &&
          mem.gridDone[mem.search.gridId] !== undefined) {
        mem.gridDone[mem.search.gridId] = true;
      }
      mem.search = null;
    }

    storeSearched(sx, sy, science);
    clearSampleState();
    mem.navKey = "";
  }

  var oldCarried = mem.lastCarried;
  if (carried > oldCarried + 0.01) {
    completeSample();
  } else if (carried < oldCarried - 0.01) {
    clearSampleState();
  }
  mem.lastCarried = carried;

  var delivered = num(obs.delivered, mem.lastDelivered);
  var deliveredChanged = delivered > mem.lastDelivered + 0.001;
  mem.lastDelivered = delivered;
  if (deliveredChanged) mem.returning = false;

  var beacon = obs.beacon || null;
  var hasBeacon = !!beacon &&
    num(beacon.distance, 99) <= 20.5;
  var gpsBaseDist = dist(mem.posX, mem.posY, mem.baseX, mem.baseY);
  var baseDist = hasBeacon
    ? clamp(num(beacon.distance, gpsBaseDist), 0, 25)
    : gpsBaseDist;

  var speedNow = Math.max(Math.abs(wheelL), Math.abs(wheelR));
  var atHome = docked || (baseDist < 2.6 && speedNow < 0.18);

  if (atHome) {
    mem.batteryMax = Math.max(mem.batteryMax, battery);
  }

  function safeEpm() {
    return clamp(
      Math.max(0.00055, mem.epm * 1.5, mem.epmHigh * 1.3),
      0.00055,
      0.025
    );
  }

  function energyCost(distance, count) {
    var load = 1 + 0.14 * Math.max(0, count);
    return safeEpm() * Math.max(0, distance) * load * 1.45 +
      0.10 + 0.015 * Math.max(0, count);
  }

  function cruiseSpeed() {
    return clamp(mem.speedAvg || 0.55, 0.38, 0.78);
  }

  function returnTime(count) {
    return baseDist / Math.max(0.32, cruiseSpeed() * 0.78) +
      25 + 6 * Math.max(0, count);
  }

  function canSampleAnother(progress) {
    var nextCount = carried + 1;
    var need = energyCost(baseDist + 20, nextCount) +
      safeEpm() * 8 + 0.02;
    var remainingDrill = Math.max(0, 6 - progress);
    return battery > need + 0.04 &&
      num(obs.timeLeft, mem.missionSeconds - now) >
        returnTime(nextCount) + remainingDrill + 10;
  }

  var pitch = num(obs.pitch, 0) * RAD;

  function motor(v, omega) {
    v = clamp(v, -0.72, 0.72);
    omega = clamp(omega, -1.15, 1.15);

    var targetL = clamp(v - 0.3 * omega, -0.95, 0.95);
    var targetR = clamp(v + 0.3 * omega, -0.95, 0.95);
    var pitchComp = docked ? 0 : 0.055 * Math.sin(pitch);

    function one(target, actual, side) {
      var gain = Math.max(0.65, side === 0 ? mem.gainL : mem.gainR);
      var integral = side === 0 ? mem.iL : mem.iR;
      var prev = side === 0 ? mem.prevTargetL : mem.prevTargetR;
      var dead = side === 0 ? mem.deadL : mem.deadR;

      if (target * prev < -0.02 || Math.abs(target - prev) > 0.72) {
        integral *= 0.35;
      }

      var u;
      if (Math.abs(target) < 0.022) {
        integral *= 0.72;
        u = -0.58 * actual / gain + integral + pitchComp;
      } else {
        var err = target - actual;
        integral = clamp(integral + err * dt * 0.10 / gain,
          -0.12, 0.12);
        u = target / gain + 0.25 * err / gain +
          integral + (target > 0 ? dead : -dead) + pitchComp;
      }

      if (docked && Math.abs(target) < 0.022) u = 0;
      u = clamp(u, -1, 1);

      if (side === 0) {
        mem.iL = integral;
        mem.prevTargetL = target;
      } else {
        mem.iR = integral;
        mem.prevTargetR = target;
      }
      return u;
    }

    return {
      l: one(targetL, wheelL, 0),
      r: one(targetR, wheelR, 1),
      v: v,
      omega: omega
    };
  }

  function zeroAction() {
    return motor(0, 0);
  }

  function finish(action, drill) {
    var left = clamp(num(action && action.l, 0), -1, 1);
    var right = clamp(num(action && action.r, 0), -1, 1);

    mem.lastCmdL = left;
    mem.lastCmdR = right;
    mem.lastDesiredV = num(action && action.v, 0);
    mem.lastDesiredOmega = num(action && action.omega, 0);
    mem.lastDrillCmd = !!drill;

    return { left: left, right: right, drill: !!drill };
  }

  function rayAt(angle) {
    angle = clamp(angle, -80, 80);
    var index = (angle + 80) / 20;
    var lo = clamp(Math.floor(index), 0, 8);
    var hi = clamp(Math.ceil(index), 0, 8);
    var f = index - lo;
    return clamp(mem.rays[lo] * (1 - f) + mem.rays[hi] * f, 0, 15);
  }

  function sideClear(side) {
    var start = side > 0 ? 5 : 0;
    var end = side > 0 ? 8 : 3;
    var sum = 0;
    for (var i = start; i <= end; i++) sum += mem.rays[i];
    return sum / (end - start + 1);
  }

  function chooseDirection(goalRel) {
    goalRel = wrap(goalRel);
    var direct = clamp(goalRel, -80, 80);
    var directClear = rayAt(direct);

    if (directClear >= 4.5) {
      return { angle: direct, clear: directClear };
    }

    if (now > mem.avoidUntil || !mem.avoidSide) {
      mem.avoidSide = sideClear(1) >= sideClear(-1) ? 1 : -1;
      mem.avoidUntil = now + 1.8;
    }

    var candidates = [-80, -60, -40, -20, 0, 20, 40, 60, 80, direct];
    var bestAngle = direct;
    var bestClear = directClear;
    var bestCost = Infinity;

    for (var i = 0; i < candidates.length; i++) {
      var a = candidates[i];
      var clear = rayAt(a);
      var cost = Math.abs(wrap(a - goalRel));

      if (clear < 0.9) cost += 260 + (0.9 - clear) * 70;
      else if (clear < 1.5) cost += 110 + (1.5 - clear) * 45;
      else if (clear < 2.2) cost += 45 + (2.2 - clear) * 24;
      else if (clear < 3.2) cost += 12 + (3.2 - clear) * 7;
      else if (clear < 4.5) cost += (4.5 - clear) * 2.5;

      if (Math.abs(a) > 12 && (a > 0 ? 1 : -1) !== mem.avoidSide) {
        cost += 2.5;
      }

      if (cost < bestCost) {
        bestCost = cost;
        bestAngle = a;
        bestClear = clear;
      }
    }

    return { angle: bestAngle, clear: bestClear };
  }

  function driveBearing(rel, distance, stopRadius, maxV) {
    rel = wrap(rel);
    distance = Math.max(0, num(distance, 0));
    stopRadius = Math.max(0, stopRadius);

    if (distance <= stopRadius + 0.10) return zeroAction();

    var remain = Math.max(0, distance - stopRadius);

    if (Math.abs(rel) > 96) {
      var spin = clamp(1.65 * rel * RAD - 0.62 * yawRate, -0.92, 0.92);
      return motor(0, spin);
    }

    var info = chooseDirection(rel);
    var steer = info.angle;
    var speed = Math.min(maxV, Math.sqrt(0.45 * remain));

    if (Math.abs(steer) > 58) speed = Math.min(speed, 0.10);
    else if (Math.abs(steer) > 44) speed = Math.min(speed, 0.20);
    else if (Math.abs(steer) > 30) speed = Math.min(speed, 0.36);

    if (Math.abs(wrap(steer - rel)) > 35) {
      speed = Math.min(speed, 0.22);
    }

    if (info.clear < 1.05) speed = 0;
    else if (info.clear < 1.55) speed = Math.min(speed, 0.07);
    else if (info.clear < 2.2) speed = Math.min(speed, 0.14);
    else if (info.clear < 3.1) speed = Math.min(speed, 0.26);
    else if (info.clear < 4.5) speed = Math.min(speed, 0.42);

    var front = rayAt(0);
    if (Math.abs(steer) < 32) {
      if (front < 1.0) speed = 0;
      else if (front < 1.55) speed = Math.min(speed, 0.07);
      else if (front < 2.2) speed = Math.min(speed, 0.14);
      else if (front < 3.2) speed = Math.min(speed, 0.27);
    }

    var omega = clamp(
      1.9 * steer * RAD - 0.64 * yawRate,
      -1.05,
      1.05
    );
    if (Math.abs(steer) < 1.0 && Math.abs(yawRate) < 0.08) omega = 0;

    return motor(speed, omega);
  }

  function drivePoint(x, y, stopRadius, maxV) {
    x = clamp(x, 3, mem.mapW - 3);
    y = clamp(y, 3, mem.mapH - 3);

    var dx = x - mem.posX;
    var dy = y - mem.posY;
    var d = Math.hypot(dx, dy);
    var rel = d < 0.01
      ? 0
      : wrap(Math.atan2(dy, dx) / RAD - mem.hEst);

    return driveBearing(rel, d, stopRadius, maxV);
  }

  function navigatePoint(x, y, stopRadius, maxV, key) {
    var d = dist(mem.posX, mem.posY, x, y);

    if (mem.navKey !== key) {
      mem.navKey = key;
      mem.navBestD = d;
      mem.navProgressAt = now;
    } else if (d < mem.navBestD - 0.40) {
      mem.navBestD = d;
      mem.navProgressAt = now;
    }

    if (d > stopRadius + 0.9 &&
        now - mem.navProgressAt > 28) {
      return { failed: true, action: zeroAction(), distance: d };
    }

    return {
      failed: false,
      action: drivePoint(x, y, stopRadius, maxV),
      distance: d
    };
  }

  function startRecovery(side) {
    mem.recoverStart = now;
    mem.recoverUntil = now + 1.05;
    mem.recoverSide = side || 1;
    mem.lastBump = now;
    mem.stuckStart = -1;
    mem.navKey = "";
  }

  if (!mem.sampleTarget && drillProgress <= 0.01 &&
      obs.bumped && !mem.bumpPrev && now - mem.lastBump > 1.0) {
    startRecovery(sideClear(1) >= sideClear(-1) ? 1 : -1);
  }
  mem.bumpPrev = !!obs.bumped;

  if (!mem.sampleTarget &&
      Math.abs(mem.lastDesiredV || 0) > 0.30 &&
      Math.abs(wheelV) > 0.18 &&
      !gpsFrozen) {
    if (mem.stuckStart < 0) {
      mem.stuckStart = now;
      mem.stuckX = mem.posX;
      mem.stuckY = mem.posY;
    } else if (now - mem.stuckStart > 10) {
      if (dist(mem.posX, mem.posY, mem.stuckX, mem.stuckY) < 0.55 &&
          now - mem.lastBump > 2) {
        startRecovery(sideClear(1) >= sideClear(-1) ? 1 : -1);
      } else {
        mem.stuckStart = now;
        mem.stuckX = mem.posX;
        mem.stuckY = mem.posY;
      }
    }
  } else {
    mem.stuckStart = -1;
  }

  function recoveryAction() {
    if (now >= mem.recoverUntil) return null;
    if (now - mem.recoverStart < 0.34) return motor(-0.22, 0);
    return motor(0, mem.recoverSide * 0.58);
  }

  function makePoint(x, y) {
    return {
      x: clamp(x, 3, mem.mapW - 3),
      y: clamp(y, 3, mem.mapH - 3)
    };
  }

  function addUniquePoint(points, x, y) {
    var p = makePoint(x, y);
    for (var i = 0; i < points.length; i++) {
      if (dist(p.x, p.y, points[i].x, points[i].y) < 2.5) return;
    }
    points.push(p);
  }

  function ringPoints(cx, cy, radius) {
    var points = [];
    var start = Math.atan2(mem.posY - cy, mem.posX - cx);
    for (var i = 0; i < 8; i++) {
      var a = start + i * Math.PI / 4;
      addUniquePoint(
        points,
        cx + radius * Math.cos(a),
        cy + radius * Math.sin(a)
      );
    }
    return points;
  }

  function startSearchStage(s, cx, cy, value, radius) {
    s.centerX = cx;
    s.centerY = cy;
    s.centerValue = Math.max(0, value);
    s.stageBest = s.centerValue;
    s.stageBestX = cx;
    s.stageBestY = cy;
    s.radius = radius;
    s.points = ringPoints(cx, cy, radius);
    s.idx = 0;
    s.waitAt = -1;
    s.sum = 0;
    s.count = 0;
  }

  function startSearch(x, y, value, hintId, gridId) {
    var v = Math.max(0, value);
    var radius = v > 1.2 ? 6.5 : (v > 0.28 ? 9 : 16);

    var s = {
      id: mem.nextSearchId++,
      originX: x,
      originY: y,
      originScience: v,
      hintId: hintId === undefined ? -1 : hintId,
      gridId: gridId === undefined ? -1 : gridId,
      level: 0,
      wideTried: false,
      bestScience: v,
      bestX: x,
      bestY: y
    };

    mem.search = s;
    startSearchStage(s, x, y, v, radius);
    mem.navKey = "";
  }

  function ensureGrid() {
    if (mem.gridReady) return;

    mem.gridPts = [];
    mem.gridDone = [];
    var step = 65;

    for (var y = 30; y <= mem.mapH - 20; y += step) {
      for (var x = 30; x <= mem.mapW - 20; x += step) {
        mem.gridPts.push(makePoint(x, y));
        mem.gridDone.push(false);
      }
    }

    if (mem.gridPts.length === 0) {
      mem.gridPts.push(makePoint(mem.mapW * 0.5, mem.mapH * 0.5));
      mem.gridDone.push(false);
    }

    mem.gridReady = true;
  }

  function recentSearch(x, y, value) {
    for (var i = mem.searched.length - 1; i >= 0; i--) {
      var a = mem.searched[i];
      if (now - a.t > 900) continue;
      if (dist(x, y, a.x, a.y) < 18 &&
          value < a.peak * 1.45 + 0.12) {
        return true;
      }
    }
    return false;
  }

  function finishSearch(s) {
    storeSearched(s.originX, s.originY, s.bestScience);

    if (s.hintId >= 0) {
      var h = findHint(s.hintId);
      if (h) h.state = 2;
      if (mem.task && mem.task.kind === "hint" &&
          mem.task.id === s.hintId) {
        mem.task = null;
      }
    }

    if (s.gridId >= 0) {
      ensureGrid();
      if (mem.gridDone[s.gridId] !== undefined) {
        mem.gridDone[s.gridId] = true;
      }
      if (mem.task && mem.task.kind === "grid" &&
          mem.task.id === s.gridId) {
        mem.task = null;
      }
    }

    if (mem.search === s) mem.search = null;
    mem.navKey = "";
  }

  function advanceSearchStage(s) {
    var threshold = Math.max(0.018, s.centerValue * 0.035);

    if (s.stageBest > s.centerValue + threshold && s.level < 3) {
      s.centerX = s.stageBestX;
      s.centerY = s.stageBestY;
      s.centerValue = s.stageBest;
      s.bestScience = Math.max(s.bestScience, s.stageBest);
      s.bestX = s.stageBestX;
      s.bestY = s.stageBestY;
      s.level++;
      startSearchStage(
        s,
        s.centerX,
        s.centerY,
        s.centerValue,
        Math.max(2.8, s.radius * 0.52)
      );
      return;
    }

    if (!s.wideTried && s.level === 0 && s.radius < 13.5) {
      s.wideTried = true;
      startSearchStage(
        s,
        s.originX,
        s.originY,
        s.originScience,
        16
      );
      return;
    }

    finishSearch(s);
  }

  function scanStep() {
    var s = mem.search;
    if (!s) return zeroAction();

    if (s.idx >= s.points.length) {
      advanceSearchStage(s);
      return zeroAction();
    }

    var p = s.points[s.idx];
    var d = dist(mem.posX, mem.posY, p.x, p.y);

    if (d > 2.0) {
      s.waitAt = -1;
      s.sum = 0;
      s.count = 0;

      var nav = navigatePoint(
        p.x,
        p.y,
        1.35,
        0.48,
        "search:" + s.id + ":" + s.level + ":" + s.idx
      );

      if (nav.failed) {
        s.idx++;
        s.waitAt = -1;
        s.sum = 0;
        s.count = 0;
        if (s.idx >= s.points.length) advanceSearchStage(s);
        return zeroAction();
      }

      return nav.action;
    }

    if (speedNow > 0.17) return zeroAction();

    if (s.waitAt < 0) {
      s.waitAt = now;
      s.sum = 0;
      s.count = 0;
    }

    s.sum += science;
    s.count++;

    if (now - s.waitAt < 0.42) return zeroAction();

    var value = s.sum / Math.max(1, s.count);
    if (value > s.stageBest) {
      s.stageBest = value;
      s.stageBestX = p.x;
      s.stageBestY = p.y;
    }
    if (value > s.bestScience) {
      s.bestScience = value;
      s.bestX = p.x;
      s.bestY = p.y;
    }

    s.idx++;
    s.waitAt = -1;
    s.sum = 0;
    s.count = 0;

    if (s.idx >= s.points.length) advanceSearchStage(s);
    return zeroAction();
  }

  function searchRoute(s) {
    var px = mem.posX;
    var py = mem.posY;
    var length = 0;
    var endX = px;
    var endY = py;

    if (!s || !s.points) {
      return { length: 0, x: px, y: py };
    }

    for (var i = s.idx; i < s.points.length; i++) {
      length += dist(px, py, s.points[i].x, s.points[i].y);
      px = s.points[i].x;
      py = s.points[i].y;
      endX = px;
      endY = py;
    }

    if (s.level < 3) length += 18;
    return { length: length, x: endX, y: endY };
  }

  function selectTask(timeLeft) {
    if (mem.task || mem.search) return;

    for (var oi = 0; oi < mem.hints.length; oi++) {
      if (mem.hints[oi].state === 1) mem.hints[oi].state = 0;
    }

    var bestHint = null;
    var bestScore = -1;

    for (var i = 0; i < mem.hints.length; i++) {
      var h = mem.hints[i];
      if (h.state !== 0) continue;

      var out = dist(mem.posX, mem.posY, h.x, h.y);
      var back = dist(h.x, h.y, mem.baseX, mem.baseY);
      var search = 58;
      var total = out + back + search + 12;
      var need = energyCost(total, carried);
      var planTime = total / Math.max(0.32, cruiseSpeed() * 0.82) +
        28 + 6 * carried;

      if (planTime > timeLeft - 5) continue;

      var allowed = need <= battery - 0.025;
      if (atHome && need <= mem.batteryMax + 0.02) allowed = true;
      if (!allowed) continue;

      var score = Math.max(0.02, h.value) /
        (34 + out + 0.68 * back + 0.48 * search);

      if (score > bestScore) {
        bestScore = score;
        bestHint = h;
      }
    }

    if (bestHint) {
      mem.task = { kind: "hint", id: bestHint.id };
      bestHint.state = 1;
      return;
    }

    ensureGrid();

    var bestGrid = -1;
    var bestGridCost = Infinity;

    for (var gi = 0; gi < mem.gridPts.length; gi++) {
      if (mem.gridDone[gi]) continue;

      var gp = mem.gridPts[gi];
      var gout = dist(mem.posX, mem.posY, gp.x, gp.y);
      var gback = dist(gp.x, gp.y, mem.baseX, mem.baseY);
      var gsearch = 32;
      var gtotal = gout + gback + gsearch + 12;
      var gneed = energyCost(gtotal, carried);
      var gtime = gtotal / Math.max(0.32, cruiseSpeed() * 0.82) +
        25 + 6 * carried;

      if (gtime > timeLeft - 5) continue;

      var gridAllowed = gneed <= battery - 0.025;
      if (atHome && gneed <= mem.batteryMax + 0.02) gridAllowed = true;
      if (!gridAllowed) continue;

      var cost = gout + 0.40 * gback;
      if (cost < bestGridCost) {
        bestGridCost = cost;
        bestGrid = gi;
      }
    }

    if (bestGrid >= 0) {
      mem.task = {
        kind: "grid",
        id: bestGrid,
        waitAt: -1,
        sum: 0,
        count: 0
      };
    }
  }

  function releaseTask() {
    if (mem.task && mem.task.kind === "hint") {
      var h = findHint(mem.task.id);
      if (h && h.state === 1) h.state = 0;
    }
    mem.task = null;
    mem.search = null;
    mem.navKey = "";
  }

  function taskEstimate() {
    if (mem.search) {
      var sr = searchRoute(mem.search);
      var back = dist(sr.x, sr.y, mem.baseX, mem.baseY);
      var total = sr.length + back + 12;
      return {
        need: energyCost(total, carried),
        time: total / Math.max(0.32, cruiseSpeed() * 0.82) +
          25 + 6 * carried
      };
    }

    if (!mem.task) return null;

    if (mem.task.kind === "hint") {
      var h = findHint(mem.task.id);
      if (!h) return null;
      var out = dist(mem.posX, mem.posY, h.x, h.y);
      var back = dist(h.x, h.y, mem.baseX, mem.baseY);
      var total = out + 58 + back + 12;
      return {
        need: energyCost(total, carried),
        time: total / Math.max(0.32, cruiseSpeed() * 0.82) +
          28 + 6 * carried
      };
    }

    if (mem.task.kind === "grid") {
      ensureGrid();
      var p = mem.gridPts[mem.task.id];
      if (!p) return null;
      var go = dist(mem.posX, mem.posY, p.x, p.y);
      var backGrid = dist(p.x, p.y, mem.baseX, mem.baseY);
      var totalGrid = go + 32 + backGrid + 12;
      return {
        need: energyCost(totalGrid, carried),
        time: totalGrid / Math.max(0.32, cruiseSpeed() * 0.82) +
