    var sy = mem.liveLocValid ? mem.liveY : mem.posY;
    var h = nearestHint(sx, sy, 40);

    if (mem.task && mem.task.kind === "hint") {
      var active = findHint(mem.task.id);
      if (active && dist(sx, sy, active.x, active.y) < 42) h = active;
    }

    if (h) mem.sampleHintId = h.id;

    mem.sampleLocValid = mem.liveLocValid &&
      now - mem.liveSeen < 5;
    if (mem.sampleLocValid) {
      mem.sampleX = mem.liveX;
      mem.sampleY = mem.liveY;
    } else {
      mem.sampleX = mem.posX;
      mem.sampleY = mem.posY;
    }

    mem.sampleAnchorSet = false;
    mem.navKey = "";
  }

