    var rel = 0;
    var live = siteValid;

    if (live) {
      d = siteDistance;
      rel = siteBearing;

      if (mem.liveLocValid) {
        if (!mem.sampleLocValid) {
          mem.sampleX = mem.liveX;
          mem.sampleY = mem.liveY;
          mem.sampleLocValid = true;
        } else {
          mem.sampleX = 0.78 * mem.sampleX + 0.22 * mem.liveX;
          mem.sampleY = 0.78 * mem.sampleY + 0.22 * mem.liveY;
        }
      }
    } else if (mem.sampleLocValid) {
      var dx = mem.sampleX - mem.posX;
      var dy = mem.sampleY - mem.posY;
      d = Math.hypot(dx, dy);
      rel = d < 0.01
        ? 0
        : wrap(Math.atan2(dy, dx) / RAD - mem.hEst);
    } else {
      d = 0;
    }

    if ((d > 1.30 && drillProgress <= 0.01) || d > 1.46) {
      mem.sampleAnchorSet = false;
      var approach = driveBearing(rel, d, 0.98, 0.38);
      return { action: approach, drill: false };
    }

    if (!mem.sampleAnchorSet) {
      if (speedNow > 0.17) {
        return { action: zeroAction(), drill: false };
      }
      mem.sampleAnchorX = mem.posX;
      mem.sampleAnchorY = mem.posY;
      mem.sampleAnchorH = mem.hEst;
      mem.sampleAnchorSet = true;
    }

    var hrad = mem.hEst * RAD;
    var ex = mem.sampleAnchorX - mem.posX;
    var ey = mem.sampleAnchorY - mem.posY;
