    var scanRecovery = recoveryAction();
    if (scanRecovery) return finish(scanRecovery, false);
    return finish(scanStep(), false);
  }

  if (!mem.task) {
    selectTask(timeLeft);
  }

  if (!mem.task) {
    if (!atHome && baseDist > 2.8) {
      mem.returning = true;
      return finish(makeBaseAction(), false);
    }
    return finish(zeroAction(), false);
  }

  if (mem.task.kind === "hint") {
    var hint = findHint(mem.task.id);

    if (!hint || hint.state === 2) {
      mem.task = null;
      return finish(zeroAction(), false);
    }

    var hd = dist(mem.posX, mem.posY, hint.x, hint.y);
    if (hd > 2.8) {
      var hn = navigatePoint(
        hint.x,
        hint.y,
        2.0,
        0.55,
        "hint:" + hint.id
      );

      if (hn.failed) {
        hint.state = 2;
        mem.task = null;
        mem.search = null;
        mem.navKey = "";
        return finish(zeroAction(), false);
      }

      return finish(hn.action, false);
    }

    startSearch(mem.posX, mem.posY, science, hint.id, -1);
    return finish(scanStep(), false);
  }

  if (mem.task.kind === "grid") {
    ensureGrid();
    var gridId = mem.task.id;
    var gp = mem.gridPts[gridId];

    if (!gp || mem.gridDone[gridId]) {
      mem.task = null;
      return finish(zeroAction(), false);
    }

    var gd = dist(mem.posX, mem.posY, gp.x, gp.y);
    if (gd > 2.2) {
      var gn = navigatePoint(
        gp.x,
        gp.y,
        1.5,
        0.55,
        "grid:" + gridId
      );

      if (gn.failed) {
        mem.gridDone[gridId] = true;
        mem.task = null;
        mem.navKey = "";
        return finish(zeroAction(), false);
      }

      return finish(gn.action, false);
    }

    if (speedNow > 0.17) return finish(zeroAction(), false);

    if (mem.task.waitAt < 0) {
      mem.task.waitAt = now;
      mem.task.sum = 0;
      mem.task.count = 0;
    }

    mem.task.sum += science;
    mem.task.count++;

    if (now - mem.task.waitAt < 0.40) {
      return finish(zeroAction(), false);
    }

    var gridSignal = mem.task.sum / Math.max(1, mem.task.count);
    if (gridSignal > 0.13 &&
        !recentSearch(gp.x, gp.y, gridSignal)) {
      startSearch(gp.x, gp.y, gridSignal, -1, gridId);
      return finish(scanStep(), false);
    }

    mem.gridDone[gridId] = true;
    mem.task = null;
    mem.navKey = "";
    return finish(zeroAction(), false);
  }

  mem.task = null;
  return finish(zeroAction(), false);
}

