      }
    }
    if (!m.explore.length) m.explore.push({ x: m.sizeX * 0.5, y: m.sizeY * 0.5, visited: false });

    m.wl = { u: 0, g: 2.5, dz: 0, boost: 0 };
    m.wr = { u: 0, g: 2.5, dz: 0, boost: 0 };
    m.vL = fin(o.wheelLeft, 0);
    m.vR = fin(o.wheelRight, 0);
    m.pitch = fin(o.pitch, 0);

    m.rays = [15, 15, 15, 15, 15, 15, 15, 15, 15];
    m.site = null;
    m.beacon = null;
    m.science = fin(o.science, 0);
    m.battery = fin(o.battery, 1);
    m.prevBattery = m.battery;
    m.solar = fin(o.solar, 0);
    m.carried = fin(o.carried, 0);
    m.prevCarried = m.carried;
    m.carriedValue = fin(o.carriedValue, 0);
    m.delivered = fin(o.delivered, 0);
    m.timeLeft = fin(o.timeLeft, m.seconds);
    m.docked = !!o.docked;
    m.bumped = !!o.bumped;
    m.prevBumped = m.bumped;
    m.drilling = fin(o.drilling, 0);

    m.state = "idle";
    m.activeHint = -1;
    m.searchPlan = [];
    m.searchIdx = 0;
    m.searchStart = t;
    m.searchWayT = t;
    m.searchLimit = 330;
    m.gotoStart = t;
    m.exploreTarget = null;
    m.sample = null;
    m.sampleFails = 0;
    m.ignoreSampleUntil = -1000;
    m.sampledTotal = 0;
    m.deliveredSamples = 0;
    m.wasCarrying = m.carried > 0;
    m.lastDeliverT = -1000;
    m.chargeStart = -1000;
    m.lastChargeExit = -1000;
    m.lastSampleT = -1000;

    m.recover = null;
    m.recoverCount = 0;
    m.lastRecover = -1000;
    m.avoidSide = 0;
    m.avoidStart = -1000;
    m.prevSteer = 0;

    m.stuckT = t;
    m.stuckPos = { x: m.pos.x, y: m.pos.y };
    m.stuckHead = m.head;
    m.cmdL = 0;
    m.cmdR = 0;

    m.ePerM = 0.0007;
    m.ignoreSiteUntil = -1000;
  }

  function updateSensors(o, m, t, dt) {
    const oldCarried = m.carried;
    m.prevCarried = oldCarried;
    m.prevBattery = m.battery;
    m.prevBumped = m.bumped;

    m.vL = fin(o.wheelLeft, m.vL);
    m.vR = fin(o.wheelRight, m.vR);
    m.pitch = fin(o.pitch, m.pitch);
    m.carried = fin(o.carried, oldCarried);
    m.carriedValue = fin(o.carriedValue, m.carriedValue);
    m.delivered = fin(o.delivered, m.delivered);
    m.battery = fin(o.battery, m.battery);
    m.solar = fin(o.solar, 0);
    m.timeLeft = fin(o.timeLeft, m.timeLeft);
    m.docked = !!o.docked;
    m.bumped = !!o.bumped;
    m.drilling = fin(o.drilling, 0);
    m.science = fin(o.science, 0);

    const rr = o.rays || [];
    for (let i = 0; i < 9; i++) {
      let r = +rr[i];
      if (!isFinite(r) || r < 0) r = 15;
      if (r > 15) r = 15;
      if (r < 0.03) r = 0.03;
      m.rays[i] = r;
    }

    m.site = null;
    if (o.site) {
      let d = fin(o.site.distance, NaN);
      let b = fin(o.site.bearing, NaN);
      let v = fin(o.site.value, 1);
      if (isFinite(d) && isFinite(b) && d >= 0) {
