      }
    }

    m.beacon = null;
    if (o.beacon) {
      let d = fin(o.beacon.distance, NaN);
      let b = fin(o.beacon.bearing, NaN);
      if (isFinite(d) && isFinite(b) && d >= 0) {
        m.beacon = { d: d, b: wrap(b * D2R) };
      }
    }

    let ds = Math.abs((m.vL + m.vR) * 0.5) * dt;
    let used = (m.prevBattery - m.battery) + m.solar * dt;
    if (ds > 0.02 && !m.docked) {
      let inst = used / ds;
      if (inst > -0.02 && inst < 0.05) m.ePerM = m.ePerM * 0.98 + inst * 0.02;
