    m.ePerM = clamp(m.ePerM, 0.00015, 0.012);
  }

  function updatePose(o, m, t, dt) {
    let rawH = wrap(fin(o.heading, m.lastRaw * R2D) * D2R);
    let yaw = ((m.vR - m.vL) / WB) * dt;
    let pred = wrap(m.head + yaw);
    let hd = wrap(rawH - pred);

    if (Math.abs(hd) > 1.45 && Math.abs(yaw) < 0.30) {
      m.head = pred;
      m.compassRej++;
      if (m.compassRej > 10) {
        m.head = wrap(pred + hd * 0.35);
        m.compassRej = 0;
      }
    } else {
      let alpha = Math.abs(hd) > 0.45 ? 0.30 : 0.58;
      m.head = wrap(pred + hd * alpha);
      m.compassRej = 0;
      m.lastRaw = rawH;
    }
    m.rawHead = rawH;

    let gx = fin(o.x, NaN);
    let gy = fin(o.y, NaN);
    let fresh = false;
    if (isFinite(gx) && isFinite(gy)) {
      if (Math.abs(gx - m.gpsX) > 0.0005 || Math.abs(gy - m.gpsY) > 0.0005) fresh = true;
    }

    if (fresh) {
      let e = dist(gx, gy, m.pos.x, m.pos.y);
      let alpha = 0.60;
      if (e < 0.6) alpha = 0.82;
      else if (e > 8.0) alpha = e > 20 ? 0.25 : 0.38;
      if (m.gpsStale > 3.0) alpha = 0.88;
      m.pos.x += (gx - m.pos.x) * alpha;
      m.pos.y += (gy - m.pos.y) * alpha;
      m.gpsX = gx;
      m.gpsY = gy;
      m.gpsStale = 0;

      if (Math.abs(m.vR - m.vL) < 0.12 && Math.abs((m.vL + m.vR) * 0.5) > 0.10) {
