          if (t - m.cal.t > 1.2 && dd > 1.0) {
            let course = Math.atan2(m.pos.y - m.cal.y, m.pos.x - m.cal.x);
            let corr = wrap(course - m.head);
            if (Math.abs(corr) < 1.2) m.head = wrap(m.head + corr * 0.22);
            m.cal = { x: m.pos.x, y: m.pos.y, t: t };
          }
        }
      } else {
        m.cal = null;
      }
    } else {
      let avg = (m.vL + m.vR) * 0.5;
      let hm = wrap(m.head - yaw * 0.5);
      m.pos.x += Math.cos(hm) * avg * dt;
      m.pos.y += Math.sin(hm) * avg * dt;
      m.gpsStale += dt;
    }

    m.pos.x = clamp(m.pos.x, 0, m.sizeX);
    m.pos.y = clamp(m.pos.y, 0, m.sizeY);
  }

  function rayAt(m, rel) {
    let deg = wrap(rel) * R2D;
    if (deg < -80) deg = -80;
    if (deg > 80) deg = 80;
    let f = (deg + 80) / 20;
    let i = Math.floor(f);
    if (i < 0) i = 0;
    if (i > 7) i = 7;
    let u = clamp(f - i, 0, 1);
    let a = m.rays[i];
    let b = m.rays[i + 1];
    let v = a * (1 - u) + b * u;
