  function corridor(m, rel) {
    rel = wrap(rel);
    let c = rayAt(m, rel);
    c = Math.min(c, rayAt(m, wrap(rel - 0.18)));
    c = Math.min(c, rayAt(m, wrap(rel + 0.18)));
    c = Math.min(c, rayAt(m, wrap(rel - 0.36)));
    c = Math.min(c, rayAt(m, wrap(rel + 0.36)));
    return c;
  }

  function edgeClear(m, worldAngle) {
    let dx = Math.cos(worldAngle);
    let dy = Math.sin(worldAngle);
    let margin = 1.15;
    let t = 10;
    if (dx > 1e-5) t = Math.min(t, (m.sizeX - margin - m.pos.x) / dx);
    else if (dx < -1e-5) t = Math.min(t, (margin - m.pos.x) / dx);
    if (dy > 1e-5) t = Math.min(t, (m.sizeY - margin - m.pos.y) / dy);
    else if (dy < -1e-5) t = Math.min(t, (margin - m.pos.y) / dy);
    return Math.max(0, t);
  }

  function chooseSteer(m, desiredRel, speed) {
    let drel = wrap(desiredRel);
    let direct = corridor(m, drel);
    let bd = edgeClear(m, wrap(m.head + drel));

    if (direct > 0.95 && bd > 1.05) {
      m.avoidSide = 0;
      m.prevSteer = drel;
      return drel;
    }

    if (!m.avoidSide || m.t - (m.avoidStart || -1000) > 8.0) {
