    let offs = [
      0, 0.16, -0.16, 0.32, -0.32, 0.50, -0.50, 0.75, -0.75,
      1.02, -1.02, 1.35, -1.35, 1.80, -1.80, 2.30, -2.30,
      Math.PI, -Math.PI
    ];
    let best = drel;
    let bestCost = 1e100;
