      let c = wrap(drel + off);
      let clr = corridor(m, c);
      let eb = edgeClear(m, wrap(m.head + c));
      let cost = Math.abs(off) * 1.0;

      if (clr < 0.55) cost += 1e7;
      else if (clr < 1.0) cost += (1.0 - clr) * 80;
      else if (clr < 2.0) cost += (2.0 - clr) * 7;

      if (eb < 0.80) cost += 1e7;
      else if (eb < 1.5) cost += (1.5 - eb) * 55;

      if (c * m.avoidSide < -0.12) cost += 1.8;
      cost += Math.abs(wrap(c - prev)) * 0.22;
      if (Math.abs(c) > 1.45) cost += 2.0;

