    va = fin(va, 0);
    let u = fin(st.u, 0);
    let g = fin(st.g, 2.5);
    let dz = fin(st.dz, 0);
    let boost = fin(st.boost, 0);

    if (Math.abs(u) > 0.07 && Math.abs(va) > 0.03 && u * va > 0) {
      let ratio = Math.abs(va / u);
      if (ratio > 0.3 && ratio < 8) g = g * 0.97 + ratio * 0.03;
    }
    g = clamp(g, 0.8, 7.0);
    st.g = g;

    let wantMove = Math.abs(vd) > 0.015;
    let err = vd - va;
    let target;

    if (!wantMove || hold) {
      let slope = Math.sin((pitch || 0) * D2R);
      if (Math.abs(va) > 0.045) {
        target = -sgn(va) * Math.min(0.72, 0.15 + Math.abs(va) * 0.7);
      } else {
        target = clamp(slope * 0.15, -0.18, 0.18);
      }
    } else {
      let dir = sgn(vd);
      let ff = dir * dz + vd / g;
      target = ff + err * 0.50 + dir * boost;

      if (va * vd > 0 && Math.abs(va) > Math.abs(vd) + 0.06) {
        target -= sgn(va) * 0.10;
      }

      if (Math.abs(va) < 0.35 * Math.abs(vd) && Math.abs(u) > 0.03) {
        boost = Math.min(0.25, boost + 0.005);
      } else if (va * vd > 0) {
        boost = Math.max(0, boost * 0.995);
      }

      if (Math.abs(va) < 0.02) {
        dz = Math.min(0.25, dz + 0.002);
      } else if (Math.abs(va) > 0.08) {
        dz = Math.max(0, dz * 0.9995);
      }
    }

    if (Math.abs(va) > 0.80) {
      target = -sgn(va) * Math.min(0.85, 0.30 + Math.abs(va) * 0.50);
    }

    let md = 0.07 + 0.04 * Math.min(1, Math.abs(vd) / 0.45);
    let d = target - u;
    if (d > md) d = md;
    if (d < -md) d = -md;
    u += d;

    let maxU = Math.abs(vd) < 0.02 ? 0.45 : 0.60;
    u = clamp(u, -maxU, maxU);

    if (wantMove && !hold && Math.abs(va) < 0.02 && Math.abs(u) < 0.025) {
      u = sgn(vd) * 0.025;
    }

    st.u = u;
    st.dz = dz;
    st.boost = boost;
    return u;
  }

  function mkWheels(o, m, vl, vr, drill, hold) {
    let uL = wheelCtrl(m.wl, vl, m.vL, m.dt, hold, m.pitch, m.t);
    let uR = wheelCtrl(m.wr, vr, m.vR, m.dt, hold, m.pitch, m.t);

    if (Math.abs(m.vL) > 0.95) uL = -sgn(m.vL) * 0.40;
    if (Math.abs(m.vR) > 0.95) uR = -sgn(m.vR) * 0.40;

    m.cmdL = uL;
    m.cmdR = uR;
    return { left: clamp(uL, -1, 1), right: clamp(uR, -1, 1), drill: !!drill };
  }

  function stopHold(o, m, drill) {
    return mkWheels(o, m, 0, 0, drill, true);
  }

  function drive(o, m, steer, v) {
    steer = wrap(steer);
    let omega = clamp(2.1 * steer, -1.35, 1.35);
    let vv = v;
    let a = Math.abs(steer);

    if (a > 1.10) vv = 0;
    else if (a > 0.55) vv *= (1.10 - a) / 0.55;

    vv = clamp(vv, 0, 0.55);
    let half = omega * WB * 0.5;
    let vl = vv - half;
    let vr = vv + half;

    let mx = Math.max(Math.abs(vl), Math.abs(vr));
    if (mx > 0.55) {
      let f = 0.55 / mx;
      vl *= f;
      vr *= f;
    }
    return mkWheels(o, m, vl, vr, false, false);
  }

  function navRel(o, m, rel, d, speed, stopD) {
    rel = wrap(rel);
    if (d <= stopD) return stopHold(o, m, false);

    let steer = chooseSteer(m, rel, speed);
    let v = speed;

    if (d < stopD + 2.5) {
      v = Math.min(v, Math.max(0.03, (d - stopD) * 0.35 + 0.03));
    }

    let a = Math.abs(steer);
    if (a > 0.95) v = 0;
    else if (a > 0.45) v *= 0.55;

    if (Math.abs(steer) < 0.35) {
      let front = Math.min(rayAt(m, 0), rayAt(m, -0.18), rayAt(m, 0.18));
      if (front < 0.55) v = 0;
      else if (front < 1.0) v = Math.min(v, Math.max(0.03, (front - 0.35) * 0.45));
    }

    if (m.pitch > 20 || m.pitch < -20) v = Math.min(v, 0.22);
    if (m.battery < 0.04) v = 0;

    if (v < 0.025) {
      if (Math.abs(steer) < 0.25) return stopHold(o, m, false);
      return drive(o, m, steer, 0);
    }
    return drive(o, m, steer, v);
  }

  function navTo(o, m, tx, ty, speed, stopD) {
    let dx = tx - m.pos.x;
    let dy = ty - m.pos.y;
    let d = Math.hypot(dx, dy);
    if (d <= stopD) return stopHold(o, m, false);
    let rel = wrap(Math.atan2(dy, dx) - m.head);
    return navRel(o, m, rel, d, speed, stopD);
  }

  function getBase(m, o) {
    if (o && o.beacon) {
      let d = fin(o.beacon.distance, NaN);
      let b = fin(o.beacon.bearing, NaN);
      if (isFinite(d) && isFinite(b) && d < 20) {
        return { d: d, rel: wrap(b * D2R) };
      }
    }
    let dx = m.base.x - m.pos.x;
    let dy = m.base.y - m.pos.y;
    return { d: Math.hypot(dx, dy), rel: wrap(Math.atan2(dy, dx) - m.head) };
  }

  function buildSearchPlan(m, cx, cy) {
    let margin = 1.3;
    let xmin = clamp(cx - 23, margin, m.sizeX - margin);
    let xmax = clamp(cx + 23, margin, m.sizeX - margin);
    if (xmax - xmin < 4) {
      xmin = clamp(cx - 8, margin, m.sizeX - margin);
      xmax = clamp(cx + 8, margin, m.sizeX - margin);
    }

    let rows = [
      clamp(cy, margin, m.sizeY - margin),
      clamp(cy + 15, margin, m.sizeY - margin),
      clamp(cy - 15, margin, m.sizeY - margin)
    ];

    rows.sort(function(a, b) {
      return Math.abs(a - m.pos.y) - Math.abs(b - m.pos.y);
    });

    let plan = [];
    let lastX = m.pos.x;

    for (let ri = 0; ri < rows.length; ri++) {
      let y = rows[ri];
      let a = xmin;
      let b = xmax;
      let start = Math.abs(a - lastX) < Math.abs(b - lastX) ? a : b;
      let end = start === a ? b : a;
      let L = Math.abs(end - start);
      let n = Math.max(1, Math.ceil(L / 11));
      for (let k = 0; k <= n; k++) {
        let x = start + (end - start) * (k / n);
        plan.push({
          x: clamp(x, margin, m.sizeX - margin),
          y: y
        });
      }
      lastX = end;
    }

    let out = [];
    for (let i = 0; i < plan.length; i++) {
      let p = plan[i];
      if (!out.length || dist(out[out.length - 1].x, out[out.length - 1].y, p.x, p.y) > 0.5) {
        out.push(p);
      }
    }
    return out;
  }

  function startHint(m, idx, t) {
    m.activeHint = idx;
    m.hints[idx].state = 1;
    m.state = "goto";
    m.gotoStart = t;
    m.searchPlan = [];
    m.searchIdx = 0;
    m.exploreTarget = null;
    m.prevSteer = 0;
    m.avoidSide = 0;
  }

  function startSearch(m, t, cx, cy) {
    m.state = "search";
    m.searchStart = t;
    m.searchWayT = t;
    m.searchIdx = 0;
    m.searchLimit = m.deliveredSamples === 0 ? 330 : 285;
    m.searchPlan = buildSearchPlan(m, cx, cy);
    m.prevSteer = 0;
    m.avoidSide = 0;
  }

  function abandonHint(m, t) {
    if (m.activeHint >= 0 && m.hints[m.activeHint]) m.hints[m.activeHint].state = 3;
    m.activeHint = -1;
    m.searchPlan = [];
    m.searchIdx = 0;
    m.state = "idle";
  }

  function selectHint(m, t) {
    let best = -1;
    let bestScore = -1e100;
    let first = m.deliveredSamples === 0;

    for (let i = 0; i < m.hints.length; i++) {
      let h = m.hints[i];
      if (h.state !== 0) continue;

      let d = dist(m.pos.x, m.pos.y, h.x, h.y);
      let db = dist(h.x, h.y, m.base.x, m.base.y);
      let travel = d + db;
      let searchTime = first ? 300 : 260;
      let needT = travel / 0.30 + searchTime + 25;
      if (m.timeLeft < needT) continue;

      let needB = travel * m.ePerM * 1.7 + 0.08 + m.carried * 0.02;
      if (m.battery < needB && !m.docked) continue;

      let est = Math.max(0.1, h.est);
      let score;
      if (first) {
        score = 100000 / (d + 30) + est * 0.001;
      } else {
        score = est / Math.pow(d + 0.70 * db + 60, 0.75);
      }
      if (h.est < 0.15) score *= 0.45;

      if (score > bestScore) {
        bestScore = score;
        best = i;
      }
    }

    if (best < 0 && first) {
      let bestD = 1e100;
      for (let i = 0; i < m.hints.length; i++) {
        let h = m.hints[i];
        if (h.state !== 0) continue;
        let d = dist(m.pos.x, m.pos.y, h.x, h.y);
        let db = dist(h.x, h.y, m.base.x, m.base.y);
        if (m.timeLeft < (d + db) / 0.28 + 70) continue;
        if (m.battery < (d + db) * m.ePerM * 1.7 + 0.06) continue;
        if (d < bestD) {
          bestD = d;
          best = i;
        }
      }
    }
    return best;
  }

  function chooseExplore(m, t) {
