      if (p.visited) continue;
      let d = dist(m.pos.x, m.pos.y, p.x, p.y);
      let db = dist(p.x, p.y, m.base.x, m.base.y);
      if (m.timeLeft < (d + db) / 0.28 + 60) continue;
      if (m.battery < (d + db) * m.ePerM * 1.6 + 0.08) continue;
      let score = d + 0.35 * db;
      if (score < bestScore) {
        bestScore = score;
        best = p;
      }
    }
    if (best) {
