  for (let guard = 0; guard < 8; guard++) {
    let st = mem.state;

    if (st === "recover") {
      let r = recoverControl(obs, mem, t);
      if (r) return r;
      continue;
    }

    if (st === "sample") {
      let r = sampleControl(obs, mem, t);
      if (r) return r;
      continue;
    }

    if (st === "return") {
      let r = returnControl(obs, mem, t);
      if (r) return r;
      continue;
    }

    if (st === "charge") {
      let r = chargeControl(obs, mem, t);
      if (r) return r;
      continue;
    }

    if (st === "search") {
      let r = searchControl(obs, mem, t);
      if (r) return r;
      continue;
    }

    if (st === "goto") {
      let r = gotoControl(obs, mem, t);
      if (r) return r;
      continue;
    }

    if (st === "idle") {
      let r = idleControl(obs, mem, t);
