    mem.searchPathLen = 0;

    mem.exploreTarget = null;
    mem.exploreStart = t0;

    mem.sample = null;
    mem.sampleFails = 0;
    mem.ignoreSiteUntil = -1000;
    mem.sampledCount = 0;
    mem.deliveredSamples = 0;
    mem.deliveredCount = 0;
    mem.lastChargeExit = -1000;
    mem.chargeStart = -1000;
    mem.baseWait = 0;

    mem.recover = null;
    mem.recoverCnt = 0;
    mem.lastRecover = -1000;
    mem.avoidDir = 1;
    mem.avoidUntil = -1000;

    mem.stuckT = t0;
    mem.stuckX = mem.px;
    mem.stuckY = mem.py;
    mem.stuckH = mem.head;

    mem.lastCmdL = 0;
    mem.lastCmdR = 0;
    mem.ePerM = 0.001;
    mem.epm = 0.001;
  }

  let t = fin(obs.t, mem.lastT + 0.1);
  let dt = t - mem.lastT;
  if (!isFinite(dt) || dt <= 0) dt = 0.1;
  if (dt > 0.5) dt = 0.5;
  mem.dt = dt;
  mem.lastT = t;
  mem.t = t;

  const timeLeft = fin(obs.timeLeft, Math.max(0, mem.seconds - (t - mem.t0)));
  mem.timeLeft = timeLeft;

  const vL = fin(obs.wheelLeft, mem.vL);
  const vR = fin(obs.wheelRight, mem.vR);
  mem.vL = vL;
  mem.vR = vR;

  const pitch = fin(obs.pitch, mem.pitch);
  mem.pitch = pitch;

  const oldCarried = fin(mem.carried, 0);
  const newCarried = fin(obs.carried, oldCarried);
  const prevBattery = fin(mem.battery, 1);
  const battery = fin(obs.battery, prevBattery);
  const solar = fin(obs.solar, 0);
  const docked = !!obs.docked;
  const bumped = !!obs.bumped;

  mem.prevBattery = prevBattery;
  mem.battery = battery;
  mem.solar = solar;
  mem.docked = docked;
  mem.carriedValue = fin(obs.carriedValue, mem.carriedValue);
  mem.delivered = fin(obs.delivered, mem.delivered);
  mem.drilling = fin(obs.drilling, 0);

  let rr = obs.rays || [];
  for (let i = 0; i < 9; i++) {
    let r = +rr[i];
    if (!isFinite(r) || r < 0) r = 15;
    if (r > 15) r = 15;
    if (r < 0.03) r = 0.03;
    mem.rays[i] = r;
  }

  mem.site = null;
  if (obs.site) {
    const sd = fin(obs.site.distance, NaN);
    const sb = fin(obs.site.bearing, NaN);
    if (isFinite(sd) && isFinite(sb) && sd >= 0) {
      mem.site = { d: sd, b: wrap(sb * D2R), v: fin(obs.site.value, 1) };
    }
  }

  mem.beacon = null;
  if (obs.beacon) {
    const bd = fin(obs.beacon.distance, NaN);
    const bb = fin(obs.beacon.bearing, NaN);
    if (isFinite(bd) && isFinite(bb) && bd >= 0) {
      mem.beacon = { d: bd, b: wrap(bb * D2R) };
    }
  }

  const bumpEdge = bumped && !mem.prevBumped;
  mem.prevBumped = bumped;

  let ds = Math.abs((vL + vR) * 0.5) * dt;
  if (ds > 0.02 && !docked) {
    let used = (prevBattery - battery) + solar * dt;
    if (used > -0.001 && used < 0.08) {
      let inst = used / ds;
      if (inst > 0.00005 && inst < 0.03) {
        mem.ePerM = mem.ePerM * 0.98 + inst * 0.02;
        mem.epm = mem.ePerM;
      }
    }
  }
  mem.ePerM = clamp(mem.ePerM, 0.00012, 0.02);
  mem.epm = mem.ePerM;

  const rawMeas = wrap(fin(obs.heading, mem.head * R2D) * D2R);
  const yawOdo = ((vR - vL) / WB) * dt;
  const raw = wrap(rawMeas - (mem.bias || 0));
  const predHead = wrap(mem.head + yawOdo);
  const hdiff = wrap(raw - predHead);
  const turnRate = Math.abs(yawOdo) / Math.max(dt, 0.01);

  if (Math.abs(hdiff) > 1.15 && turnRate < 1.5) {
    mem.headRej++;
    if (mem.headRej > 12) {
      mem.head = wrap(predHead + hdiff * 0.25);
      mem.headRej = 0;
    } else {
      mem.head = predHead;
    }
  } else {
    const alpha = Math.abs(hdiff) > 0.55 ? 0.35 : 0.62;
    mem.head = wrap(predHead + hdiff * alpha);
    mem.headRej = 0;
  }

  const dh = wrap(mem.head - mem.prevHead);
  const yr = dh / Math.max(dt, 0.01);
  mem.yawRate = mem.yawRate * 0.65 + yr * 0.35;
  mem.prevHead = mem.head;

  const avgSpeed = (vL + vR) * 0.5;
  const hmid = wrap(mem.head - yawOdo * 0.5);
  mem.px += Math.cos(hmid) * avgSpeed * dt;
  mem.py += Math.sin(hmid) * avgSpeed * dt;

  const gx = fin(obs.x, mem.lastRawGpsX);
  const gy = fin(obs.y, mem.lastRawGpsY);
  const fresh = Math.abs(gx - mem.lastRawGpsX) > 0.0005 || Math.abs(gy - mem.lastRawGpsY) > 0.0005;

  if (fresh) {
    const e = dist(gx, gy, mem.px, mem.py);
    let alpha = e < 0.6 ? 0.70 : (e < 3 ? 0.55 : (e < 10 ? 0.35 : 0.18));
    if (mem.gpsStale > 3) alpha = Math.max(alpha, 0.75);
    mem.px += (gx - mem.px) * alpha;
    mem.py += (gy - mem.py) * alpha;
    mem.lastRawGpsX = gx;
    mem.lastRawGpsY = gy;
    mem.gpsStale = 0;
    mem.gpsFresh = true;
  } else {
    mem.gpsStale += dt;
    mem.gpsFresh = false;
  }

  mem.px = clamp(mem.px, 0, mem.sizeX);
  mem.py = clamp(mem.py, 0, mem.sizeY);

  if (mem.gpsFresh) {
    if (!mem.cal) {
      mem.cal = { x: mem.px, y: mem.py, t: t };
    } else if (t - mem.cal.t > 2.0) {
      const dx = mem.px - mem.cal.x;
      const dy = mem.py - mem.cal.y;
      const dd = Math.hypot(dx, dy);
      if (dd > 1.0 && Math.abs(vR - vL) < 0.22 && Math.abs(avgSpeed) > 0.06) {
        const course = Math.atan2(dy, dx);
        const bnew = wrap(rawMeas - course);
        const bd = wrap(bnew - mem.bias);
        if (Math.abs(bd) < 0.9) mem.bias = wrap(mem.bias + bd * 0.22);
      }
      mem.cal = { x: mem.px, y: mem.py, t: t };
    }
  } else if (mem.cal && t - mem.cal.t > 4.0) {
    mem.cal = { x: mem.px, y: mem.py, t: t };
  }

  function wheelCtrl(st, target, meas, hold, pitchAngle) {
    target = clamp(fin(target, 0), -0.62, 0.62);
    meas = fin(meas, 0);

    let uOld = fin(st.u, 0);
    let g = clamp(fin(st.g, 2.5), 0.7, 8.0);

    if (Math.abs(uOld) > 0.08 && Math.abs(meas) > 0.04 && uOld * meas > 0) {
      let ratio = meas / uOld;
      if (ratio > 0.30 && ratio < 8.0) g = clamp(g * 0.995 + ratio * 0.005, 0.7, 8.0);
    }
    st.g = g;

    let out;
    const targetZero = hold || Math.abs(target) < 0.005;

    if (targetZero) {
      let e = -meas;
      st.hi = clamp(fin(st.hi, 0) + e * dt * 2.6, -0.75, 0.75);
      let ff = Math.sin((pitchAngle || 0) * D2R) * 0.18;
      out = st.hi + e * 3.2 + ff;
      st.i *= 0.97;
    } else {
      let e = target - meas;
      st.i = clamp(fin(st.i, 0) + e * dt * 1.4, -0.65, 0.65);
      let ff = target / g;
      out = ff + e * 1.9 + st.i;
      st.hi *= 0.95;

      if (Math.abs(meas) < 0.02) {
        if (target > 0) out = Math.max(out, 0.10);
        else out = Math.min(out, -0.10);
      }
    }

    if (out > 1) {
      if (st.i > 0) st.i *= 0.90;
      if (st.hi > 0) st.hi *= 0.90;
    } else if (out < -1) {
      if (st.i < 0) st.i *= 0.90;
      if (st.hi < 0) st.hi *= 0.90;
    }

    out = clamp(out, -1, 1);

    const maxDelta = 0.40;
    if (out > uOld + maxDelta) out = uOld + maxDelta;
    if (out < uOld - maxDelta) out = uOld - maxDelta;

    st.u = clamp(out, -1, 1);
    return st.u;
  }

  function commandWheels(tl, tr, hold, drill) {
    let uL = wheelCtrl(mem.wL, hold ? 0 : tl, mem.vL, hold, mem.pitch);
    let uR = wheelCtrl(mem.wR, hold ? 0 : tr, mem.vR, hold, mem.pitch);

    if (Math.abs(mem.vL) > 0.82) uL = -sgn(mem.vL);
    if (Math.abs(mem.vR) > 0.82) uR = -sgn(mem.vR);

    mem.lastCmdL = uL;
    mem.lastCmdR = uR;

    return {
      left: clamp(uL, -1, 1),
      right: clamp(uR, -1, 1),
      drill: !!drill
    };
  }

  function stopHold(drill) {
    return commandWheels(0, 0, true, !!drill);
  }

  function driveRaw(v, omega) {
    const maxW = 0.58;
    const half = omega * WB * 0.5;
    let tl = v - half;
    let tr = v + half;
    const m = Math.max(Math.abs(tl), Math.abs(tr));
    if (m > maxW) {
      const f = maxW / m;
      tl *= f;
      tr *= f;
    }
    return commandWheels(tl, tr, false, false);
  }

  function driveRelative(rel, speed) {
    rel = wrap(rel);

    const rA = mem.rays[3];
    const rB = mem.rays[4];
    const rC = mem.rays[5];
    const front = Math.max(Math.min(rA, rB), Math.min(Math.max(rA, rB), rC));

    const leftClear = Math.min(mem.rays[5], mem.rays[6], mem.rays[7]);
    const rightClear = Math.min(mem.rays[1], mem.rays[2], mem.rays[3]);

    if (t < mem.avoidUntil) {
      if (front < 1.3) rel = wrap(rel + mem.avoidDir * 0.75);
    } else if (front < 0.78) {
      const side = leftClear >= rightClear ? 1 : -1;
      mem.avoidDir = side;
      mem.avoidUntil = t + 0.9;
      rel = wrap(rel + side * 0.90);
    }

    let v = clamp(speed, 0, 0.58);

    if (front < 0.25) v = Math.min(v, 0.02);
    else if (front < 0.48) v = Math.min(v, 0.10);
    else if (front < 0.78) v = Math.min(v, 0.22);

    const ar = Math.abs(rel);
    if (ar > 1.95) v = Math.min(v, 0.02);
    else if (ar > 1.25) v = Math.min(v, 0.07);
    else if (ar > 0.72) v = Math.min(v, 0.14);
    else if (ar > 0.42) v = Math.min(v, 0.28);

    if (mem.battery < 0.12) v = Math.min(v, 0.30);

    const edgeMargin = 1.8;
    if (mem.px < edgeMargin || mem.py < edgeMargin ||
        mem.px > mem.sizeX - edgeMargin || mem.py > mem.sizeY - edgeMargin) {
      const inward = Math.atan2(mem.sizeY * 0.5 - mem.py, mem.sizeX * 0.5 - mem.px);
      const er = wrap(inward - mem.head);
      rel = wrap(rel * 0.25 + er * 0.75);
      v = Math.min(v, 0.25);
    }

    let omega = 1.85 * rel - 0.20 * (mem.yawRate || 0);
    omega = clamp(omega, -1.15, 1.15);
    if (Math.abs(rel) < 0.025 && Math.abs(mem.yawRate || 0) < 0.15) omega = 0;

    v = clamp(v, 0, 0.58);
    const half = omega * WB * 0.5;
    let tl = v - half;
    let tr = v + half;

    const maxW = 0.62;
    const m = Math.max(Math.abs(tl), Math.abs(tr));
    if (m > maxW) {
      const f = maxW / m;
      tl *= f;
      tr *= f;
    }

    return commandWheels(tl, tr, false, false);
  }

  function navRel(rel, d, speed, stopD) {
    rel = wrap(rel);
    if (d <= stopD) return stopHold(false);
    let v = speed;
    if (d < stopD + 2.5) {
      v = Math.min(v, Math.max(0.06, (d - stopD) * 0.30 + 0.06));
    }
    return driveRelative(rel, v);
  }

  function navToWorld(tx, ty, speed, stopD) {
    const dx = tx - mem.px;
    const dy = ty - mem.py;
    const d = Math.hypot(dx, dy);
    if (d <= stopD) return stopHold(false);
    const rel = wrap(Math.atan2(dy, dx) - mem.head);
    return navRel(rel, d, speed, stopD);
  }

  function getBaseInfo() {
    if (mem.beacon && mem.beacon.d < 19.8) {
      return { d: mem.beacon.d, rel: mem.beacon.b };
    }
    const dx = mem.base.x - mem.px;
    const dy = mem.base.y - mem.py;
    return {
      d: Math.hypot(dx, dy),
      rel: wrap(Math.atan2(dy, dx) - mem.head)
    };
  }

  function markNearbyHint(x, y) {
    let best = -1;
    let bestD = 1e9;
    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (h.state === 2) continue;
      const d = dist(h.x, h.y, x, y);
      if (d < bestD) {
        bestD = d;
        best = i;
      }
    }
    if (best >= 0 && bestD < 45) mem.hints[best].state = 2;
  }

  if (newCarried > oldCarried + 1e-6) {
    mem.sampledCount += newCarried - oldCarried;
    mem.sampleFails = 0;
    markNearbyHint(mem.px, mem.py);
    if (mem.curHint >= 0 && mem.hints[mem.curHint] && mem.hints[mem.curHint].state !== 2) {
      mem.hints[mem.curHint].state = 2;
    }
    mem.curHint = -1;
    mem.sample = null;
    mem.searchPlan = [];
    mem.mode = "return";
    mem.baseWait = 0;
    mem.ignoreSiteUntil = t + 2.5;
  }

  if (oldCarried > 0 && newCarried < oldCarried - 1e-6 && newCarried === 0) {
    mem.deliveredSamples += oldCarried;
    mem.deliveredCount += oldCarried;
    mem.mode = "charge";
    mem.chargeStart = t;
    mem.curHint = -1;
    mem.sample = null;
    mem.searchPlan = [];
    mem.baseWait = 0;
    mem.ignoreSiteUntil = t + 1.0;
  }

  mem.carried = newCarried;

  function startRecovery(tn, reason) {
    if (mem.mode === "recover" || mem.mode === "sample" || mem.mode === "charge") return;
    mem.recoverCnt = (mem.recoverCnt || 0) + 1;
    mem.recover = {
      start: tn,
      prev: mem.mode,
      prevHint: mem.curHint,
      side: (mem.recoverCnt % 2) ? 1 : -1,
      reason: reason || ""
    };
    mem.mode = "recover";
    mem.lastRecover = tn;
    mem.avoidDir = mem.recover.side;
    mem.avoidUntil = tn + 2.5;
    mem.searchWayT = tn;
  }

  if (bumpEdge && mem.mode !== "sample" && mem.mode !== "charge" &&
      mem.mode !== "recover" && t > (mem.lastRecover || -1000) + 1.8) {
    const bi = getBaseInfo();
    if (!(mem.carried > 0 && bi.d < 5.0)) startRecovery(t, "bump");
  }

  if (mem.mode !== "sample" && mem.mode !== "charge" && mem.mode !== "recover" &&
      t - (mem.stuckT || 0) > 2.4) {
    const moved = dist(mem.px, mem.py, mem.stuckX, mem.stuckY);
    const turned = Math.abs(wrap(mem.head - mem.stuckH));
    const eff = moved + 0.45 * Math.min(turned, 1.1);
    const cmd = Math.abs(mem.lastCmdL || 0) + Math.abs(mem.lastCmdR || 0);
    if (cmd > 0.22 && eff < 0.11 && t > (mem.lastRecover || -1000) + 2.5) {
      startRecovery(t, "stuck");
    }
    mem.stuckT = t;
    mem.stuckX = mem.px;
    mem.stuckY = mem.py;
    mem.stuckH = mem.head;
  }

  function handleRecovery(tn) {
    const r = mem.recover;
    if (!r) {
      mem.mode = "idle";
      return null;
    }

    const age = tn - r.start;
    if (age < 1.35) {
      return driveRaw(-0.28, 0);
    }
    if (age < 2.15) {
      return driveRaw(-0.04, r.side * 1.05);
    }
    if (age < 3.00) {
      return driveRaw(0.18, -r.side * 0.55);
    }

    let prev = r.prev || "idle";
    mem.curHint = r.prevHint;
    mem.recover = null;
    mem.avoidDir = r.side;
    mem.avoidUntil = tn + 1.5;

    if (mem.carried > 0) mem.mode = "return";
    else if (prev === "search" && mem.curHint >= 0 && mem.hints[mem.curHint] &&
             mem.hints[mem.curHint].state === 1) mem.mode = "search";
    else if (prev === "toHint" && mem.curHint >= 0 && mem.hints[mem.curHint] &&
             mem.hints[mem.curHint].state === 1) mem.mode = "toHint";
    else if (prev === "explore" && mem.exploreTarget) mem.mode = "explore";
    else mem.mode = "idle";

    return null;
  }

  function startSample(tn) {
    if (!mem.site) return false;
    const s = mem.site;
    const wa = wrap(mem.head + s.b);
    mem.sample = {
      phase: "approach",
      start: tn,
      phaseStart: tn,
      lastSeen: tn,
      lastD: s.d,
      lastB: s.b,
      val: s.v,
      lastWorld: {
        x: mem.px + Math.cos(wa) * s.d,
        y: mem.py + Math.sin(wa) * s.d
      },
      prevMode: mem.mode,
      prevHint: mem.curHint,
      drillStart: -1000
    };
    mem.mode = "sample";
    mem.baseWait = 0;
    return true;
  }

  function abortSample(tn) {
    mem.sampleFails = (mem.sampleFails || 0) + 1;
    const s = mem.sample;
    const prev = s ? s.prevMode : "idle";
    const prevHint = s ? s.prevHint : mem.curHint;

    mem.ignoreSiteUntil = tn + (mem.sampleFails >= 2 ? 35 : 12);
    mem.sample = null;

    if (mem.sampleFails >= 2) {
      if (mem.curHint >= 0 && mem.hints[mem.curHint]) {
        mem.hints[mem.curHint].attempts = (mem.hints[mem.curHint].attempts || 0) + 1;
        mem.hints[mem.curHint].state = 3;
      }
      mem.curHint = -1;
      mem.searchPlan = [];
      mem.mode = "idle";
      return;
    }

    if (prevHint >= 0) mem.curHint = prevHint;

    if (prev === "search" && mem.curHint >= 0 && mem.hints[mem.curHint] &&
        mem.hints[mem.curHint].state === 1) mem.mode = "search";
    else if (prev === "toHint" && mem.curHint >= 0 && mem.hints[mem.curHint] &&
             mem.hints[mem.curHint].state === 1) mem.mode = "toHint";
    else if (prev === "explore" && mem.exploreTarget) mem.mode = "explore";
    else mem.mode = "idle";
  }

  function handleSample(tn) {
    const s = mem.sample;
    if (!s) {
      mem.mode = "idle";
      return null;
    }

    if (mem.site) {
      s.lastD = mem.site.d;
      s.lastB = mem.site.b;
      s.val = mem.site.v;
      s.lastSeen = tn;
      const wa = wrap(mem.head + mem.site.b);
      s.lastWorld = {
        x: mem.px + Math.cos(wa) * mem.site.d,
        y: mem.py + Math.sin(wa) * mem.site.d
      };
    }

    let d = s.lastD;
    let rel = s.lastB;

    if (!mem.site && s.lastWorld) {
      const dx = s.lastWorld.x - mem.px;
      const dy = s.lastWorld.y - mem.py;
      d = Math.hypot(dx, dy);
      rel = wrap(Math.atan2(dy, dx) - mem.head);
    }

    if (!mem.site && tn - s.lastSeen > 4.0 && s.phase !== "drill") {
      abortSample(tn);
      return null;
    }

    if (s.phase === "approach") {
      if (tn - s.start > 65.0) {
        abortSample(tn);
        return null;
      }

      if (d <= 1.35) {
        s.phase = "settle";
        s.phaseStart = tn;
        return stopHold(false);
      }

      let sp = d > 4.0 ? 0.30 : (d > 2.0 ? 0.18 : 0.10);
      if (mem.battery < 0.10) sp = Math.min(sp, 0.12);
      return navRel(rel, d, sp, 0.8);
    }

    if (s.phase === "settle") {
      const spd = Math.max(Math.abs(mem.vL), Math.abs(mem.vR));
      if (spd < 0.12 || tn - s.phaseStart > 1.6) {
        if (d <= 1.58) {
          s.phase = "drill";
          s.drillStart = tn;
        } else {
          s.phase = "approach";
        }
      }
      return stopHold(false);
    }

    if (s.phase === "drill") {
      if (tn - s.drillStart > 10.0) {
        abortSample(tn);
        return null;
      }
      return stopHold(true);
    }

    abortSample(tn);
    return null;
  }

  function buildSearchPlan(cx, cy, radius, spacing) {
    const margin = 1.2;
    let x0 = clamp(cx - radius, margin, mem.sizeX - margin);
    let x1 = clamp(cx + radius, margin, mem.sizeX - margin);
    let y0 = clamp(cy - radius, margin, mem.sizeY - margin);
    let y1 = clamp(cy + radius, margin, mem.sizeY - margin);

    if (x1 - x0 < 2.0) {
      x0 = clamp(cx - 6, margin, mem.sizeX - margin);
      x1 = clamp(cx + 6, margin, mem.sizeX - margin);
    }
    if (y1 - y0 < 2.0) {
      y0 = clamp(cy - 6, margin, mem.sizeY - margin);
      y1 = clamp(cy + 6, margin, mem.sizeY - margin);
    }

    const n = Math.max(1, Math.ceil((y1 - y0) / spacing));
    const ys = [];
    for (let i = 0; i <= n; i++) {
      ys.push(y0 + (y1 - y0) * (i / n));
    }

    const remaining = ys.slice();
    const plan = [];
    let curX = mem.px;
    let curY = mem.py;

    while (remaining.length) {
      let bestI = 0;
      let bestScore = 1e100;
      for (let i = 0; i < remaining.length; i++) {
        const y = remaining[i];
        const score = Math.abs(y - curY) + 0.02 * Math.abs((x0 + x1) * 0.5 - curX);
        if (score < bestScore) {
          bestScore = score;
          bestI = i;
        }
      }

      const y = remaining.splice(bestI, 1)[0];
      let pA = { x: x0, y: y };
      let pB = { x: x1, y: y };
      let entry = pA;
      let exit = pB;
      const dA = dist(curX, curY, pA.x, pA.y);
      const dB = dist(curX, curY, pB.x, pB.y);
      if (dB < dA) {
        entry = pB;
        exit = pA;
      }

      plan.push(entry);
      plan.push(exit);
      curX = exit.x;
      curY = exit.y;
    }

    const out = [];
    for (let i = 0; i < plan.length; i++) {
      const p = plan[i];
      if (!out.length || dist(out[out.length - 1].x, out[out.length - 1].y, p.x, p.y) > 0.4) {
        out.push(p);
      }
    }

    let len = 0;
    let lx = mem.px;
    let ly = mem.py;
    for (let i = 0; i < out.length; i++) {
      len += dist(lx, ly, out[i].x, out[i].y);
      lx = out[i].x;
      ly = out[i].y;
    }

    mem.searchPlan = out;
    mem.searchIdx = 0;
    mem.searchPathLen = len;
    mem.searchStart = t;
    mem.searchWayT = t;
    mem.searchLimit = Math.min(470, Math.max(170, len / 0.32 + 45));
  }

  function startSearch(tn) {
    if (mem.curHint < 0 || !mem.hints[mem.curHint]) {
      mem.mode = "idle";
      return;
    }
    const h = mem.hints[mem.curHint];
    const attempt = h.attempts || 0;
    const radius = attempt > 0 ? 24 : 16;
    const spacing = attempt > 0 ? 9 : 8;
    buildSearchPlan(h.x, h.y, radius, spacing);
    mem.mode = "search";
    mem.searchStart = tn;
    mem.searchWayT = tn;
  }

  function failSearch(tn) {
    if (mem.curHint >= 0 && mem.hints[mem.curHint]) {
      const h = mem.hints[mem.curHint];
      h.attempts = (h.attempts || 0) + 1;
      h.state = 3;
    }
    mem.curHint = -1;
    mem.searchPlan = [];
    mem.searchIdx = 0;
    mem.mode = "idle";
  }

  function handleToHint(tn) {
    if (mem.curHint < 0 || !mem.hints[mem.curHint]) {
      mem.mode = "idle";
      return null;
    }
    const h = mem.hints[mem.curHint];
    if (h.state !== 1) {
      mem.curHint = -1;
      mem.mode = "idle";
      return null;
    }

    const d = dist(mem.px, mem.py, h.x, h.y);
    if (d < 4.0 || (tn - (mem.hintStart || tn) > 140 && d < 18)) {
      startSearch(tn);
      return null;
    }

    if (tn - (mem.hintStart || tn) > 220 && d >= 18) {
      h.attempts = (h.attempts || 0) + 1;
      h.state = 3;
      mem.curHint = -1;
      mem.mode = "idle";
      return null;
    }

    return navToWorld(h.x, h.y, 0.58, 1.0);
  }

  function handleSearch(tn) {
    if (mem.curHint < 0 || !mem.hints[mem.curHint]) {
      mem.mode = "idle";
      return null;
    }
    const h = mem.hints[mem.curHint];
    if (h.state !== 1) {
      mem.curHint = -1;
      mem.mode = "idle";
      return null;
    }

    if (tn - mem.searchStart > mem.searchLimit) {
      failSearch(tn);
      return null;
    }

    if (mem.searchIdx >= mem.searchPlan.length) {
      failSearch(tn);
      return null;
    }

    let guard = 0;
    while (mem.searchIdx < mem.searchPlan.length && guard++ < 6) {
      const p = mem.searchPlan[mem.searchIdx];
      if (dist(mem.px, mem.py, p.x, p.y) < 0.95) {
        mem.searchIdx++;
        mem.searchWayT = tn;
      } else {
        break;
      }
    }

    if (mem.searchIdx >= mem.searchPlan.length) {
      failSearch(tn);
      return null;
    }

    if (tn - mem.searchWayT > 32.0) {
      mem.searchIdx++;
      mem.searchWayT = tn;
      if (mem.searchIdx >= mem.searchPlan.length) {
        failSearch(tn);
        return null;
      }
      return null;
    }

    const p = mem.searchPlan[mem.searchIdx];
    return navToWorld(p.x, p.y, 0.55, 0.7);
  }

  function handleReturn(tn) {
    const info = getBaseInfo();
    const carrying = mem.carried > 0;
    const stopD = carrying ? 1.15 : 1.9;

    if (info.d <= stopD) {
      if (carrying) {
        mem.baseWait += dt;
        if (mem.baseWait > 3.0 && info.d > 0.35) {
          return navRel(info.rel, info.d, 0.10, 0.18);
        }
        return stopHold(false);
      }

      mem.baseWait = 0;
      if (mem.battery < 0.92 && mem.timeLeft > 85) {
        mem.mode = "charge";
        mem.chargeStart = tn;
        return null;
      }
      mem.mode = "idle";
      return null;
    }

    mem.baseWait = 0;

    let speed = carrying ? 0.52 : 0.48;
    if (info.d < 5.0) speed = Math.min(speed, 0.22);
    if (mem.battery < 0.15) speed = Math.min(speed, 0.28);

    return navRel(info.rel, info.d, speed, stopD);
  }

  function handleCharge(tn) {
    if (mem.carried > 0) {
      mem.mode = "return";
      return null;
    }

    const info = getBaseInfo();
    if (info.d > 3.2) {
      mem.mode = "return";
      return null;
    }

    if (!mem.docked && info.d > 0.35) {
      let sp = info.d > 1.2 ? 0.12 : 0.07;
      return navRel(info.rel, info.d, sp, 0.12);
    }

    const waited = tn - (mem.chargeStart || tn);
    if (mem.battery > 0.93 || waited > 50.0 || mem.timeLeft < 75) {
      mem.lastChargeExit = tn;
      mem.mode = "idle";
      mem.baseWait = 0;
      return null;
    }

    return stopHold(false);
  }

  function chooseHint(tn) {
    let best = -1;
    let bestScore = 1e100;
    const first = mem.deliveredCount === 0 && mem.sampledCount === 0;

    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (h.state !== 0) continue;

      const d = dist(mem.px, mem.py, h.x, h.y);
      const db = dist(h.x, h.y, mem.base.x, mem.base.y);
      const est = Math.max(0.2, h.est);

      const searchNeed = first ? 230 : 210;
      const needT = (d + db) / 0.38 + searchNeed + 30;
      if (mem.timeLeft < needT) continue;

      const needB = (d + db) * mem.ePerM * 1.9 + 0.06;
      if (mem.battery < needB && !mem.docked) continue;

      let score;
      if (first) {
        score = d + 0.15 * db - Math.min(5.0, est) * 0.8;
      } else {
        score = (d + 0.70 * db + 25) / (est + 0.4);
      }

      if (score < bestScore) {
        bestScore = score;
        best = i;
      }
    }

    if (best >= 0) return best;

    let bestD = 1e100;
    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (h.state !== 0) continue;
      const d = dist(mem.px, mem.py, h.x, h.y);
      const db = dist(h.x, h.y, mem.base.x, mem.base.y);
      if (mem.timeLeft < (d + db) / 0.40 + 55) continue;
      const needB = (d + db) * mem.ePerM * 1.7 + 0.05;
      if (mem.battery < needB && !mem.docked) continue;
      if (d < bestD) {
        bestD = d;
        best = i;
      }
    }

    return best;
  }

  function chooseRetry(tn) {
    let best = -1;
    let bestScore = 1e100;

    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (h.state !== 3) continue;
      if ((h.attempts || 0) >= 2) continue;

      const d = dist(mem.px, mem.py, h.x, h.y);
      const db = dist(h.x, h.y, mem.base.x, mem.base.y);
      if (mem.timeLeft < (d + db) / 0.38 + 170) continue;
      const needB = (d + db) * mem.ePerM * 1.9 + 0.06;
      if (mem.battery < needB && !mem.docked) continue;

      const score = d + 0.65 * db - Math.min(6.0, h.est) * 0.4;
      if (score < bestScore) {
        bestScore = score;
        best = i;
      }
    }

    return best;
  }

  function chooseExplore(tn) {
    let best = null;
    let bestScore = 1e100;

    for (let i = 0; i < mem.explore.length; i++) {
      const p = mem.explore[i];
      if (p.seen) continue;

      const d = dist(mem.px, mem.py, p.x, p.y);
      const db = dist(p.x, p.y, mem.base.x, mem.base.y);
      if (mem.timeLeft < (d + db) / 0.35 + 55) continue;
      const needB = (d + db) * mem.ePerM * 1.7 + 0.06;
      if (mem.battery < needB && !mem.docked) continue;

      const score = d + 0.35 * db;
      if (score < bestScore) {
        bestScore = score;
        best = p;
      }
    }

    return best;
  }

  function handleExplore(tn) {
    if (!mem.exploreTarget) {
      mem.mode = "idle";
      return null;
    }

    const p = mem.exploreTarget;
    const d = dist(mem.px, mem.py, p.x, p.y);

    if (d < 2.0 || tn - mem.exploreStart > 170) {
      p.seen = true;
      mem.exploreTarget = null;
      mem.mode = "idle";
      return null;
    }

    return navToWorld(p.x, p.y, 0.50, 0.9);
  }

  function idleStep(tn) {
    if (mem.carried > 0) {
      mem.mode = "return";
      return null;
    }

    const base = getBaseInfo();

    if (mem.battery < 0.20 && base.d > 3.0) {
      mem.mode = "return";
      return null;
    }

    if (base.d < 3.2 && mem.battery < 0.90 && mem.timeLeft > 120 &&
        tn - (mem.lastChargeExit || -1000) > 35) {
      mem.mode = "charge";
      mem.chargeStart = tn;
      return null;
    }

    if (mem.timeLeft < 22) {
      return stopHold(false);
    }

    const idx = chooseHint(tn);
    if (idx >= 0) {
      const h = mem.hints[idx];
      h.state = 1;
      h.startT = tn;
      mem.curHint = idx;
      mem.hintStart = tn;
      mem.searchPlan = [];
      mem.searchIdx = 0;
      mem.mode = "toHint";
      return null;
    }

    const ridx = chooseRetry(tn);
    if (ridx >= 0) {
      const h = mem.hints[ridx];
      h.state = 1;
      h.startT = tn;
      mem.curHint = ridx;
      mem.hintStart = tn;
      mem.searchPlan = [];
      mem.searchIdx = 0;
      mem.mode = "toHint";
      return null;
    }

    const ep = chooseExplore(tn);
    if (ep) {
      ep.seen = true;
      mem.exploreTarget = { x: ep.x, y: ep.y };
      mem.exploreStart = tn;
      mem.mode = "explore";
      return null;
    }

    return stopHold(false);
  }

  if (mem.carried > 0 &&
      mem.mode !== "sample" && mem.mode !== "return" &&
      mem.mode !== "recover" && mem.mode !== "charge") {
    mem.mode = "return";
  }

  if (mem.mode !== "return" && mem.mode !== "recover" &&
      mem.mode !== "sample" && mem.mode !== "charge" &&
      mem.battery < 0.12) {
    const bi = getBaseInfo();
    if (bi.d > 3.0) mem.mode = "return";
  }

  if (mem.site && mem.mode !== "return" && mem.mode !== "charge" &&
      mem.mode !== "sample" && mem.mode !== "recover" &&
      mem.carried < mem.cap && mem.battery > 0.075 &&
      t >= (mem.ignoreSiteUntil || -1000)) {
    const bi = getBaseInfo();
    const enoughTime = mem.timeLeft > bi.d / 0.38 + 17.0;
    if (enoughTime) startSample(t);
  }

  for (let guard = 0; guard < 10; guard++) {
    if (mem.mode === "recover") {
      const r = handleRecovery(t);
      if (r) return r;
      continue;
    }

    if (mem.mode === "sample") {
      const r = handleSample(t);
      if (r) return r;
      continue;
    }

    if (mem.mode === "return") {
      const r = handleReturn(t);
      if (r) return r;
      continue;
    }

    if (mem.mode === "charge") {
      const r = handleCharge(t);
      if (r) return r;
      continue;
    }

    if (mem.mode === "toHint") {
      const r = handleToHint(t);
      if (r) return r;
      continue;
    }

    if (mem.mode === "search") {
      const r = handleSearch(t);
      if (r) return r;
      continue;
    }

    if (mem.mode === "explore") {
      const r = handleExplore(t);
      if (r) return r;
      continue;
    }

    if (mem.mode === "idle") {
      const r = idleStep(t);
      if (r) return r;
      if (mem.mode === "idle") break;
      continue;
    }

    mem.mode = "idle";
  }

  return stopHold(false);
}

function act(obs, mem) {
  const R = Math.PI / 180;
  const clamp = (v, a, b) => (v < a ? a : v > b ? b : v);
  const wrap = (a) => { while (a > 180) a -= 360; while (a < -180) a += 360; return a; };
  const dist = (ax, ay, bx, by) => Math.hypot(ax - bx, ay - by);
  const stop = () => ({ left: 0, right: 0, drill: false });
  const num = (v, d) => (typeof v === 'number' && isFinite(v) ? v : d);

  const t = num(obs.t, 0);
  const x = num(obs.x, 0), y = num(obs.y, 0);
  const hdRaw = num(obs.heading, 0);
  const battery = num(obs.battery, 1);
  const timeLeft = num(obs.timeLeft, 1200);
  const carried = num(obs.carried, 0);
  const wl = num(obs.wheelLeft, 0), wr = num(obs.wheelRight, 0);
  const drilling = num(obs.drilling, 0);

  if (!mem.init) {
    mem.init = true;
    const m = obs.mission || {};
    mem.base = m.base ? { x: num(m.base.x, 0), y: num(m.base.y, 0) } : { x: 0, y: 0 };
    mem.cap = num(m.capacity, 5);
    mem.hints = (m.hints || []).map(h => ({
      x: num(h.x, 0), y: num(h.y, 0), est: num(h.estimate, 1), done: false, fail: false
    }));
    mem.hOff = 0; mem.hOffSet = false;
    mem.trail = []; mem.done = [];
    mem.mode = 'go'; mem.tgt = null; mem.tgtStart = t;
    mem.search = null; mem.sample = null;
    mem.hi = 0; mem.rec = null; mem.lastRecEnd = -10; mem.lastFwd = 0;
    mem.charge = false; mem.noCharge = false;
    mem.dockT = 0; mem.ignoreRet = -1; mem.rnd = 7;
  }

  const bx = mem.base.x, by = mem.base.y;
  const cap = mem.cap;
  const rnd = () => { mem.rnd += 1; const v = Math.sin(mem.rnd * 12.9898) * 43758.5453; return v - Math.floor(v); };

  // ---- trail and heading estimate (compass corrected by GPS track) ----
  mem.trail.push({ x, y });
  if (mem.trail.length > 60) mem.trail.shift();
  const tr = mem.trail;
  if (tr.length >= 30 && !obs.bumped) {
    const a = tr[tr.length - 30];
    const dx = x - a.x, dy = y - a.y;
    if (Math.hypot(dx, dy) > 2 && wl > 0.25 && wr > 0.25 && Math.abs(wl - wr) < 0.2) {
      const diff = wrap(Math.atan2(dy, dx) / R - hdRaw);
      if (!mem.hOffSet) { mem.hOff = diff; mem.hOffSet = true; }
      else mem.hOff = wrap(mem.hOff + 0.05 * wrap(diff - mem.hOff));
    }
  }
  const hd = wrap(hdRaw + mem.hOff);

  // ---- range readings ----
  const rays = Array.isArray(obs.rays) ? obs.rays : [];
  const rr = (i) => num(rays[i], 15);
  const leftC = (rr(5) + rr(6) + rr(7) + rr(8)) / 4;
  const rightC = (rr(0) + rr(1) + rr(2) + rr(3)) / 4;
  const front = Math.min(rr(3), rr(4), rr(5));

  // ---- helpers ----
  const driveOut = (tx, ty, vmax, arrive) => {
    const dx = tx - x, dy = ty - y;
    const d = Math.hypot(dx, dy);
    if (d < arrive) { mem.lastFwd = 0; return stop(); }
    let e = wrap(Math.atan2(dy, dx) / R - hd);
    let speed = vmax;
    if (front < 5) speed *= clamp((front - 1) / 4, 0.2, 1);
    if (front < 4) {
      const k = clamp((4 - front) / 2.5, 0, 1);
      e += k * (leftC > rightC ? 40 : -40);
    }
    let fwd = Math.abs(e) > 45 ? 0 : speed * Math.cos(e * R);
    if (front < 1.5) fwd = 0;
    fwd = Math.min(fwd, 0.15 + 0.3 * d);
    if (fwd > 0.02 && fwd < 0.2 && speed >= 0.2) fwd = 0.2;
    fwd = Math.max(0, fwd);
    let turn = clamp(0.03 * e, -0.9, 0.9);
    if (Math.abs(e) > 8 && Math.abs(turn) < 0.25) turn = 0.25 * (turn < 0 ? -1 : 1);
    mem.lastFwd = fwd;
    return { left: clamp(fwd - turn, -1, 1), right: clamp(fwd + turn, -1, 1), drill: false };
  };

  const holdCtl = (hx, hy, hH) => {
    const dx = x - hx, dy = y - hy;
    const ux = Math.cos(hH * R), uy = Math.sin(hH * R);
    const dF = dx * ux + dy * uy;
    const v = (wl + wr) / 2;
    mem.hi = clamp(mem.hi - 0.02 * dF, -0.35, 0.35);
    const u = clamp(mem.hi - 0.3 * dF - 1.0 * v, -0.4, 0.4);
    const tu = clamp(-0.02 * wrap(hH - hd), -0.3, 0.3);
    return { left: clamp(u - tu, -1, 1), right: clamp(u + tu, -1, 1) };
  };

  const markDone = (px, py) => {
    mem.done.push({ x: px, y: py });
    for (const h of mem.hints) if (dist(h.x, h.y, px, py) < 20) h.done = true;
  };
  const nearDone = (px, py) => mem.done.some(p => dist(p.x, p.y, px, py) < 3);

  const pickHint = () => {
    let best = null, bs = -1;
    for (const h of mem.hints) {
      if (h.done || h.fail) continue;
      const d = dist(x, y, h.x, h.y), dB = dist(h.x, h.y, bx, by);
      if ((d + dB) / 0.6 > timeLeft - 40) continue;
      const s = h.est / (d + 0.5 * dB + 25);
      if (s > bs) { bs = s; best = h; }
    }
    return best;
  };

  const pickExplore = () => {
    let px = x, py = y;
    for (let k = 0; k < 20; k++) {
      const a = rnd() * 360 * R, d = 40 + rnd() * 80;
      const cx = x + d * Math.cos(a), cy = y + d * Math.sin(a);
      px = clamp(cx, 25, 375); py = clamp(cy, 25, 375);
      if (cx > 25 && cx < 375 && cy > 25 && cy < 375) break;
    }
    mem.tgt = { x: px, y: py, kind: 'explore' };
    mem.tgtStart = t;
  };

  // ---- recovery from bumps and stuck states ----
  if (!mem.rec) {
    let trig = 0;
    if (obs.bumped && t - mem.lastRecEnd > 1) trig = 1.5;
    else if (tr.length >= 50 && mem.lastFwd > 0.25 && t - mem.lastRecEnd > 3) {
      const old = tr[tr.length - 50];
      if (dist(x, y, old.x, old.y) < 0.4) trig = 2.0;
    }
    if (trig > 0) mem.rec = { phase: 'back', until: t + trig, side: 1 };
  }
  if (mem.rec && t >= mem.rec.until) {
    if (mem.rec.phase === 'back') mem.rec = { phase: 'turn', until: t + 1.0, side: leftC > rightC ? 1 : -1 };
    else { mem.rec = null; mem.lastRecEnd = t; }
  }
  if (mem.rec) {
    mem.lastFwd = 0;
    if (mem.rec.phase === 'back') return { left: -0.45, right: -0.45, drill: false };
    return { left: -0.5 * mem.rec.side, right: 0.5 * mem.rec.side, drill: false };
  }

  // ---- energy flags ----
  if (battery < 0.2) mem.charge = true;
  if (battery > 0.6) { mem.charge = false; mem.noCharge = false; }

  // ---- sampling in progress ----
  if (mem.mode === 'sample' && mem.sample) {
    const s = mem.sample;
    if (drilling >= 6.0) {
      markDone(s.sx, s.sy);
      mem.mode = 'go'; mem.sample = null; mem.tgt = null; mem.lastFwd = 0;
      return stop();
    }
    if (t - s.t0 > 60) {
      markDone(s.sx, s.sy);
      mem.mode = 'go'; mem.sample = null; mem.tgt = null; mem.lastFwd = 0;
      return stop();
    }
    const c = holdCtl(s.hx, s.hy, s.hH);
    return { left: c.left, right: c.right, drill: true };
  }
  mem.mode = 'go';

  // ---- return decision ----
  const dBase = dist(x, y, bx, by);
  let needRet = false;
  if (carried >= cap) needRet = true;
  if (carried > 0 && (timeLeft < dBase / 0.6 + 70 || battery < 0.25)) needRet = true;
  if (mem.charge && !mem.noCharge) needRet = true;
  if (mem.ignoreRet > t && carried < cap) needRet = false;

  // ---- target selection when not returning ----
  if (!needRet) {
    if (mem.tgt && mem.tgt.kind === 'hint' && mem.tgt.ref.done) mem.tgt = null;
    if (!mem.tgt) {
      const h = pickHint();
      if (h) { mem.tgt = { x: h.x, y: h.y, kind: 'hint', ref: h }; mem.tgtStart = t; mem.search = null; }
      else if (carried > 0) needRet = true;
      else pickExplore();
    }
  }

  // ---- docking / charging at base ----
  if (needRet && dBase < 2.5) {
    mem.dockT++;
    const finished = carried === 0 && (!mem.charge || battery > 0.6);
    if (!finished && mem.dockT < 250) { mem.mode = 'deliver'; mem.lastFwd = 0; return stop(); }
    if (carried > 0) mem.ignoreRet = t + 30;
    if (mem.charge && battery <= 0.6) mem.noCharge = true;
    mem.dockT = 0; mem.tgt = null; mem.search = null;
    needRet = false;
  }
  if (!needRet && dBase >= 2.5) mem.dockT = 0;

  if (needRet) {
    mem.mode = 'deliver'; mem.search = null;
    return driveOut(bx, by, 0.5, 1.5);
  }

  // ---- opportunistic sampling of any visible site ----
  const s = obs.site;
  if (s && carried < cap) {
    const sd = num(s.distance, 99);
    const sb = num(s.bearing, 0);
    const sx = x + sd * Math.cos((hd + sb) * R);
    const sy = y + sd * Math.sin((hd + sb) * R);
    if (!nearDone(sx, sy)) {
      if (sd < 1.3) {
        mem.mode = 'sample';
        mem.sample = { sx, sy, hx: x, hy: y, hH: hd, t0: t };
        mem.hi = 0;
        const c = holdCtl(x, y, hd);
