      mem.mode = 'deliver'; mem.goal = null; mem.search = null; mem.dockT = null;
    }
  }
  if (mem.mode === 'deliver') {
    if (dEff < 2.2) {
      if (mem.dockT === null) mem.dockT = t;
      const waited = t - mem.dockT;
      if ((carried === 0 && (battery > 0.5 || waited > 25)) || waited > 45) {
        mem.mode = 'go'; mem.dockT = null;
      } else {
        if (carried > 0 && waited > 8 && dEff > 1.0) return navAvoid(mem.bx, mem.by, 0.12);
        return setWheels(0, 0);
      }
    } else {
      mem.dockT = null;
      if (carried === 0 && battery > 0.5) mem.mode = 'go';
      else return navAvoid(mem.bx, mem.by, 0.6);
    }
  }

  // ---- local search at a goal ----
  if (mem.search) return searchStep();

  // ---- goal selection and navigation ----
  if (!mem.goal) mem.goal = pickGoal();
  const g = mem.goal;
  if (t - g.t0 > g.tmax || mem.goalBumps >= 6) {
    if (g.h) g.h.st = 2;
    mem.goal = null;
    return setWheels(0, 0);
  }
  if (dist(mem.px, mem.py, g.x, g.y) < 3) {
    mem.goal = null;
    mem.search = {
      cx: g.x, cy: g.y, h: g.h, phase: 'scan', lastH: null, h0: 0, ang: 0, bins: null,
      cyc: 0, rings: 0, pts: [], pi: 0, t0: t, start: t, H: 0, sx: 0, sy: 0,
    };
    return setWheels(0, 0);
  }
  return navAvoid(g.x, g.y, 0.7);
}

function act(obs, mem) {
  const D = Math.PI / 180;
  const C = 5, NG = 80;
  const clamp = (v, a, b) => (v < a ? a : v > b ? b : v);
  const wrapD = (a) => ((((a + 180) % 360) + 360) % 360) - 180;
  const num = (v, d) => (typeof v === 'number' && isFinite(v) ? v : d);
  const hyp = (a, b) => Math.hypot(a, b);

  const t = num(obs.t, 0);
  const gx = num(obs.x, 0);
  const gy = num(obs.y, 0);
  const hdRaw = num(obs.heading, 0);
  const battery = num(obs.battery, 1);
  const timeLeft = num(obs.timeLeft, 1200);
  const carried = num(obs.carried, 0);
  const wl = num(obs.wheelLeft, 0);
  const wr = num(obs.wheelRight, 0);
  const drilling = num(obs.drilling, 0);
  const science = num(obs.science, 0);
  const rays = Array.isArray(obs.rays) ? obs.rays : [];
  const rayv = (i) => clamp(num(rays[i], 15), 0, 15);
  const bumped = !!obs.bumped;
  const site = obs.site && typeof obs.site.distance === 'number' ? obs.site : null;
  const beacon = obs.beacon && typeof obs.beacon.distance === 'number' ? obs.beacon : null;
  const vAvg = (wl + wr) / 2;

  if (!mem.init) {
    mem.init = true;
    const m = obs.mission || {};
    const b = m.base || {};
    mem.bx = num(b.x, gx);
    mem.by = num(b.y, gy);
    mem.cap = Math.max(1, num(m.capacity, 5));
    mem.hints = (Array.isArray(m.hints) ? m.hints : []).map((h) => ({
      x: num(h.x, 0), y: num(h.y, 0), est: Math.max(0.1, num(h.estimate, 1)), st: 0,
    }));
    mem.px = gx; mem.py = gy; mem.lgx = gx; mem.lgy = gy;
    mem.lastT = t - 0.1;
    mem.hOff = 0; mem.hOffSet = false; mem.anc = null;
    mem.GL = 2.5; mem.GR = 2.5;
    mem.lastCmd = { l: 0, r: 0 }; mem.lastW = 0;
    mem.occ = new Array(NG * NG).fill(0);
    mem.occT = new Array(NG * NG).fill(-10);
    mem.samples = []; mem.failed = []; mem.visits = [];
    mem.lastVisit = { x: gx, y: gy };
    mem.mode = 'hunt'; mem.goal = null; mem.search = null; mem.drill = null;
    mem.path = []; mem.pathGoal = null; mem.pathT = -100; mem.replan = false;
    mem.rec = null; mem.recT = -100; mem.stk = null;
    mem.dockT = null; mem.holdU = 0; mem.siteC = null;
    mem.lastSciT = -100; mem.spinT = null;
  }

  const cap = mem.cap;
  const dt = clamp(t - mem.lastT, 0.01, 0.5);
  mem.lastT = t;

  // ---------- position: dead reckoning + GPS blend ----------
  const hd0 = wrapD(hdRaw + mem.hOff);
  mem.px += vAvg * dt * Math.cos(hd0 * D);
  mem.py += vAvg * dt * Math.sin(hd0 * D);
  const fresh = gx !== mem.lgx || gy !== mem.lgy;
  if (fresh) {
    mem.lgx = gx; mem.lgy = gy;
    const jump = hyp(gx - mem.px, gy - mem.py);
    const k = jump > 6 ? 1 : 0.5;
    mem.px += k * (gx - mem.px);
    mem.py += k * (gy - mem.py);
    // compass offset from GPS course on straight runs
    const bad = bumped || Math.abs(mem.lastW) > 0.3 || Math.abs(wl - wr) > 0.25 || vAvg < 0.12 || !!mem.rec;
    if (bad) mem.anc = null;
    else if (!mem.anc) mem.anc = { x: gx, y: gy, h: hdRaw };
    else {
      const a = mem.anc;
      const dh = Math.abs(wrapD(hdRaw - a.h));
      const dA = hyp(gx - a.x, gy - a.y);
      if (dh > 20) mem.anc = { x: gx, y: gy, h: hdRaw };
      else if (dA >= 10) {
        const course = Math.atan2(gy - a.y, gx - a.x) / D;
        const mObs = wrapD(course - hdRaw);
        if (!mem.hOffSet) { mem.hOff = mObs; mem.hOffSet = true; }
        else mem.hOff = wrapD(mem.hOff + 0.3 * wrapD(mObs - mem.hOff));
        mem.anc = { x: gx, y: gy, h: hdRaw };
      }
    }
  }
  const hd = wrapD(hdRaw + mem.hOff);

  // ---------- motor gain learning ----------
  {
    const cl = mem.lastCmd.l, cr = mem.lastCmd.r;
    if (!bumped && Math.abs(cl) > 0.25 && Math.sign(cl) === Math.sign(wl) && Math.abs(wl) > 0.05 && Math.abs(wl) < 4)
      mem.GL = clamp(0.97 * mem.GL + 0.03 * clamp(Math.abs(wl) / Math.abs(cl), 0.8, 5), 0.8, 5);
    if (!bumped && Math.abs(cr) > 0.25 && Math.sign(cr) === Math.sign(wr) && Math.abs(wr) > 0.05 && Math.abs(wr) < 4)
      mem.GR = clamp(0.97 * mem.GR + 0.03 * clamp(Math.abs(wr) / Math.abs(cr), 0.8, 5), 0.8, 5);
  }

  // ---------- visits (for exploration) ----------
  if (hyp(mem.px - mem.lastVisit.x, mem.py - mem.lastVisit.y) > 12) {
    mem.visits.push({ x: mem.px, y: mem.py });
    mem.lastVisit = { x: mem.px, y: mem.py };
    if (mem.visits.length > 300) mem.visits.shift();
  }

  // ---------- occupancy grid from rays ----------
  const cellOf = (x, y) => {
    const i = clamp(Math.floor(x / C), 0, NG - 1);
    const j = clamp(Math.floor(y / C), 0, NG - 1);
    return j * NG + i;
  };
  const blocked = (c) => mem.occ[c] >= 2;
  const allSame = rays.length > 0 && rays.every((v) => num(v, -1) === num(rays[0], -1));
  if (!allSame) {
    for (let i = 0; i < 9; i++) {
      const r = num(rays[i], 15);
      const th = (hd + (i - 4) * 20) * D;
      const rr = clamp(r, 0, 15);
      if (rr > 0.3 && rr < 14.3) {
        const c = cellOf(mem.px + rr * Math.cos(th), mem.py + rr * Math.sin(th));
        if (t - mem.occT[c] > 1.5) { mem.occ[c] += 1; mem.occT[c] = t; }
      }
      const lim = Math.min(rr, 14.3) - 1.0;
      for (let s = 2.5; s < lim; s += 2.5) {
        const c = cellOf(mem.px + s * Math.cos(th), mem.py + s * Math.sin(th));
        if (mem.occ[c] === 1) mem.occ[c] = 0;
      }
    }
  }

  const leftSum = rayv(5) + rayv(6) + rayv(7) + rayv(8);
  const rightSum = rayv(0) + rayv(1) + rayv(2) + rayv(3);
  const sideSign = leftSum >= rightSum ? 1 : -1;
  const front = Math.min(rayv(3), rayv(4), rayv(5));

  // ---------- helpers ----------
  const setW = (v, w) => {
    const vl = v - 0.3 * w, vr = v + 0.3 * w;
    const f = (vv, G) => {
      let c = clamp(vv / G, -1, 1);
      if (Math.abs(vv) > 0.03 && Math.abs(c) < 0.12) c = vv < 0 ? -0.12 : 0.12;
      return c;
    };
    const cl = f(vl, mem.GL), cr = f(vr, mem.GR);
    mem.lastCmd = { l: cl, r: cr };
    mem.lastW = w;
    return { left: cl, right: cr, drill: false };
  };

  const avoid = () => {
    let s = 0;
    for (let i = 0; i < 9; i++) {
      const r = rayv(i);
      if (r < 4.5) s += -Math.sin((i - 4) * 20 * D) * (4.5 - r) / 4.5;
    }
    if (front < 4.5) s += sideSign * (4.5 - front) / 4.5 * 0.6;
    return clamp(s, -1.2, 1.2);
  };

  const plan = (sx, sy, tx, ty) => {
    const s = cellOf(sx, sy), g = cellOf(tx, ty);
    if (s === g) return [{ x: tx, y: ty }];
    const N = NG * NG;
    const gS = new Float64Array(N).fill(1e9);
    const came = new Int32Array(N).fill(-1);
    const closed = new Uint8Array(N);
    const gi = g % NG, gj = (g - gi) / NG;
    const heur = (c) => {
      const i = c % NG, j = (c - i) / NG;
      const dx = Math.abs(i - gi), dy = Math.abs(j - gj);
      return Math.max(dx, dy) + 0.414 * Math.min(dx, dy);
    };
    const nearOcc = (c) => {
      const i = c % NG, j = (c - i) / NG;
      for (let a = -1; a <= 1; a++) {
        for (let b = -1; b <= 1; b++) {
          const x = i + a, y = j + b;
          if (x < 0 || y < 0 || x >= NG || y >= NG) return true;
          if (mem.occ[y * NG + x] >= 2) return true;
        }
      }
      return false;
    };
    const hk = [], hv = [];
    const hpush = (k, v) => {
      hk.push(k); hv.push(v);
      let i = hk.length - 1;
      while (i > 0) {
        const p = (i - 1) >> 1;
        if (hk[p] <= hk[i]) break;
        const tk = hk[p]; hk[p] = hk[i]; hk[i] = tk;
        const tv = hv[p]; hv[p] = hv[i]; hv[i] = tv;
        i = p;
      }
    };
    const hpop = () => {
      const top = hv[0];
      const lk = hk.pop(), lv = hv.pop();
      if (hk.length > 0) {
        hk[0] = lk; hv[0] = lv;
        let i = 0;
        const n = hk.length;
        for (;;) {
          const l = 2 * i + 1, r = l + 1;
          let m = i;
          if (l < n && hk[l] < hk[m]) m = l;
          if (r < n && hk[r] < hk[m]) m = r;
          if (m === i) break;
          const tk = hk[m]; hk[m] = hk[i]; hk[i] = tk;
          const tv = hv[m]; hv[m] = hv[i]; hv[i] = tv;
          i = m;
        }
      }
      return top;
    };
    gS[s] = 0;
    hpush(heur(s), s);
    let found = false, it = 0;
    while (hk.length > 0 && it < 9000) {
      it++;
      const c = hpop();
      if (closed[c]) continue;
      closed[c] = 1;
      if (c === g) { found = true; break; }
      const ci = c % NG, cj = (c - ci) / NG;
      for (let di = -1; di <= 1; di++) {
        for (let dj = -1; dj <= 1; dj++) {
          if (di === 0 && dj === 0) continue;
          const ni = ci + di, nj = cj + dj;
          if (ni < 0 || nj < 0 || ni >= NG || nj >= NG) continue;
          const n = nj * NG + ni;
          if (closed[n]) continue;
          if (n !== g && blocked(n)) continue;
          const diag = di !== 0 && dj !== 0;
          if (diag && (blocked(cj * NG + ni) || blocked(nj * NG + ci))) continue;
          const cost = (diag ? 1.414 : 1) + (nearOcc(n) ? 1.2 : 0);
          const ng = gS[c] + cost;
          if (ng < gS[n]) {
            gS[n] = ng; came[n] = c;
            hpush(ng + heur(n), n);
          }
        }
      }
    }
    if (!found) return [{ x: tx, y: ty }];
    const out = [];
    let c = g;
    while (c !== -1 && c !== s) {
      const i = c % NG, j = (c - i) / NG;
      out.push({ x: i * C + C / 2, y: j * C + C / 2 });
      c = came[c];
    }
    out.reverse();
    out[out.length - 1] = { x: tx, y: ty };
    return out;
  };

  const ensurePath = (tx, ty) => {
    const pg = mem.pathGoal;
    let need = !pg || mem.path.length === 0 || hyp(pg.x - tx, pg.y - ty) > 3 || t - mem.pathT > 5 || mem.replan;
    if (!need && t - mem.pathT > 1 && mem.path.length > 0 && blocked(cellOf(mem.path[0].x, mem.path[0].y))) need = true;
    if (need) {
      mem.path = plan(mem.px, mem.py, tx, ty);
      mem.pathGoal = { x: tx, y: ty };
      mem.pathT = t;
      mem.replan = false;
    }
    while (mem.path.length > 1) {
      const d0 = hyp(mem.path[0].x - mem.px, mem.path[0].y - mem.py);
      const d1 = hyp(mem.path[1].x - mem.px, mem.path[1].y - mem.py);
      if (d0 < 2.5 || d1 < d0) mem.path.shift();
      else break;
    }
    return mem.path[0];
  };

  const drive = (tx, ty, vmax) => {
    const dT = hyp(tx - mem.px, ty - mem.py);
    if (dT < 0.3) return setW(0, 0);
    const wp = ensurePath(tx, ty);
    const eGoal = wrapD(Math.atan2(wp.y - mem.py, wp.x - mem.px) / D - hd) * D;
    const e = eGoal + avoid();
    const w = clamp(1.3 * e, -1, 1);
    let v = vmax * clamp(1.6 * Math.cos(e), 0, 1);
    if (Math.abs(e) > 1.1) {
      v = 0;
      if (mem.spinT === null) mem.spinT = t;
      if (t - mem.spinT > 6) v = 0.15;
    } else mem.spinT = null;
    v *= clamp((front - 0.8) / 4.5, 0.15, 1);
    v = Math.min(v, 0.25 + 0.4 * dT);
    if (v > 0 && v < 0.1) v = 0.1;
    return setW(v, w);
  };

  const ringPts = (cx, cy, r, n, off) => {
    const out = [];
    for (let k = 0; k < n; k++) {
      const a = (off + (360 * k) / n) * D;
      out.push({ x: clamp(cx + r * Math.cos(a), 3, 397), y: clamp(cy + r * Math.sin(a), 3, 397) });
    }
    return out;
  };

  const startSearch = (cx, cy, h) => {
    mem.search = { cx, cy, h, stage: 1, pts: ringPts(cx, cy, 6, 6, 0), i: 0, t0: t, start: t, sciMax: 0 };
  };
  const endSearch = () => {
    const s = mem.search;
    if (s && s.h && s.h.st === 0) s.h.st = 2;
    mem.search = null; mem.goal = null; mem.path = [];
    return setW(0, 0);
  };
  const searchStep = () => {
    const s = mem.search;
    if (science > s.sciMax) s.sciMax = science;
    if (s.h && s.h.st !== 0) { mem.search = null; mem.goal = null; return null; }
    if (t - s.start > 170) return endSearch();
    if (s.i >= s.pts.length) {
      if (s.stage === 1 && s.sciMax > 0.25) {
        s.stage = 2; s.pts = ringPts(s.cx, s.cy, 12, 8, 22.5); s.i = 0; s.t0 = t;
      } else {
        return endSearch();
      }
    }
    const p = s.pts[s.i];
    if (hyp(p.x - mem.px, p.y - mem.py) < 2 || t - s.t0 > 25) { s.i++; s.t0 = t; return setW(0, 0); }
    return drive(p.x, p.y, 0.6);
  };

  const pickHint = () => {
    let best = null, bs = -1;
    for (const h of mem.hints) {
      if (h.st !== 0) continue;
      if (mem.failed.some((p) => hyp(p.x - h.x, p.y - h.y) < 4)) continue;
      const d = hyp(h.x - mem.px, h.y - mem.py), db = hyp(h.x - mem.bx, h.y - mem.by);
      if ((d + db) / 0.5 + 30 > timeLeft) continue;
      const s = h.est / (d + db + 40);
      if (s > bs) { bs = s; best = h; }
    }
    return best;
  };

  const pickExplore = () => {
    let best = { x: mem.px, y: mem.py }, bs = -1e9;
    for (let k = 0; k < 10; k++) {
      const a = Math.random() * 2 * Math.PI, d = 40 + Math.random() * 60;
      const x = clamp(mem.px + d * Math.cos(a), 8, 392);
      const y = clamp(mem.py + d * Math.sin(a), 8, 392);
      let mz = 150;
      for (const v of mem.visits) {
        const dd = hyp(v.x - x, v.y - y);
        if (dd < mz) mz = dd;
      }
      const sc = Math.min(mz, 120) - 0.15 * hyp(x - mem.bx, y - mem.by);
      if (sc > bs) { bs = sc; best = { x, y }; }
    }
    return best;
  };

  const startDrill = (x, y) => {
    mem.drill = { x, y, t0: t };
    mem.holdU = 0; mem.goal = null; mem.search = null; mem.path = [];
  };
  const drillStep = () => {
    const d = mem.drill;
    if (drilling >= 6.0) {
      mem.samples.push({ x: d.x, y: d.y });
      for (const h of mem.hints) if (hyp(h.x - d.x, h.y - d.y) < 12) h.st = 1;
      mem.drill = null; mem.search = null; mem.goal = null; mem.path = [];
      return setW(0, 0);
    }
    if (t - d.t0 > 30) {
      mem.failed.push({ x: d.x, y: d.y });
      mem.drill = null; mem.goal = null; mem.path = [];
      return setW(0, 0);
    }
    mem.holdU = clamp(mem.holdU - 1.0 * vAvg * dt, -0.4, 0.4);
    mem.lastCmd = { l: mem.holdU, r: mem.holdU };
    return { left: mem.holdU, right: mem.holdU, drill: true };
  };

  const startRec = () => {
    mem.rec = { ph: 0, t0: t, side: sideSign };
    mem.replan = true; mem.stk = null;
  };
  const recStep = () => {
    const rc = mem.rec;
    if (rc.ph === 0 && t - rc.t0 >= 1.0) { rc.ph = 1; rc.t0 = t; }
    if (rc.ph === 1 && t - rc.t0 >= 1.0) { mem.rec = null; mem.recT = t; return setW(0, 0); }
    return rc.ph === 0 ? setW(-0.3, 0) : setW(0, 0.9 * rc.side);
  };
  const markAhead = (dd) => {
    const c = cellOf(mem.px + dd * Math.cos(hd * D), mem.py + dd * Math.sin(hd * D));
    mem.occ[c] = Math.max(mem.occ[c], 2);
    mem.occT[c] = t;
  };

  // ================= main flow =================

  // 1. recovery manoeuvre
  if (mem.rec) return recStep();

  // 2. bump and stuck detection
  if (!mem.drill && bumped && t - mem.recT > 1.5) {
    markAhead(0.9);
    startRec();
    return recStep();
  }
  const cmdSp = (mem.lastCmd.l + mem.lastCmd.r) / 2;
  if (!mem.drill && cmdSp > 0.2) {
    if (!mem.stk || hyp(mem.px - mem.stk.x, mem.py - mem.stk.y) > 0.5) mem.stk = { x: mem.px, y: mem.py, t };
    else if (t - mem.stk.t > 6) { startRec(); return recStep(); }
  } else {
    mem.stk = null;
  }

  // 3. drilling in progress
  if (mem.drill) return drillStep();

  // 4. energy / delivery mode
  const dBase = hyp(mem.bx - mem.px, mem.by - mem.py);
  const dNear = beacon ? Math.min(dBase, beacon.distance) : dBase;
  if (mem.mode === 'hunt') {
    if ((carried > 0 && (carried >= cap || timeLeft < dBase / 0.5 + 60)) || battery < 0.2) {
      mem.mode = 'home'; mem.goal = null; mem.search = null; mem.path = []; mem.dockT = null;
    }
  }
  if (mem.mode === 'home') {
    if (dNear < 2.2) {
      if (mem.dockT === null) mem.dockT = t;
      const wt = t - mem.dockT;
      if ((carried === 0 && (battery > 0.5 || wt > 12)) || wt > 40) {
        mem.mode = 'hunt'; mem.dockT = null; mem.goal = null; mem.path = [];
      } else {
        return setW(0, 0);
      }
    } else {
      mem.dockT = null;
      return drive(mem.bx, mem.by, 0.8);
    }
  }

  // 5. visible site: approach and sample
  if (site && mem.mode === 'hunt' && carried < cap) {
    const sd = site.distance;
    const sb = num(site.bearing, 0) * D;
    const sx = mem.px + sd * Math.cos(hd * D + sb);
    const sy = mem.py + sd * Math.sin(hd * D + sb);
    const known = mem.samples.some((p) => hyp(p.x - sx, p.y - sy) < 4.5) ||
      mem.failed.some((p) => hyp(p.x - sx, p.y - sy) < 4.5);
    if (!known) {
      if (!mem.siteC || hyp(mem.siteC.x - sx, mem.siteC.y - sy) > 5) mem.siteC = { x: sx, y: sy, t0: t };
      if (t - mem.siteC.t0 > 40) {
        mem.failed.push({ x: sx, y: sy });
        mem.siteC = null;
      } else if (sd <= 1.3) {
        if (Math.abs(vAvg) < 0.15) { startDrill(sx, sy); return drillStep(); }
        return setW(0, 0);
      } else {
        const e = sb;
        if (Math.abs(e) > 1.2) return setW(0, clamp(1.5 * e, -0.8, 0.8));
        let v = clamp(0.12 + 0.2 * sd, 0.12, 0.45) * clamp(1.5 * Math.cos(e), 0, 1);
        v *= clamp((front - 0.5) / 3, 0.3, 1);
        const w = clamp(1.5 * e + avoid(), -0.8, 0.8);
        return setW(Math.max(v, 0.1), w);
      }
    }
  }

  // 6. initial straight run to calibrate the compass offset from GPS course
