      for (const v of mem.visits) {
        const dd = hyp(v.x - x, v.y - y);
        if (dd < mz) mz = dd;
      }
      const sc = Math.min(mz, 120) - 0.15 * hyp(x - mem.bx, y - mem.by);
      if (sc > bs) { bs = sc; best = { x, y }; }
    }
    return best;
  };

  // ---------- drilling ----------
  const startDrill = (x, y) => {
    mem.drill = { x, y, t0: t };
    mem.holdU = 0; mem.goal = null; mem.search = null; mem.path = [];
  };
  const drillStep = () => {
    const d = mem.drill;
    if (drilling >= 6.0) {
      mem.samples.push({ x: d.x, y: d.y });
      for (const h of mem.hints) if (hyp(h.x - d.x, h.y - d.y) < 10) h.st = 1;
      mem.drill = null; mem.search = null; mem.goal = null; mem.path = [];
      return setW(0, 0);
    }
    if (t - d.t0 > 30) {
      mem.failed.push({ x: d.x, y: d.y });
      mem.drill = null; mem.goal = null; mem.path = [];
      return setW(0, 0);
    }
    mem.holdU = clamp(mem.holdU - 1.0 * vAvg * dt, -0.4, 0.4);
    mem.lastCmd = { l: mem.holdU, r: mem.holdU };
    return { left: mem.holdU, right: mem.holdU, drill: true };
  };

  // ---------- recovery ----------
  const startRec = () => {
    mem.rec = { ph: 0, t0: t, side: sideSign };
    mem.replan = true; mem.stk = null;
  };
  const recStep = () => {
    const rc = mem.rec;
    if (rc.ph === 0 && t - rc.t0 >= 1.0) { rc.ph = 1; rc.t0 = t; }
    if (rc.ph === 1 && t - rc.t0 >= 1.0) { mem.rec = null; mem.recT = t; return setW(0, 0); }
    return rc.ph === 0 ? setW(-0.3, 0) : setW(0, 0.9 * rc.side);
  };
  const markAhead = (dd) => {
    const c = cellOf(mem.px + dd * Math.cos(hd * D), mem.py + dd * Math.sin(hd * D));
    mem.occ[c] = Math.max(mem.occ[c], 2);
    mem.occT[c] = t;
  };

  // ================= main flow =================

  // 1. recovery manoeuvre
  if (mem.rec) return recStep();

  // 2. bump and stuck detection
  if (!mem.drill && bumped && t - mem.recT > 1.5) {
    markAhead(0.9);
    startRec();
    return recStep();
  }
  const cmdSp = (mem.lastCmd.l + mem.lastCmd.r) / 2;
  if (!mem.drill && cmdSp > 0.2) {
    if (!mem.stk || hyp(mem.px - mem.stk.x, mem.py - mem.stk.y) > 0.5) mem.stk = { x: mem.px, y: mem.py, t };
    else if (t - mem.stk.t > 6) { startRec(); return recStep(); }
  } else {
    mem.stk = null;
  }

  // 3. drilling in progress
  if (mem.drill) return drillStep();

  // 4. energy / delivery mode
  const dBase = hyp(mem.bx - mem.px, mem.by - mem.py);
  const dNear = beacon ? Math.min(dBase, beacon.distance) : dBase;
  if (mem.mode === 'hunt') {
    if ((carried > 0 && (carried >= cap || timeLeft < dBase / 0.5 + 60)) || battery < 0.2) {
      mem.mode = 'home'; mem.goal = null; mem.search = null; mem.path = []; mem.dockT = null;
    }
  }
  if (mem.mode === 'home') {
    if (dNear < 2.2) {
      if (mem.dockT === null) mem.dockT = t;
      const wt = t - mem.dockT;
      if ((carried === 0 && (battery > 0.5 || wt > 12)) || wt > 40) {
        mem.mode = 'hunt'; mem.dockT = null; mem.goal = null; mem.path = [];
      } else {
        return setW(0, 0);
      }
    } else {
      mem.dockT = null;
      return drive(mem.bx, mem.by, 0.8);
    }
  }

  // 5. visible site: approach and sample (bearing is relative to heading, so no map needed)
  if (site && mem.mode === 'hunt' && carried < cap) {
    const sd = site.distance;
    const sb = num(site.bearing, 0) * D;
    const sx = mem.px + sd * Math.cos(hd * D + sb);
    const sy = mem.py + sd * Math.sin(hd * D + sb);
    const known = mem.samples.some((p) => hyp(p.x - sx, p.y - sy) < 4.5) ||
      mem.failed.some((p) => hyp(p.x - sx, p.y - sy) < 4.5);
    if (!known) {
      if (!mem.siteC || hyp(mem.siteC.x - sx, mem.siteC.y - sy) > 5) mem.siteC = { x: sx, y: sy, t0: t };
      if (t - mem.siteC.t0 > 40) {
        mem.failed.push({ x: sx, y: sy });
        mem.siteC = null;
      } else if (sd <= 1.3) {
