    mem.goal = null; mem.search = null; mem.drill = null; mem.app = null;
    mem.rec = null; mem.recT = -100; mem.stk = null; mem.spinT = null;
    mem.holdU = 0; mem.lastSearchT = -100;
  }

  const cap = mem.cap;
  const dt = clamp(t - mem.lastT, 0.01, 0.5);
  mem.lastT = t;

  // ---------- compass jump guard ----------
  const jumpH = Math.abs(wrapD(hdRaw - mem.prevHd)) > 25 && dt < 0.3;
  mem.prevHd = hdRaw;

  // ---------- dead reckoning ----------
  const hd0R = wrapD(hdRaw + mem.hOff) * D;
  const ds = vAvg * dt;
  mem.px += ds * Math.cos(hd0R);
  mem.py += ds * Math.sin(hd0R);
  mem.acX += ds * Math.cos(hdRaw * D);
  mem.acY += ds * Math.sin(hdRaw * D);
  mem.acLen += Math.abs(ds);
  if (jumpH) { mem.acX = 0; mem.acY = 0; mem.acLen = 0; mem.ax = gx; mem.ay = gy; }

  // ---------- GPS fusion and compass offset ----------
  const fresh = gx !== mem.lgx || gy !== mem.lgy;
  if (fresh) {
    mem.lgx = gx; mem.lgy = gy;
    const jump = hyp(gx - mem.px, gy - mem.py);
    const k = jump > 6 ? 1 : 0.4;
    mem.px += k * (gx - mem.px);
    mem.py += k * (gy - mem.py);
    const dAnc = hyp(gx - mem.ax, gy - mem.ay);
    const netDR = hyp(mem.acX, mem.acY);
    if (!jumpH && dAnc > 8 && netDR > 8 && dAnc / netDR > 0.6 && dAnc / netDR < 1.6) {
      const gpsDir = Math.atan2(gy - mem.ay, gx - mem.ax) / D;
      const cmpDir = Math.atan2(mem.acY, mem.acX) / D;
      const mObs = wrapD(gpsDir - cmpDir);
      if (!mem.hOffSet) { mem.hOff = mObs; mem.hOffSet = true; }
      else mem.hOff = wrapD(mem.hOff + 0.3 * wrapD(mObs - mem.hOff));
      mem.ax = gx; mem.ay = gy; mem.acX = 0; mem.acY = 0; mem.acLen = 0;
    } else if (dAnc > 25 || mem.acLen > 150) {
      mem.ax = gx; mem.ay = gy; mem.acX = 0; mem.acY = 0; mem.acLen = 0;
    }
  }
  const hd = wrapD(hdRaw + mem.hOff);
  const hdR = hd * D;

  // ---------- motor gain learning ----------
  {
    const cl = mem.lastCmd.l, cr = mem.lastCmd.r;
    if (!bumped && Math.abs(cl) > 0.2) {
      mem.sL = 0.98 * mem.sL + Math.abs(wl);
      mem.cL = 0.98 * mem.cL + Math.abs(cl);
      if (mem.cL > 0.5) mem.GL = clamp(mem.sL / mem.cL, 1, 4);
    }
    if (!bumped && Math.abs(cr) > 0.2) {
      mem.sR = 0.98 * mem.sR + Math.abs(wr);
      mem.cR = 0.98 * mem.cR + Math.abs(cr);
      if (mem.cR > 0.5) mem.GR = clamp(mem.sR / mem.cR, 1, 4);
    }
  }

  // ---------- visits ----------
  if (hyp(mem.px - mem.lvx, mem.py - mem.lvy) > 12) {
    mem.visits.push({ x: mem.px, y: mem.py });
    mem.lvx = mem.px; mem.lvy = mem.py;
    if (mem.visits.length > 150) mem.visits.shift();
  }

  const front = Math.min(rayv(3), rayv(4), rayv(5));
  const leftS = rayv(5) + rayv(6) + rayv(7) + rayv(8);
  const rightS = rayv(0) + rayv(1) + rayv(2) + rayv(3);
  const sideSign = leftS >= rightS ? 1 : -1;

  // ---------- helpers ----------
  const setW = (v, w) => {
    const vl = v - 0.3 * w, vr = v + 0.3 * w;
    const f = (vv, G) => {
      let c = clamp(vv / G, -1, 1);
      if (Math.abs(vv) > 0.04 && Math.abs(c) < 0.1) c = vv < 0 ? -0.1 : 0.1;
      return c;
    };
    const cl = f(vl, mem.GL), cr = f(vr, mem.GR);
    mem.lastCmd = { l: cl, r: cr };
    return { left: cl, right: cr, drill: false };
  };

  const avoidR = () => {
    let s = 0;
    for (let i = 0; i < 9; i++) {
      const r = rayv(i);
      if (r < 4) s += -Math.sin((i - 4) * 20 * D) * (4 - r) / 4;
    }
    if (front < 3) s += sideSign * (3 - front) / 3 * 0.9;
    return clamp(s, -1.2, 1.2);
  };

  const driveTo = (tx, ty, vmax) => {
    const dx = tx - mem.px, dy = ty - mem.py;
    const dT = hyp(dx, dy);
    const eg = wrapR(Math.atan2(dy, dx) - hdR);
    const e = clamp(eg + (raysOK ? avoidR() : 0), -3, 3);
    const w = clamp(1.4 * e, -1, 1);
    let v = 0;
    if (Math.abs(e) > 1.0) {
      if (mem.spinT === null) mem.spinT = t;
      v = t - mem.spinT > 8 ? 0.15 : 0;
    } else {
      mem.spinT = null;
      v = vmax * clamp(Math.cos(e), 0, 1);
      if (raysOK) v *= clamp((front - 0.7) / 3, 0.2, 1);
      v = Math.min(v, 0.2 + 0.5 * dT);
      if (v > 0 && v < 0.15) v = 0.15;
    }
    return setW(v, w);
  };

  // steer by sensor relative bearing (positive = left)
  const approachRel = (sd, sb, vmax) => {
    const w = clamp(1.6 * sb, -1, 1);
    let v = 0;
    if (Math.abs(sb) < 0.9) v = vmax * clamp(Math.cos(sb), 0, 1) * clamp(sd / 2, 0.3, 1);
    if (v > 0 && v < 0.15) v = 0.15;
    if (front < 1.2) v = Math.min(v, 0.15);
    return setW(v, w);
  };

  const ringPts = (cx, cy, r, n, off) => {
    const out = [];
    for (let k = 0; k < n; k++) {
      const a = (off + (360 * k) / n) * D;
      out.push({ x: clamp(cx + r * Math.cos(a), 3, 397), y: clamp(cy + r * Math.sin(a), 3, 397) });
    }
    return out;
  };

  const startSearch = (cx, cy, h, R) => {
    mem.search = {
      cx, cy, h, R, iter: 0,
      pts: ringPts(cx, cy, R, 6, Math.random() * 60),
      i: 0, pt0: t, start: t, checked: false,
      best: { x: mem.px, y: mem.py, s: -1 },
    };
  };

  const endSearch = () => {
    const s = mem.search;
    if (s) {
      if (s.h && s.h.st === 0) s.h.st = 2;
      mem.searched.push({ x: s.cx, y: s.cy });
      if (mem.searched.length > 40) mem.searched.shift();
    }
    mem.search = null; mem.goal = null; mem.lastSearchT = t;
    return setW(0, 0);
  };

  const searchStep = () => {
    const s = mem.search;
    if (science > s.best.s) s.best = { x: mem.px, y: mem.py, s: science };
    if (s.h && s.h.st !== 0) { mem.search = null; mem.goal = null; return setW(0, 0); }
    if (!s.checked && t - s.start > 10) {
      s.checked = true;
      if (s.best.s < 0.02) return endSearch();
    }
    if (t - s.start > 110) return endSearch();
    if (s.i >= s.pts.length) {
      const moved = hyp(s.best.x - s.cx, s.best.y - s.cy);
      if (s.best.s > 0.05 && s.iter < 2 && moved > 2) {
        s.iter++;
        s.cx = s.best.x; s.cy = s.best.y;
        s.R = Math.max(3, s.R * 0.6);
        s.pts = ringPts(s.cx, s.cy, s.R, 6, Math.random() * 60);
        s.i = 0; s.pt0 = t;
        s.best = { x: s.cx, y: s.cy, s: -1 };
      } else {
        return endSearch();
      }
    }
    const p = s.pts[s.i];
    if (hyp(p.x - mem.px, p.y - mem.py) < 1.5 || t - s.pt0 > 25) {
      s.i++; s.pt0 = t;
      return setW(0, 0);
    }
    return driveTo(p.x, p.y, 0.4);
  };

  const pickHint = () => {
    let best = null, bs = -1;
    for (const h of mem.hints) {
      if (h.st !== 0) continue;
      if (mem.failed.some((p) => hyp(p.x - h.x, p.y - h.y) < 5)) continue;
      if (mem.samples.some((p) => hyp(p.x - h.x, p.y - h.y) < 8)) continue;
      const d = hyp(h.x - mem.px, h.y - mem.py), db = hyp(h.x - mem.bx, h.y - mem.by);
      if ((d + db) / 0.3 + 60 > timeLeft) continue;
      const s = h.est / (d + db + 40);
      if (s > bs) { bs = s; best = h; }
    }
    return best;
  };

  const pickExplore = () => {
    let best = { x: mem.px, y: mem.py }, bs = -1e9;
    for (let k = 0; k < 10; k++) {
      const a = Math.random() * 2 * Math.PI, d = 30 + Math.random() * 50;
      const x = clamp(mem.px + d * Math.cos(a), 8, 392);
      const y = clamp(mem.py + d * Math.sin(a), 8, 392);
      let mz = 150;
      for (const v of mem.visits) {
        const dd = hyp(v.x - x, v.y - y);
        if (dd < mz) mz = dd;
      }
      const sc = Math.min(mz, 100) - 0.05 * hyp(x - mem.bx, y - mem.by);
      if (sc > bs) { bs = sc; best = { x, y }; }
    }
    return best;
  };

  const startDrill = (x, y) => {
    mem.drill = { x, y, t0: t };
    mem.holdU = 0; mem.goal = null; mem.search = null; mem.app = null;
  };

  const drillStep = () => {
    const d = mem.drill;
    if (drilling >= 6.0) {
      mem.samples.push({ x: d.x, y: d.y });
      for (const h of mem.hints) if (hyp(h.x - d.x, h.y - d.y) < 15) h.st = 1;
      mem.drill = null; mem.search = null; mem.goal = null; mem.app = null;
      mem.holdU = 0; mem.lastCmd = { l: 0, r: 0 };
      return { left: 0, right: 0, drill: false };
    }
    if (t - d.t0 > 45) {
      mem.failed.push({ x: d.x, y: d.y });
      mem.drill = null; mem.app = null; mem.goal = null;
      mem.lastCmd = { l: 0, r: 0 };
      return { left: 0, right: 0, drill: false };
    }
    // integral hold: push back against any measured creep
    mem.holdU = clamp(mem.holdU - 0.6 * vAvg * dt, -0.4, 0.4);
    mem.lastCmd = { l: mem.holdU, r: mem.holdU };
    return { left: mem.holdU, right: mem.holdU, drill: true };
  };

  const startRec = () => {
    mem.rec = { ph: 0, t0: t, side: sideSign };
    mem.stk = null;
  };
  const recStep = () => {
    const rc = mem.rec;
    if (rc.ph === 0 && t - rc.t0 >= 1.0) { rc.ph = 1; rc.t0 = t; }
    if (rc.ph === 1 && t - rc.t0 >= 0.9) { mem.rec = null; mem.recT = t; return setW(0, 0); }
    return rc.ph === 0 ? setW(-0.25, 0) : setW(0, 0.9 * rc.side);
  };

  const recentBumps = () =>
    mem.bumpPts.filter((b) => t - b.t < 200 && hyp(b.x - mem.px, b.y - mem.py) < 5).length;

  // ================= main flow =================

  // 1. recovery manoeuvre
  if (mem.rec) return recStep();

  // 2. drilling in progress
  if (mem.drill) return drillStep();

  // 3. bump handling
  if (bumped && t - mem.recT > 1.2) {
    mem.bumpPts.push({ x: mem.px, y: mem.py, t });
    if (mem.bumpPts.length > 60) mem.bumpPts.shift();
    if (recentBumps() >= 3) {
      if (mem.app) { mem.failed.push({ x: mem.app.x, y: mem.app.y }); mem.app = null; }
      if (mem.goal && mem.goal.h) mem.goal.h.st = 2;
      mem.goal = null; mem.search = null;
    }
    startRec();
    return recStep();
  }

  // 4. stuck detection (commanded to move but not moving)
  const cmdSp = (mem.lastCmd.l + mem.lastCmd.r) / 2;
  if (cmdSp > 0.15) {
    if (!mem.stk || hyp(mem.px - mem.stk.x, mem.py - mem.stk.y) > 0.6) mem.stk = { x: mem.px, y: mem.py, t };
    else if (t - mem.stk.t > 7) { mem.stk = null; startRec(); return recStep(); }
  } else {
    mem.stk = null;
  }

  // 5. energy and delivery modes
  const dBase = hyp(mem.bx - mem.px, mem.by - mem.py);
  const dHome = beacon ? beacon.distance : dBase;
  if (mem.mode === 'hunt') {
    const full = carried >= cap;
    const timeOut = carried > 0 && timeLeft < dBase / 0.3 + 90;
    const nearBase3 = carried >= 3 && dBase < 60;
    const deliver = carried > 0 && (full || timeOut || nearBase3) && t - mem.dockFailT > 60;
    if (deliver || battery < 0.2) {
      mem.mode = 'home';
      mem.homeWhy = carried > 0 ? 'cargo' : 'battery';
      mem.goal = null; mem.search = null; mem.app = null; mem.dockT = null;
    }
  }
  if (mem.mode === 'home') {
    if (dHome < 2.5) {
      if (mem.dockT === null) mem.dockT = t;
      const wt = t - mem.dockT;
      const done = carried === 0 && (mem.homeWhy !== 'battery' || battery > 0.5 || wt > 60);
      if (done || wt > 30) {
        if (carried > 0) mem.dockFailT = t;
        mem.mode = 'hunt'; mem.dockT = null; mem.homeWhy = ''; mem.goal = null;
      } else {
        return setW(0, 0);
      }
    } else {
      mem.dockT = null;
      if (beacon) return approachRel(beacon.distance, num(beacon.bearing, 0) * D, 0.5);
      return driveTo(mem.bx, mem.by, 0.6);
    }
  }

  // 6. visible site: approach and drill
  if (site && mem.mode === 'hunt' && carried < cap) {
    const sd = site.distance;
    const sb = num(site.bearing, 0) * D;
    const sx = mem.px + sd * Math.cos(hdR + sb);
    const sy = mem.py + sd * Math.sin(hdR + sb);
    const known = mem.samples.some((p) => hyp(p.x - sx, p.y - sy) < 5) ||
      mem.failed.some((p) => hyp(p.x - sx, p.y - sy) < 5);
    if (!known) {
      if (!mem.app || hyp(mem.app.x - sx, mem.app.y - sy) > 6) mem.app = { x: sx, y: sy, t0: t };
      if (t - mem.app.t0 > 80) {
        mem.failed.push({ x: sx, y: sy });
        mem.app = null;
      } else if (sd <= 1.4) {
        startDrill(sx, sy);
        return drillStep();
      } else {
        return approachRel(sd, sb, 0.35);
      }
    }
  }

  // 7. initial straight run to calibrate compass offset from GPS course
  if (!mem.hOffSet && t < 40 && mem.mode === 'hunt' && carried === 0 && !site) {
    if (front < 3) return setW(0, 0.6 * sideSign);
    return setW(0.35, 0);
  }

  // 8. active search around a hint or science peak
  if (mem.search) return searchStep();

  // 9. strong science here: search for the source
  if (mem.mode === 'hunt' && science > 1.0 && carried < cap && t - mem.lastSearchT > 40 &&
      !mem.searched.some((p) => hyp(p.x - mem.px, p.y - mem.py) < 10)) {
    startSearch(mem.px, mem.py, null, 5);
    mem.lastSearchT = t;
    return searchStep();
  }

  // 10. goal selection and navigation
  if (!mem.goal) {
    const h = pickHint();
    if (h) {
      mem.goal = { kind: 'hint', h, x: h.x, y: h.y, t0: t, tmax: 60 + 3 * hyp(h.x - mem.px, h.y - mem.py) };
    } else {
      const p = pickExplore();
      mem.goal = { kind: 'explore', h: null, x: p.x, y: p.y, t0: t, tmax: 40 + 3 * hyp(p.x - mem.px, p.y - mem.py) };
    }
  }
  const g = mem.goal;
  if (g.h && g.h.st !== 0) { mem.goal = null; return setW(0, 0); }
  if (t - g.t0 > g.tmax) {
    if (g.h) g.h.st = 2;
    mem.goal = null;
    return setW(0, 0);
  }
  if (hyp(g.x - mem.px, g.y - mem.py) < 5) {
    if (g.kind === 'hint') { startSearch(g.x, g.y, g.h, 6); return searchStep(); }
    mem.goal = null;
    return setW(0, 0);
  }
  return driveTo(g.x, g.y, 0.6);
}
